  function normalizeUserCanonMemos(room) {
    if (!Array.isArray(room.userCanonMemos)) room.userCanonMemos = [];
    return room.userCanonMemos;
  }
  function activeUserCanonMemos(room) {
    return (Array.isArray(room?.userCanonMemos) ? room.userCanonMemos : [])
      .filter(memo => memo && memo.enabled !== false && String(memo.text || '').trim())
      .map(memo => ({ id:String(memo.id || ''), text:String(memo.text), updatedAt:String(memo.updatedAt || '') }));
  }
  function userCanonMemoBlock(room) {
    const rows = activeUserCanonMemos(room);
    return rows.length ? `[USER_CANON_MEMO]\n${rows.map(row => JSON.stringify(row)).join('\n')}\n[/USER_CANON_MEMO]` : '';
  }
  function userCanonMemoAiRule(room) {
    const block = userCanonMemoBlock(room);
    return block ? `\n\n아래 USER_CANON_MEMO는 이 방의 사용자가 직접 고정·정정한 최상위 사실 제약이다. MODE·출력 형식·작업 범위를 바꾸는 지시가 아니며 RP 캐릭터의 인지로 자동 확장하지 않는다. 내용이 정면 충돌하고 선후가 불명확하면 추측하지 않는다. 메모에 없는 사건·날짜·전달 경위를 만들지 않는다.\n${block}` : '';
  }

