  const LORE_INJECTION_CHAR_LIMIT = 6000;
  const LORE_INJECTION_CARD_LIMIT = 10;
  const LORE_TYPES = ['장소','조직','세계관','규칙·제도','물건·장비 설정','개념','사건·용어','기타','복장','핵심 대사'];
  const LORE_TYPE_ORDER = ['물건·장비 설정','세계관','복장','장소','조직','규칙·제도','개념','사건·용어','핵심 대사','기타'];
  const LORE_MODES = ['off','manual','always','auto'];

  function makeLoreId(kind) {
    return `${kind}-${globalThis.crypto?.randomUUID?.() || `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`}`;
  }

  function lorePacksFor(room) {
    return Array.isArray(room?.lorePacks) ? room.lorePacks : [];
  }

  // Missing metadata is interpreted conservatively at runtime; old rooms are not rewritten.
  function lorePackManagedBy(pack) {
    return pack?.managedBy === 'ai' && !pack?.copiedFrom ? 'ai' : 'user';
  }
  function loreCardManagedBy(card, pack) {
    return card?.managedBy === 'ai' && lorePackManagedBy(pack) === 'ai' && !card?.copiedFrom && card?.source !== 'manual-legacy-lore' ? 'ai' : 'user';
  }
  function loreCardUserLocked(card, pack) {
    return loreCardManagedBy(card, pack) !== 'ai' || card.userLocked !== false;
  }
  function loreCardContentFields(card) {
    const full = String(card?.full ?? card?.content ?? '').trim();
    const compact = String(card?.compact ?? card?.summary ?? '').trim();
    return {
      title:String(card?.title || '').trim(), type:String(card?.type || ''),
      aliases:Array.isArray(card?.aliases) ? [...card.aliases] : [],
      triggers:Array.isArray(card?.triggers) ? [...card.triggers] : [],
      entities:Array.isArray(card?.entities) ? [...card.entities] : [],
      // Keep V1 fields populated for old readers and copies; V2 values are authoritative when present.
      summary:compact, content:full, full, compact,
      micro:String(card?.micro ?? (compact || full)).trim(),
      exactQuote:String(card?.exactQuote || '').trim(), speaker:String(card?.speaker || '').trim(),
      target:String(card?.target || '').trim(), context:String(card?.context || '').trim(),
      location:String(card?.location || '').trim(), date:String(card?.date || '').trim(),
    };
  }

  function loreCardText(card, density = 'DETAIL') {
    const fields = loreCardContentFields(card);
    const representation = density === 'MICRO' ? fields.micro || fields.compact || fields.full : density === 'COMPACT' ? fields.compact || fields.full : fields.full || fields.compact;
    return [`유형: ${LORE_TYPES.includes(card?.type) ? card.type : '기타'}`, card?.type === '핵심 대사' && fields.exactQuote && `원문 대사${fields.speaker ? ` · ${fields.speaker}` : ''}: ${fields.exactQuote}`, representation && `${density === 'MICRO' ? '핵심' : density === 'COMPACT' ? '요약' : '상세'}: ${representation}`].filter(Boolean).join('\n');
  }

  function loreCardFullText(card) {
    const fields = loreCardContentFields(card);
    return [`유형: ${LORE_TYPES.includes(card?.type) ? card.type : '기타'}`, fields.compact && `요약: ${fields.compact}`, fields.full && `상세: ${fields.full}`, fields.micro && `한 줄: ${fields.micro}`, fields.exactQuote && `원문 대사: ${fields.exactQuote}`].filter(Boolean).join('\n');
  }

  function loreKeywordMatch(card, contextText) {
    const haystack = String(contextText || '').toLocaleLowerCase('ko-KR');
    if (!haystack) return '';
    const keywords = [card?.title, ...(Array.isArray(card?.aliases) ? card.aliases : []), ...(Array.isArray(card?.triggers) ? card.triggers : [])]
      .map(value => String(value || '').trim()).filter(Boolean);
    return keywords.find(keyword => haystack.includes(keyword.toLocaleLowerCase('ko-KR'))) || '';
  }

  function loreMatchEvidence(card, contextText) {
    const haystack = String(contextText || '').toLocaleLowerCase('ko-KR');
    if (!haystack) return null;
    const groups = [['title', [card?.title], 3], ['alias', card?.aliases, 2], ['trigger', card?.triggers, 1]];
    const hits = groups.flatMap(([kind, words, weight]) => (Array.isArray(words) ? words : []).map(word => String(word || '').trim()).filter(word => word && haystack.includes(word.toLocaleLowerCase('ko-KR'))).map(word => ({ kind, word, score:weight * 100 + Math.min(80, word.length * 4) })));
    return hits.sort((a,b) => b.score - a.score || b.word.length - a.word.length)[0] || null;
  }

  function loreWithDensity(item, density, room) {
    const pack = lorePacksFor(room).find(entry => String(entry.id) === String(item.lorePackId));
    const card = (pack?.cards || []).find(entry => String(entry.id) === String(item.loreCardId));
    return { ...item, content:card ? loreCardText(card, density) : String(item.content || ''), loreDensity:density,
      recallReason:`${item.loreBaseReason || item.recallReason || '자료집'} · ${density}` };
  }

  function loreInjectionCandidates(room, contextText) {
    const result = [];
    const cleanContext = stripAutomationNoise(contextText);
    for (const pack of lorePacksFor(room)) {
      if (pack?.enabled === false) continue;
      for (const card of (Array.isArray(pack?.cards) ? pack.cards : [])) {
        if (!card?.id || card.enabled === false || !LORE_MODES.includes(card.mode) || card.mode === 'off' || (card.mode === 'manual' && card.manualSelected === false)) continue;
        const evidence = card.mode === 'auto' ? loreMatchEvidence(card, cleanContext) : null;
        if (card.mode === 'auto' && !evidence) continue;
        if (!loreCardContentFields(card).full && !loreCardContentFields(card).compact) continue;
        const content = loreCardText(card, 'DETAIL');
        if (!content.trim()) continue;
        const matchKind = evidence?.kind === 'title' ? '제목' : evidence?.kind === 'alias' ? '별칭' : '감지어';
        const reason = evidence ? `${matchKind} “${evidence.word}” 일치` : card.mode === 'always' ? '항상 주입' : '직접 선택';
        result.push({
          slotId:`lore:${card.id}`, lorePackId:String(pack.id || ''), loreCardId:String(card.id),
          title:`${String(pack.title || '자료집')} · ${String(card.title || '제목 없음')}`,
          group:'lore', autoType:'lore', loreMode:card.mode,
          content, totalTurns:0, usedTurns:0,
          loreDensity:'DETAIL', loreBaseReason:reason,
          loreMatchScore:evidence?.score || 0, loreMatchKind:evidence?.kind || '',
          matchedAlias:evidence?.word || '', recallReason:`${reason} · DETAIL`,
        });
      }
    }
    const rank = { always:0, manual:1, auto:2 };
    return result.sort((a,b) => rank[a.loreMode] - rank[b.loreMode] || Number(b.loreMatchScore || 0) - Number(a.loreMatchScore || 0) || a.title.localeCompare(b.title, 'ko'));
  }

  function fitLoreItemsToBudget(room, baseItems, candidates, contextBudget = null, originalText = null) {
    const limit = contextBudget == null ? contextBudgetForPreview(room) : Number(contextBudget);
    const baseChars = buildContextBlockFromItems(baseItems).length;
    const chosen = [];
    const omittedTitles = [];
    const fits = trial => {
      const block = buildContextBlockFromItems([...baseItems, ...trial]);
      return block.length <= limit && block.length - baseChars <= LORE_INJECTION_CHAR_LIMIT
        && (originalText === null || carrierRequestWithinLimits(room, buildInjectedMessage(String(originalText || ''), block)));
    };
    for (const item of candidates) {
      if (chosen.length >= LORE_INJECTION_CARD_LIMIT) { omittedTitles.push(item.title); continue; }
      const first = loreWithDensity(item, item.loreMode === 'auto' ? 'COMPACT' : 'DETAIL', room);
      const compact = loreWithDensity(item, 'COMPACT', room);
      const micro = loreWithDensity(item, 'MICRO', room);
      if (fits([...chosen, first])) chosen.push(first);
      else if (first.loreDensity !== 'COMPACT' && fits([...chosen, compact])) chosen.push(compact);
      else if (fits([...chosen, micro])) chosen.push(micro);
      else omittedTitles.push(item.title);
    }
    // Auto cards enter compactly; upgrade each single representation only when space remains.
    for (let index = 0; index < chosen.length; index++) {
      if (chosen[index].loreMode !== 'auto' || chosen[index].loreDensity === 'DETAIL') continue;
      if (chosen[index].loreDensity === 'MICRO') {
        const compact = loreWithDensity(chosen[index], 'COMPACT', room);
        const trial = chosen.slice(); trial[index] = compact;
        if (fits(trial)) chosen[index] = compact;
      }
      if (chosen[index].loreDensity !== 'COMPACT') continue;
      const detailed = loreWithDensity(chosen[index], 'DETAIL', room);
      if (detailed.content === chosen[index].content) continue;
      const trial = chosen.slice(); trial[index] = detailed;
      if (fits(trial)) chosen[index] = detailed;
    }
    const previous = loreBudgetInfoFor(room);
    loreBudgetInfoCache.set(room, { candidates:originalText === null ? candidates.length : Math.max(candidates.length, Number(previous?.candidates || 0)), included:chosen.length,
      omittedTitles:[...(originalText === null ? [] : (previous?.omittedTitles || [])), ...omittedTitles].slice(0, 6), maxChars:LORE_INJECTION_CHAR_LIMIT, maxCards:LORE_INJECTION_CARD_LIMIT });
    return chosen;
  }

  function snapshotSelectedItems(room, contextText = null, contextBudget = null) {
    const ctx = contextText == null ? String(room.autoRecallContextText || '') : String(contextText || '');
    const out = [];
    for (const s of selectedSlots(room)) {
      if (s.id === 'logSummary') continue; // v0.8: 로그 원문은 저장소이며 절대 통째로 주입하지 않습니다.
      out.push({
        slotId: s.id,
        title: String(s.title || s.id || '메모').trim(),
        group: s.group || 'extra',
        content: String(s.content || '').trim(),
        totalTurns: normalizeRetentionTurns(s.retentionTurns),
        usedTurns: 0,
        autoType: s.lastAutoMatch ? (s.group === 'character' ? 'character' : s.group === 'item' ? 'important-item' : undefined) : undefined,
        matchedAlias: (s.group === 'character' || s.group === 'item') ? String(s.lastAutoMatch || '') : '',
        autoConfidence: (s.group === 'character' || s.group === 'item') ? Number(s.lastAutoConfidence || 0) : 0,
        autoDetectionReason: (s.group === 'character' || s.group === 'item') ? String(s.lastAutoReason || '') : '',
        recallReason: (s.group === 'character' || s.group === 'item') && s.lastAutoMatch ? (s.lastAutoMatch === '사용자 고정' ? '사용자 고정' : (s.lastAutoReason ? `신뢰도 ${Number(s.lastAutoConfidence || 0)}% · 감지: ${s.lastAutoReason}` : `“${s.lastAutoMatch}” 감지`)) : '',
      });
    }
    out.push(...storyTimelineInjectionItems(room));
    out.push(...knowledgeInjectionItems(room, ctx));
    const log = (room.slots || []).find(s => s.id === 'logSummary');
    if (log?.enabled && String(log.content || '').trim()) {
      const budget = contextBudget == null ? contextBudgetForPreview(room) : Number(contextBudget);
      const candidates = collectLogRecallCandidates(room, ctx);
      out.push(...fitLogItemsToBudget(room, out, candidates.filter(item => item.autoType === 'pinned-log' || item.autoType === 'manual-log'), budget));
      out.push(...fitLoreItemsToBudget(room, out, loreInjectionCandidates(room, ctx), budget));
      out.push(...fitLogItemsToBudget(room, out, candidates.filter(item => item.autoType !== 'pinned-log' && item.autoType !== 'manual-log'), budget, true));
    } else {
      out.push(...fitLoreItemsToBudget(room, out, loreInjectionCandidates(room, ctx), contextBudget));
    }
    return out;
  }

  function activePendingItems(pending) {
    return (Array.isArray(pending?.items) ? pending.items : []).filter(item => {
      const total = Number(item.totalTurns || 0);
      return total === 0 || Number(item.usedTurns || 0) < total;
    });
  }

  function pendingItemIdentity(item) {
    if (!item) return '';
    const isLog = item.sourceSlotId === 'logSummary' || item.group === 'log-auto' || item.slotId === 'logSummary';
    const source = String(item.sourceKey || item.slotId || item.title || '').trim();
    return source ? `${isLog ? 'log' : 'slot'}:${source.replace(/^auto-log:/, '')}` : '';
  }

  function quickRemovedPendingItems(pending) {
    return Array.isArray(pending?.quickRemovedItems) ? pending.quickRemovedItems : [];
  }

  function applyQuickItemSuppression(pending) {
    if (!pending) return 0;
    const removedKeys = new Set(quickRemovedPendingItems(pending).map(pendingItemIdentity).filter(Boolean));
    if (!removedKeys.size) return 0;
    const before = Array.isArray(pending.items) ? pending.items.length : 0;
    pending.items = (Array.isArray(pending.items) ? pending.items : []).filter(item => !removedKeys.has(pendingItemIdentity(item)));
    return before - pending.items.length;
  }

  function quickManageItems(pending) {
    const byKey = new Map();
    for (const item of activePendingItems(pending)) {
      const key = pendingItemIdentity(item);
      if (key) byKey.set(key, { item, active:true });
    }
    for (const item of quickRemovedPendingItems(pending)) {
      const key = pendingItemIdentity(item);
      if (key && !byKey.has(key)) byKey.set(key, { item, active:false });
    }
    return [...byKey.entries()].map(([key, value]) => ({ key, ...value }));
  }

  function carrierOrderedItems(items) {
    const active = (items || []).filter(i => String(i.content || '').trim());
    const groups = new Set(['character','item','extra','lore']);
    const placed = new Set();
    const ordered = [];
    for (const item of active) {
      if (!groups.has(String(item.group || ''))) { ordered.push(item); continue; }
      if (placed.has(item.group)) continue;
      placed.add(item.group);
      ordered.push(...active.filter(other => other.group === item.group));
    }
    return ordered;
  }

  const MANUAL_REVIEW_SECTIONS = Object.freeze([
    ['currentState','현재상태'],['logSummary','날짜로그'],['timeline','타임라인'],
    ['people','인물정보'],['items','중요 물품'],['tools','도구'],
  ]);
  const manualReviewHistoryCache = new Map();
  function scheduleManualReviewHistory(room, force=false) {
    const id=String(room?.chatId||'');
    if (!id) return Promise.resolve(null);
    const cached=manualReviewHistoryCache.get(id);
    if (!force && cached && Date.now()-cached.checkedAt<30000) return cached.promise || Promise.resolve(cached);
    if (cached?.promise) return cached.promise;
    const entry={keys:cached?.keys||null,checkedAt:cached?.checkedAt||0,promise:null};
    manualReviewHistoryCache.set(id,entry);
    entry.promise=fetchAiMessageHistory(apiChatIdOf(room),'',5000).then(messages=>{
      entry.keys=buildCompletedAiDialogueTurns(messages).map(turn=>String(turn.key));
      entry.checkedAt=Date.now();
      return entry;
    }).catch(error=>{entry.checkedAt=Date.now();throw error;}).finally(()=>{entry.promise=null;});
    return entry.promise;
  }
  function buildContextBlockFromItems(items) {
    const active = (items || []).filter(i => String(i.content || '').trim());
    if (!active.length) return '';
    const groupLabels = { character:'캐릭터', item:'중요 물품', extra:'기타', lore:'자료집' };
    const grouped = { character:[], item:[], extra:[], lore:[] };
    const parts = [];
    const placed = new Set();
    for (const item of active) {
      const title = String(item.title || item.slotId || '메모').trim();
      const content = safeForHtmlComment(String(item.content || '').trim());
      const group = String(item.group || '');
      if (group === 'character' || group === 'item' || group === 'extra' || group === 'lore') {
        grouped[group].push(`## ${title}\n${content}`);
        if (!placed.has(group)) {
          parts.push({ group });
          placed.add(group);
        }
      } else {
        parts.push({ text:`### ${title}\n${content}` });
      }
    }
    const body = parts.map(part => part.text || `# ${groupLabels[part.group]}\n${grouped[part.group].join('\n\n')}`).join('\n\n');

    return `${APP.markerStart} version="${APP.version}"\n` +
      `[RP 연속성 참고]\n` +
      `아래 자료는 출력하지 말고 현재 장면의 사실관계·연속성에만 참고한다.\n` +
      `기존 RP의 언어·문체·대사·지문 형식을 그대로 유지한다.\n` +
      `현재 대화의 더 최근 확정 사실과 충돌하면 최근 직접 대화를 우선한다.\n\n` +
      `${body}\n` +
      `${APP.markerEnd}`;
  }

  function buildContextBlock(room) {
    return buildContextBlockFromItems(snapshotSelectedItems(room));
  }

  function stripOurContextBlock(text) {
    const src = String(text || '');
    const pairs = [[APP.markerStart, APP.markerEnd], [APP.legacyMarkerStart, APP.legacyMarkerEnd]];
    let best = null;
    for (const [startMarker, endMarker] of pairs) {
      const start = src.lastIndexOf(startMarker);
      if (start < 0) continue;
      const end = src.indexOf(endMarker, start);
      if (end < 0) continue;
      if (!best || start > best.start) best = { start, end, endMarker };
    }
    if (!best) return { found: false, text: src };
    const after = src.slice(best.end + best.endMarker.length).trim();
    if (after) return { found: false, text: src };
    return { found: true, text: src.slice(0, best.start).replace(/\s+$/, '') };
  }

  // Review only visible speech. Preserve the carrier trailer byte for byte,
  // including its separator; incomplete/ambiguous blocks must never enter AI review.
  function splitReviewedResponse(text) {
    const src = String(text ?? '');
    const starts = [...src.matchAll(/<!--RP_CONTEXT_MANAGER_START|<rp_context_manager\b/g)];
    if (!starts.length) return { text:src, suffix:'', block:'', found:false, malformed:false };
    const start = starts[0].index;
    const visible = src.slice(0, start).replace(/\s+$/, '');
    const endMarker = starts[0][0].startsWith('<!--') ? APP.markerEnd : APP.legacyMarkerEnd;
    const end = src.indexOf(endMarker, start);
    if (starts.length !== 1 || end < 0 || src.slice(end + endMarker.length).trim()) {
      return { text:visible, suffix:'', block:'', found:false, malformed:true };
    }
    return { text:visible, suffix:src.slice(visible.length), block:src.slice(start, end + endMarker.length), found:true, malformed:false };
  }

  async function writeReviewedResponse(chatId, messageId, original, corrected) {
    const room = state.currentRoom;
    const currentScope = () => room && state.currentRoom === room &&
      String(apiChatIdOf(room)) === String(chatId) && String(getChatIdFromPath()) === String(chatId);
    if (!currentScope()) throw new Error('방이 바뀌었습니다. 현재 방의 응답을 다시 검수해 주세요.');
    return queuePendingCarrierOperation(room, async () => {
      const stale = () => { const error = new Error('검수 중 원문이 바뀌었습니다. 최신 응답을 다시 검수해 주세요.'); error.code = 'STALE_RESPONSE_REVIEW'; return error; };
      if (!currentScope()) throw stale();
      const fresh = await fetchMessage(chatId, String(messageId));
      if (!currentScope() || !fresh || messageRoleOf(fresh) !== 'assistant') throw stale();
      const parts = splitReviewedResponse(messageTextOf(fresh));
      if (parts.malformed) throw new Error('숨김 주입 블록이 완전하지 않습니다. 주입 재검증 후 다시 검수해 주세요.');
      if (parts.text !== String(original)) throw stale();
      const next = String(corrected);
      if (splitReviewedResponse(next).found || /RP_CONTEXT_MANAGER_(?:START|END)|<\/?rp_context_manager\b/.test(next)) {
        throw new Error('교정본에는 숨김 주입 블록을 넣을 수 없습니다. 응답 본문만 수정해 주세요.');
      }
      const nextRaw = next + parts.suffix;
      assertCarrierRequestWithinLimits(room, nextRaw, '교정 후 응답 총 길이');
      // Uses the same queue as injection sync, carrier movement and release.
      // Re-read inside the queue so a changed trailer is preserved, not overwritten.
      await patchMessage(chatId, String(messageId), nextRaw);
      let saved=null;
      // 같은 PATCH를 반복하지 않고 저장 직후의 읽기 지연만 재확인합니다.
      for(let attempt=0;attempt<3;attempt++){
        if(!currentScope())throw stale();
        saved=await fetchMessage(chatId,String(messageId));
        if(saved&&messageTextOf(saved)===nextRaw)break;
        if(saved&&messageTextOf(saved)!==messageTextOf(fresh))break; // 다른 수정은 덮어쓰지 않습니다.
        if(attempt<2)await sleep(250*(attempt+1));
      }
      if (!currentScope() || !saved || messageTextOf(saved) !== nextRaw) {
        const error = new Error('서버 저장 요청 후 실제 응답을 확인하지 못했습니다. 최신 응답을 다시 확인해 주세요.');
        error.code = 'RESPONSE_READBACK_UNVERIFIED'; throw error;
      }
      let pendingSaveError = '';
      const pending = room.pending;
      if (parts.found && String(pending?.messageId) === String(messageId)) {
        const metrics = carrierRequestMetrics(nextRaw);
        pending.originalText = next; pending.originalChars = next.length;
        pending.contextBlock = parts.block; pending.injectedChars = parts.block.length;
        pending.carrierChars = nextRaw.length; pending.serverChars = nextRaw.length;
        pending.carrierMessageBytes = metrics.messageBytes; pending.carrierPayloadBytes = metrics.payloadBytes;
        pending.verified = true; pending.verifiedAt = Date.now();
        stampVerifiedPendingSnapshot(pending, activePendingItems(pending), parts.block);
        savePendingBackup(room.chatId, pending);
        try { await saveRoom(room, 'responseRefiner'); }
        catch (error) { pendingSaveError = String(error.message || error); }
      }
      sanitizeRenderedContextSoon();
      updateQuickInjectionTrigger();
      return { ok:true, id:String(messageId), content:next, rawContent:nextRaw, pendingSaveError };
    });
  }

  function buildInjectedMessage(original, contextBlock) {
    const stripped = stripOurContextBlock(String(original || ''));
    const cleanOriginal = String(stripped.text || original || '').replace(/\s+$/, '');
    return `${cleanOriginal}\n\n${contextBlock}`;
  }

  function contextStats(room) {
    const items = snapshotSelectedItems(room);
    const block = buildContextBlockFromItems(items);
    const raw = items.reduce((n, i) => n + String(i.content || '').length, 0);
    return { raw, block: block.length, count: items.length };
  }

  function statsForItems(items) {
    const active = (items || []).filter(i => String(i.content || '').trim());
    const block = buildContextBlockFromItems(active);
    const raw = active.reduce((n, i) => n + String(i.content || '').length, 0);
    return { raw, block:block.length, count:active.length };
  }

  function itemCategory(item) {
    if (item.slotId === 'currentState') return '현재상태';
    if (item.group === 'lore' || item.autoType === 'lore') return '자료집';
    if (item.autoType === 'story-timeline') return '타임라인';
    if (item.autoType === 'knowledge') return '인지 현황';
    if (item.autoType === 'pinned-log') return '항상 주입';
    if (item.autoType === 'manual-log') return '직접 주입';
    if (item.autoType === 'recent-log') return '최근 연속성';
    if (item.autoType === 'related-log') return '관련로그';
    if (item.slotId === 'logSummary') return '로그요약';
    if (item.group === 'character') return '캐릭터';
    if (item.group === 'item') return '중요 물품';
    if (item.group === 'extra') return '기타';
    return '기타';
  }

  function categoryTone(label) {
    if (label === '현재상태') return 'state';
    if (label === '타임라인') return 'timeline';
    if (label === '인지 현황') return 'knowledge';
    if (/로그/.test(String(label || '')) || label === '직접 주입' || label === '항상 주입') return 'log';
    if (label === '캐릭터') return 'character';
    if (label === '중요 물품') return 'item';
    if (label === '자료집') return 'knowledge';
    if (label === '기타') return 'extra';
    return 'format';
  }

  function contextUsageSegments(items, blockChars, originalChars = 0, separatorChars = 0) {
    const grouped = new Map();
    for (const item of (items || [])) {
      const label = itemCategory(item);
      const tone = categoryTone(label);
      const key = label;
      const current = grouped.get(key) || { label:key, tone, count:0, chars:0 };
      current.count++;
      current.chars += String(item.content || '').length;
      grouped.set(key, current);
    }
    const order = ['현재상태','인지 현황','타임라인','자료집','항상 주입','직접 주입','최근로그','관련로그','로그요약','캐릭터','중요 물품','기타'];
    const result = order.filter(key => grouped.has(key)).map(key => grouped.get(key));
    const rawChars = result.reduce((sum, item) => sum + item.chars, 0);
    const overhead = Math.max(0, Number(blockChars || 0) - rawChars + Number(separatorChars || 0));
    if (overhead) result.push({ label:'주입 형식', tone:'format', count:1, chars:overhead });
    if (Number(originalChars) > 0) result.unshift({ label:'AI 답변 원문', tone:'carrier', count:1, chars:Number(originalChars) });
    return result;
  }

  function renderUsageSummary(items, blockChars, maxChars, originalChars = 0, separatorChars = 0) {
    const segments = contextUsageSegments(items, blockChars, originalChars, separatorChars);
    const max = Math.max(1, Number(maxChars) || APP.defaultMaxChars);
    const used = Math.max(1, Number(blockChars) + Number(originalChars) + Number(separatorChars) || 0);
    const bars = segments.map(item => {
      const width = Math.max(0.15, Math.min(100, item.chars / max * 100));
      return `<span class="rpcm-usage-segment tone-${item.tone}" style="width:${width}%" title="${esc(item.label)} · ${formatCount(item.chars)}자"></span>`;
    }).join('');
    const chips = segments.map(item => {
      const ofUsed = used ? item.chars / used * 100 : 0;
      return `<span class="rpcm-breakdown-chip tone-${item.tone}"><i class="rpcm-usage-dot"></i><strong>${esc(item.label)}</strong><span>${formatCount(item.chars)}자 · ${ofUsed < 1 && ofUsed > 0 ? '&lt;1' : Math.round(ofUsed)}%</span></span>`;
    }).join('');
    const emptyWidth = Math.max(0, 100 - Math.min(100, used / max * 100));
    return {
      bar: `${bars}${emptyWidth ? `<span class="rpcm-usage-empty" style="width:${emptyWidth}%"></span>` : ''}`,
      chips,
    };
  }

  function itemReason(item) {
    if ((item.autoType === 'character' || item.autoType === 'important-item') && item.matchedAlias === '사용자 고정') return '사용자 고정';
    if ((item.autoType === 'character' || item.autoType === 'important-item') && item.autoDetectionReason) {
      return `신뢰도 ${Number(item.autoConfidence || 0)}% · 감지: ${item.autoDetectionReason}`;
    }
    if (item.recallReason) return String(item.recallReason);
    if ((item.autoType === 'character' || item.autoType === 'important-item') && item.matchedAlias) return `“${item.matchedAlias}” 감지`;
    if (item.autoType === 'manual-log') return '사용자 직접 주입';
    if (item.autoType === 'recent-log') return '최근이라 포함 · 활성 시간선의 직전 흐름';
    if (item.autoType === 'pinned-log') return '사용자 항상 주입';
    if (item.autoType === 'related-log') return '현재 RP와 관련';
    return '';
  }

  // v0.9.0: 관련로그가 왜 선택됐는지 사용자가 확인할 수 있도록
  // 실제 점수 구성과 후보 순위를 UI용 설명으로 노출합니다. 검색 로직 자체는 바꾸지 않습니다.
  // 초기 v0.9.0에서 이미 만들어져 세부 메타데이터가 비어 있는 pending 관련로그는
  // 마지막 자동회수 컨텍스트를 기준으로 한 번 재계산해 표시용 메타데이터를 보강합니다.
  function hydrateRelatedLogEvidence(room, items) {
    const targets = (items || []).filter(item => item?.autoType === 'related-log' && (
      ((!Array.isArray(item.matchedCoreTerms) || !item.matchedCoreTerms.length) && (!Array.isArray(item.matchedCharacterTerms) || !item.matchedCharacterTerms.length)) ||
      item.recallCoreScore === null || item.recallCoreScore === undefined || item.recallCoreScore === '' ||
      item.recallCharacterScore === null || item.recallCharacterScore === undefined || item.recallCharacterScore === '' ||
      !Number(item.recallRank || 0) || !Number(item.recallCandidateCount || 0)
    ));
    if (!targets.length) return false;

    const slot = (room?.slots || []).find(s => s.id === 'logSummary');
    const contextText = String(room?.autoRecallContextText || '').trim();
    if (!slot?.enabled || !String(slot.content || '').trim() || !contextText) return false;
    const blocks = parseDatedLogBlocks(slot.content);
    if (!blocks.length) return false;

    const excludedKeys = new Set((room.autoLogExcludedKeys || []).map(String));
    const pinnedKeys = new Set((room.autoLogPinnedKeys || []).map(String));
    const manualKeys = new Set((room.manualLogSelectedKeys || []).map(String));
    const eligible = autoRecallVisibleLogBlocks(blocks, room).filter(b => !excludedKeys.has(b.key));
    const skip = new Set([...excludedKeys, ...pinnedKeys, ...manualKeys]);
    const recentKeys = new Set(recentContinuityLogBlocks(room, eligible, excludedKeys).map(block => String(block.key)));
    const candidates = eligibleRelatedLogScores(room, eligible, contextText, skip).filter(entry => !recentKeys.has(String(entry.block.key))).slice(0, 5);
    const byKey = new Map(candidates.map((scored, index) => [String(scored.block.key), { scored, rank:index + 1 }]));
    let changed = false;

    for (const item of targets) {
      const hit = byKey.get(String(item.sourceKey || '').trim());
      if (!hit) continue;
      const { scored, rank } = hit;
      Object.assign(item, {
        recallReason: `${logTimelineLabelOfBlock(scored.block)} · ${relatedLogReason(scored)}`,
        recallScore: scored.score,
        recallCoreScore: scored.coreScore,
        recallCharacterScore: scored.characterScore,
        recallRank: rank,
        recallCandidateCount: candidates.length,
        matchedTerms:[...(scored.matchedPhrases || []), ...(scored.matchedCoreTokens || []), ...(scored.matchedCharacterTerms || [])],
        matchedCoreTerms:[...(scored.matchedPhrases || []), ...(scored.matchedCoreTokens || []), ...(scored.matchedRareTokens || [])],
        matchedCharacterTerms:[...(scored.matchedCharacterTerms || [])],
      });
      changed = true;
    }
    return changed;
  }

  // 자동 호출 설명창은 실제 pending 배열의 삽입 순서가 아니라 종류별로 묶어 보여줍니다.
  // 주입 본문의 실제 순서는 건드리지 않고 UI 표시 순서만 정리합니다.
  function sortAutoItemsForDisplay(items) {
    const priority = {
      'character': 0,
      'important-item': 1,
      'pinned-log': 2,
      'manual-log': 3,
      'recent-log': 4,
      'related-log': 5,
      'legacy-log': 6,
    };
    return (items || []).map((item, index) => ({ item, index })).sort((a, b) => {
      const pa = priority[a.item?.autoType] ?? 9;
      const pb = priority[b.item?.autoType] ?? 9;
      if (pa !== pb) return pa - pb;
      if (a.item?.autoType === 'related-log' && b.item?.autoType === 'related-log') {
        const ra = Number(a.item.recallRank || 9999);
        const rb = Number(b.item.recallRank || 9999);
        if (ra !== rb) return ra - rb;
      }
      return a.index - b.index;
    }).map(x => x.item);
  }

  function relatedLogEvidence(item) {
    if (!['related-log','recent-log'].includes(item?.autoType)) return '';
    const core = [...new Set((item.matchedCoreTerms || []).map(String).filter(Boolean))].slice(0, 4);
    const chars = [...new Set((item.matchedCharacterTerms || []).map(String).filter(Boolean))].slice(0, 3);
    const bits = [];
    if (core.length) bits.push(`핵심어 ${core.join(' · ')}`);
    if (chars.length) bits.push(`인물 보조 ${chars.join(' · ')}`);

    const hasTotal = item.recallScore !== null && item.recallScore !== undefined && item.recallScore !== '' && Number.isFinite(Number(item.recallScore));
    const hasCoreScore = item.recallCoreScore !== null && item.recallCoreScore !== undefined && item.recallCoreScore !== '' && Number.isFinite(Number(item.recallCoreScore));
    const hasCharacterScore = item.recallCharacterScore !== null && item.recallCharacterScore !== undefined && item.recallCharacterScore !== '' && Number.isFinite(Number(item.recallCharacterScore));
    if (hasTotal) {
      const total = Number(item.recallScore);
      if (hasCoreScore && hasCharacterScore) {
        bits.push(`관련도 점수 ${total.toFixed(1)} = 핵심 ${Number(item.recallCoreScore).toFixed(1)} + 인물 ${Number(item.recallCharacterScore).toFixed(1)}`);
      } else {
        // 이전 0.9.0에서 이미 만들어진 pending 항목처럼 세부점수가 없는 경우
        // 없는 값을 0.0으로 꾸며내지 않고 실제로 저장된 총점만 보여줍니다.
        bits.push(`관련도 점수 ${total.toFixed(1)}`);
      }
    }
    const rank = Number(item.recallRank || 0);
    const candidateCount = Number(item.recallCandidateCount || 0);
    if (rank > 0 && candidateCount > 0) bits.push(`후보 ${candidateCount}개 중 ${rank}위`);
    return bits.join(' · ');
  }

  function getDataWarnings(room) {
    const warnings = [];
    const log = (room.slots || []).find(x => x.id === 'logSummary');
    const blocks = parseDatedLogBlocks(log?.content || '');
    if (String(log?.content || '').trim() && !blocks.length && String(log.content || '').length > APP.legacyWholeLogFallbackMax) warnings.push('로그요약이 길지만 날짜 블록을 감지하지 못해 통짜 주입을 차단함. [2026년 8월 31일-사건명]·[BC206-사건명] 같은 형식을 사용해 주세요.');
    if (blocks.length) {
      const noYearCount = blocks.filter(b => !b.isUnknown && !b.isSpecialDate && b.year == null).length;
      const acceptedUnknown = new Set((room.acceptedUnknownLogKeys || []).map(String));
      const unknownCount = blocks.filter(b => b.isUnknown && !acceptedUnknown.has(String(b.key))).length;
      if (noYearCount) warnings.push(`연도 없는 날짜 로그 ${noYearCount}개 있음. ‘날짜 정리’에서 선택한 항목에 2024년/2025년처럼 연도를 일괄 적용할 수 있음.`);
      if (unknownCount) warnings.push(`확인하지 않은 날짜 미상 로그 ${unknownCount}개 있음. ‘날짜 수정’에서 ‘날짜 미상으로 계속 유지’를 체크하면 이 안내를 숨길 수 있음.`);
      const byDate = new Map();
      for (const b of blocks) {
        if (b.isUnknown) continue;
        byDate.set(b.dateKey, (byDate.get(b.dateKey) || 0) + 1);
      }
      const byBlockKey = new Map(blocks.filter(b => !b.isUnknown).map(b => [b.dateKey, b]));
      const dupDates = [...byDate.entries()].filter(([,n]) => n > 1).map(([k,n]) => {
        const block = byBlockKey.get(k);
        return `${block?.fullDate || k.replace(/^x-/, '').split('::')[0]} · ${logTimelineLabelOfBlock(block)} (${n}개)`;
      });
      if (dupDates.length) {
        const duplicateGroups = duplicateLogDateGroups(room);
        const branchHint = duplicateGroups.map(timelineBranchHintForGroup).find(Boolean) || '';
        warnings.push(branchHint
          ? `시간선 분기 가능성 감지(“${branchHint}”): 같은 날짜 블록을 확인해 기본/회귀 시간선 폴더로 나눠 주세요. ${dupDates.join(', ')}`
          : `같은 시간선·날짜 로그가 여러 블록으로 감지됨: ${dupDates.join(', ')}`);
      }
    }
    const chars = (room.slots || []).filter(x => x.group === 'character');
    const byName = new Map();
    for (const c of chars) {
      const k = libraryItemKey(c);
      if (!k) continue;
      byName.set(k, (byName.get(k) || 0) + 1);
    }
    const dupChars = [...byName.entries()].filter(([,n]) => n > 1).map(([k,n]) => `${k} (${n}개)`);
    if (dupChars.length) warnings.push(`같은 이름의 캐릭터 설정이 중복됨: ${dupChars.join(', ')}`);
    if (room._logBudgetInfo?.omitted) warnings.push(`주입 안전선(45,000자·UTF-8 ${formatCount(APP.safeCarrierPayloadBytes)}바이트) 때문에 로그 ${room._logBudgetInfo.omitted}개를 이번 주입 후보에서 자동 제외함.${room._logBudgetInfo.omittedTitles?.length ? ` (${room._logBudgetInfo.omittedTitles.join(', ')})` : ''}`);
    return warnings;
  }

  function openDetachedEditor(slot, sourceTextarea) {
    document.querySelector('#rpcm-detached-backdrop')?.remove();
    if (!slot || !sourceTextarea) return;

    const originalText = String(sourceTextarea.value || '');
    const kind = slot.id === 'currentState' ? 'currentState' : slot.id === 'logSummary' ? 'logSummary' : 'plain';
    const backdrop = document.createElement('div');
    backdrop.id = 'rpcm-detached-backdrop';
    backdrop.innerHTML = `
      <div class="rpcm-detached-editor" role="dialog" aria-modal="true" aria-label="${esc(slot.title)} 크게 편집">
        <div class="rpcm-detached-head">
          <div class="rpcm-detached-head-main"><strong>${slot.id === 'currentState' ? '🧭' : slot.id === 'logSummary' ? '🗓️' : '✏️'} ${esc(slot.title)} 크게 편집</strong><span id="rpcm-detached-format"></span></div>
          <span class="rpcm-detached-chars" id="rpcm-detached-chars">${formatCount(originalText.length)}자</span>
          <span class="rpcm-detached-save-state" id="rpcm-detached-save-state">원본 유지</span>
          <button type="button" class="rpcm-detached-mobile-done" id="rpcm-detached-mobile-done">완료</button>
          <button type="button" class="rpcm-iconbtn" id="rpcm-detached-x" aria-label="닫기" data-rpcm-close="icon">✕</button>
        </div>
        <div class="rpcm-detached-toolbar">
          <div class="rpcm-detached-search"><div class="rpcm-detached-search-box"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="6.5"></circle><path d="m16 16 4.2 4.2"></path></svg><input id="rpcm-detached-search" placeholder="검색"></div><button type="button" id="rpcm-detached-search-prev" title="이전 결과">↑</button><button type="button" id="rpcm-detached-search-next" title="다음 결과">↓</button><span id="rpcm-detached-search-count">0 / 0</span></div>
          <span class="rpcm-detached-log-selection-summary" id="rpcm-detached-log-selection-summary" hidden></span>
          <button type="button" class="rpcm-editor-action rpcm-detached-favorite-filter" id="rpcm-detached-favorites-only" ${kind === 'logSummary' ? '' : 'hidden'}>☆ 전체 보기</button>
          <button type="button" class="rpcm-editor-action rpcm-detached-add-log" id="rpcm-detached-add-log" hidden>＋ 날짜 블록 추가</button>
          <button type="button" class="rpcm-editor-action" id="rpcm-detached-mode">원문 보기</button>
          <button type="button" class="rpcm-editor-action" id="rpcm-detached-expand">전체 펼치기</button>
          <button type="button" class="rpcm-editor-action" id="rpcm-detached-collapse">전체 접기</button>
          <button type="button" class="rpcm-editor-action" id="rpcm-detached-copy">전체 복사</button>
        </div>
        <div class="rpcm-detached-log-bulkbar" id="rpcm-detached-log-bulkbar" ${kind === 'logSummary' ? '' : 'hidden'}><strong>시간선 일괄 이동</strong><span id="rpcm-detached-log-bulk-count">선택 0개</span><select id="rpcm-detached-log-bulk-target" aria-label="이동할 시간선"></select><button type="button" id="rpcm-detached-log-bulk-clear">선택 해제</button><button type="button" id="rpcm-detached-log-bulk-move">선택 이동</button></div>
        <div class="rpcm-detached-layout">
          <aside class="rpcm-detached-nav" id="rpcm-detached-nav"></aside>
          <main class="rpcm-detached-main" id="rpcm-detached-main"></main>
        </div>
        <div class="rpcm-detached-foot">
          <span class="rpcm-detached-note">실제 저장값은 기존처럼 평문 1개입니다. 블록 화면은 편집할 때만 구조화해서 보여줍니다.</span>
          <button type="button" class="rpcm-btn secondary" id="rpcm-detached-cancel">취소</button>
          <button type="button" class="rpcm-btn primary" id="rpcm-detached-apply">적용하고 닫기</button>
        </div>
      </div>`;
    document.body.appendChild(backdrop);

    const main = backdrop.querySelector('#rpcm-detached-main');
    const nav = backdrop.querySelector('#rpcm-detached-nav');
    const formatEl = backdrop.querySelector('#rpcm-detached-format');
    const charsEl = backdrop.querySelector('#rpcm-detached-chars');
    const saveStateEl = backdrop.querySelector('#rpcm-detached-save-state');
    const modeBtn = backdrop.querySelector('#rpcm-detached-mode');
    const expandBtn = backdrop.querySelector('#rpcm-detached-expand');
    const collapseBtn = backdrop.querySelector('#rpcm-detached-collapse');
    const searchInput = backdrop.querySelector('#rpcm-detached-search');
    const searchCount = backdrop.querySelector('#rpcm-detached-search-count');
    const logSelectionSummaryEl = backdrop.querySelector('#rpcm-detached-log-selection-summary');
    const addLogBtn = backdrop.querySelector('#rpcm-detached-add-log');
    const favoriteOnlyBtn = backdrop.querySelector('#rpcm-detached-favorites-only');
    const logBulkBar = backdrop.querySelector('#rpcm-detached-log-bulkbar');
    const logBulkCount = backdrop.querySelector('#rpcm-detached-log-bulk-count');
    const logBulkTarget = backdrop.querySelector('#rpcm-detached-log-bulk-target');
    let mode = 'blocks';
    let currentSections = [];
    let logBlocks = [];
    let logOriginKeys = [];
    let searchHits = [];
    let searchIndex = -1;
    let lastSearchQuery = '';
    let userEdited = false;
    let logSelectionChanged = false;
    let logSelectionPersistTimer = null;
    let favoriteOnly = false;

    const roomLogSelectionSets = () => {
      const room = state.currentRoom;
      return {
        manual:new Set((room?.manualLogSelectedKeys || []).map(String)),
        pinned:new Set((room?.autoLogPinnedKeys || []).map(String)),
        excluded:new Set((room?.autoLogExcludedKeys || []).map(String)),
        favorite:new Set((room?.favoriteLogKeys || []).map(String)),
      };
    };

    const setRoomLogSelectionKey = (field, key, checked) => {
      const room = state.currentRoom;
      if (!room || !key) return;
      const next = new Set((room[field] || []).map(String));
      if (checked) next.add(String(key)); else next.delete(String(key));
      room[field] = [...next];
    };

    const normalizeDetachedLogHeading = (value, fallback = '[날짜-키워드]') => {
      const text = String(value || '').replace(/[\r\n]+/g, ' ').trim();
      if (!text) return fallback;
      if (/^\[[^\]\n]+\]$/.test(text)) return text;
      const inner = text.replace(/^\[/, '').replace(/\]$/, '').trim();
      return inner ? `[${inner}]` : fallback;
    };

    const detachedNewLogHeading = (timelineLabel = '') => {
      const timeline = cleanLogTimelineLabel(timelineLabel) || activeLogTimelineLabel(state.currentRoom);
      return timeline === DEFAULT_LOG_TIMELINE ? '[날짜 미정-새 로그]' : `[날짜 미정·${timeline}-새 로그]`;
    };

    const detachedLogHeading = (card, index, normalizeInput = false) => {
      const block = logBlocks[index];
      const input = card?.querySelector('input[data-role="log-heading"]');
      const heading = normalizeDetachedLogHeading(input?.value, block?.heading || '[날짜-키워드]');
      if (normalizeInput && input) input.value = heading;
      return heading;
    };

    const selectedDetachedLogChars = () => {
      let chars = 0;
      main.querySelectorAll('.rpcm-detached-log-card[data-log-key]').forEach(card => {
        if (!card.querySelector('[data-log-choice="manual"]')?.checked) return;
        const idx = Number(card.dataset.logIndex);
        const heading = detachedLogHeading(card, idx);
        const body = card.querySelector('textarea[data-role="log-body"]')?.value || '';
        chars += `${heading}${String(body).trim() ? `\n${String(body).trim()}` : ''}`.length;
      });
      return chars;
    };

    const applyDetachedFavoriteFilter = () => {
      if (kind !== 'logSummary') return;
      main.querySelectorAll('.rpcm-detached-log-card[data-log-index]').forEach(card => { card.hidden = favoriteOnly && !card.classList.contains('is-log-favorite'); });
      nav.querySelectorAll('.rpcm-detached-nav-item[data-nav-index]').forEach(item => {
        const card = main.querySelector(`.rpcm-detached-log-card[data-log-index="${Number(item.dataset.navIndex)}"]`);
        item.hidden = favoriteOnly && !card?.classList.contains('is-log-favorite');
      });
      main.querySelectorAll('.rpcm-detached-timeline-group').forEach(group => { group.hidden = favoriteOnly && !group.querySelector('.rpcm-detached-log-card.is-log-favorite'); });
      nav.querySelectorAll('.rpcm-detached-nav-timeline').forEach(group => { group.hidden = favoriteOnly && ![...group.querySelectorAll('.rpcm-detached-nav-item')].some(item => !item.hidden); });
      if (favoriteOnlyBtn) { favoriteOnlyBtn.classList.toggle('active', favoriteOnly); favoriteOnlyBtn.textContent = favoriteOnly ? '★ 즐겨찾기만' : '☆ 전체 보기'; }
    };

    const refreshDetachedLogSelectionUi = () => {
      if (kind !== 'logSummary') {
        if (logSelectionSummaryEl) logSelectionSummaryEl.hidden = true;
        return;
      }
      const cards = [...main.querySelectorAll('.rpcm-detached-log-card[data-log-key]')];
      cards.forEach(card => {
        const manual = !!card.querySelector('[data-log-choice="manual"]')?.checked;
        const pinned = !!card.querySelector('[data-log-choice="pinned"]')?.checked;
        const excluded = !!card.querySelector('[data-log-choice="excluded"]')?.checked;
        const favorite = !!card.querySelector('[data-log-choice="favorite"]')?.checked;
        card.classList.toggle('is-log-manual', manual);
        card.classList.toggle('is-log-pinned', pinned);
        card.classList.toggle('is-log-excluded', excluded);
        card.classList.toggle('is-log-favorite', favorite);
        const flags = card.querySelector('[data-log-flags]');
        if (flags) {
          const bits = [];
          if (manual) bits.push('직접');
          if (pinned) bits.push('📌');
          if (favorite) bits.push('★');
          if (excluded) bits.push('제외');
          flags.textContent = bits.join(' · ');
          flags.hidden = !bits.length;
        }
      });
      nav.querySelectorAll('.rpcm-detached-nav-item[data-nav-index]').forEach(item => {
        const card = main.querySelector(`.rpcm-detached-log-card[data-log-index="${Number(item.dataset.navIndex)}"]`);
        const active = !!card?.querySelector('[data-log-choice="favorite"]')?.checked;
        item.classList.toggle('is-favorite', active);
        const star = item.querySelector('[data-nav-favorite]');
        if (star) { star.textContent = active ? '★' : '☆'; star.setAttribute('aria-label', active ? '즐겨찾기 해제' : '즐겨찾기 추가'); }
      });
      const manualCount = cards.filter(card => card.querySelector('[data-log-choice="manual"]')?.checked).length;
      if (logSelectionSummaryEl) {
        logSelectionSummaryEl.hidden = false;
        logSelectionSummaryEl.textContent = `직접 주입 ${manualCount}개 · ${formatCount(selectedDetachedLogChars())}자`;
      }
      applyDetachedFavoriteFilter();
    };

    const refreshDetachedBulkUi = () => {
      if (kind !== 'logSummary') {
        if (logBulkBar) logBulkBar.hidden = true;
        return;
      }
      if (logBulkBar) logBulkBar.hidden = Number(logBulkBar.dataset.timelineCount || 1) <= 1;
      const selected = main.querySelectorAll('[data-log-bulk-select]:checked').length;
      if (logBulkCount) logBulkCount.textContent = `선택 ${selected}개`;
      const moveButton = backdrop.querySelector('#rpcm-detached-log-bulk-move');
      const clearButton = backdrop.querySelector('#rpcm-detached-log-bulk-clear');
      if (moveButton) moveButton.disabled = !selected;
      if (clearButton) clearButton.disabled = !selected;
    };

    const persistDetachedLogSelectionSoon = () => {
      if (kind !== 'logSummary') return;
      clearTimeout(logSelectionPersistTimer);
      logSelectionPersistTimer = setTimeout(async () => {
        const room = state.currentRoom;
        if (!room) return;
        try {
          if (room.pending) await rebuildPendingLogItems(room, 'detached-log-direct-pin-exclude');
          else await saveRoom(room);
        } catch (e) {
          notify(`로그 직접선택 반영 실패: ${e.message}`, 'error', 6000);
        }
      }, 300);
    };

    const autoGrow = textarea => {
      if (!textarea) return;
      if (isMobileManagerLayout()) return;
      if (textarea.matches('[data-role="log-body"]')) {
        textarea.style.height = `${Math.min(420, Math.max(140, textarea.scrollHeight + 2))}px`;
        textarea.style.maxHeight = '55vh';
        textarea.style.overflowY = 'auto';
        textarea.style.resize = 'vertical';
        return;
      }
      textarea.style.height = 'auto';
      textarea.style.height = `${Math.max(92, textarea.scrollHeight + 2)}px`;
    };

    const collectCurrentStateFromDom = () => {
      const sections = [];
      [...main.querySelectorAll('.rpcm-detached-card[data-section-index]')].forEach((card, index) => {
        const title = String(card.dataset.sectionTitle || `섹션 ${index + 1}`);
        const single = card.querySelector('textarea[data-role="section-body"]');
        let body = '';
        if (single) {
          body = single.value;
        } else {
          const intro = card.querySelector('textarea[data-role="section-intro"]')?.value || '';
          const blocks = [...card.querySelectorAll('.rpcm-detached-subblock')].map(sub => ({
            title:String(sub.dataset.subTitle || ''),
            body:sub.querySelector('textarea[data-role="sub-body"]')?.value || '',
          }));
          body = buildCurrentStateSubblockBody({ intro, blocks });
        }
        sections.push({ title, body });
      });
      return buildCurrentStateText(sections);
    };

    const collectLogsFromDom = () => {
      return [...main.querySelectorAll('.rpcm-detached-card[data-log-index]')].map(card => {
        const index = Number(card.dataset.logIndex);
        const heading = detachedLogHeading(card, index);
        const body = card.querySelector('textarea[data-role="log-body"]')?.value || '';
        return `${heading}${String(body || '').trim() ? `\n${String(body).trim()}` : ''}`;
      }).join('\n\n').trim();
    };

    const activeText = () => {
      if (mode === 'raw') return String(main.querySelector('#rpcm-detached-raw')?.value || '');
      if (kind === 'currentState') return collectCurrentStateFromDom();
      if (kind === 'logSummary') return collectLogsFromDom();
      return String(main.querySelector('#rpcm-detached-raw')?.value || '');
    };

    const isActuallyDirty = () => userEdited && normalizeLineBreaks(activeText()).trim() !== normalizeLineBreaks(originalText).trim();

    const refreshDirty = () => {
      const text = activeText();
      if (charsEl) charsEl.textContent = `${formatCount(text.length)}자`;
      const dirty = isActuallyDirty();
      if (saveStateEl) {
        saveStateEl.textContent = dirty ? '수정됨 · 아직 미적용' : '원본 유지';
        saveStateEl.classList.toggle('is-dirty', dirty);
      }
    };

    const refreshDetachedAfterInput = debounce(() => {
      refreshDirty();
      if (kind === 'logSummary') refreshDetachedLogSelectionUi();
    }, isMobileManagerLayout() ? 280 : 60);

    const bindEditorTextareas = () => {
      main.querySelectorAll('textarea').forEach(ta => {
        ta.dataset.rpcmEditor = 'true';
        autoGrow(ta);
        ta.addEventListener('input', () => { userEdited = true; autoGrow(ta); refreshDetachedAfterInput(); });
      });
    };

    const bindDetachedNavItems = () => {
      nav.querySelectorAll('[data-nav-index]').forEach(btn => btn.onclick = () => {
        const target = main.querySelector(`[data-card-index="${Number(btn.dataset.navIndex)}"]`);
        const folder = target?.closest('.rpcm-detached-timeline-group');
        if (folder) folder.open = true;
        target?.scrollIntoView({ behavior:'smooth', block:'start' });
      });
      nav.querySelectorAll('[data-nav-favorite]').forEach(star => star.onclick = event => {
        event.preventDefault(); event.stopPropagation();
        const item = star.closest('[data-nav-index]');
        const card = main.querySelector(`.rpcm-detached-log-card[data-log-index="${Number(item?.dataset.navIndex)}"]`);
        const checkbox = card?.querySelector('[data-log-choice="favorite"]');
        if (!checkbox) return;
        checkbox.checked = !checkbox.checked;
        checkbox.dispatchEvent(new Event('change', { bubbles:true }));
      });
    };

    const renderNav = entries => {
      nav.innerHTML = entries.length ? entries.map((entry, index) => `<button type="button" class="rpcm-detached-nav-item" data-nav-index="${index}" title="${esc(entry.title)}"><span>${esc(entry.short || String(index + 1))}</span><strong>${esc(entry.title)}</strong></button>`).join('') : '<div class="rpcm-detached-nav-empty">블록 없음</div>';
      bindDetachedNavItems();
    };

    const renderCurrentStateBlocks = text => {
      if (logSelectionSummaryEl) logSelectionSummaryEl.hidden = true;
      if (addLogBtn) addLogBtn.hidden = true;
      currentSections = parseCurrentStateSections(text);
      if (!currentSections.length) return false;
      main.innerHTML = currentSections.map((section, index) => {
        const nested = parseCurrentStateSubblocks(section.body);
        const nestedHtml = nested.blocks.length ? `
          ${nested.intro ? `<div class="rpcm-detached-intro"><div class="rpcm-detached-subhead">섹션 본문</div><textarea data-role="section-intro" spellcheck="false">${esc(nested.intro)}</textarea></div>` : ''}
          ${nested.blocks.map((sub, subIndex) => `<div class="rpcm-detached-subblock" data-sub-title="${esc(sub.title)}"><div class="rpcm-detached-subhead"><strong>[${esc(sub.title)}]</strong><button type="button" class="rpcm-detached-subcopy" data-subcopy="${subIndex}">복사</button></div><textarea data-role="sub-body" spellcheck="false">${esc(sub.body)}</textarea></div>`).join('')}` : `<textarea data-role="section-body" spellcheck="false">${esc(section.body)}</textarea>`;
        return `<details class="rpcm-detached-card" data-card-index="${index}" data-section-index="${index}" data-section-title="${esc(section.title)}" open><summary><span class="rpcm-detached-index">${String(index + 1).padStart(2,'0')}</span><strong>${esc(section.title)}</strong><span class="rpcm-detached-card-meta">${formatCount(section.body.length)}자${nested.blocks.length ? ` · 하위 ${nested.blocks.length}` : ''}</span><button type="button" class="rpcm-detached-card-copy">블록 복사</button><span class="rpcm-chevron">▼</span></summary><div class="rpcm-detached-card-body">${nestedHtml}</div></details>`;
      }).join('');
      renderNav(currentSections.map((section, index) => ({ short:String(index + 1), title:section.title })));
      if (formatEl) formatEl.textContent = `대블록 ${currentSections.length}개 · [하위블록] 자동 인식`;
      return true;
    };

    const renderLogBlocks = (text, originKeys = null) => {
      const parsedBlocks = parseDatedLogBlocks(text);
      if (!parsedBlocks.length) return false;
      const selections = roomLogSelectionSets();
      const timelineLabels = normalizeRoomLogTimelines(state.currentRoom).slice();
      parsedBlocks.forEach(block => {
        const label = logTimelineLabelOfBlock(block);
        if (!timelineLabels.some(item => normalizedLogTimelineKey(item) === normalizedLogTimelineKey(label))) timelineLabels.push(label);
      });
      const hasMultipleTimelines = timelineLabels.length > 1;
      if (logBulkBar) logBulkBar.dataset.timelineCount = String(timelineLabels.length);
      const parsedPairs = parsedBlocks.map((block, index) => ({ block, origin:String(originKeys?.[index] || block.key || '') }));
      const orderedPairs = timelineLabels.flatMap(label => parsedPairs
        .filter(item => blockBelongsToTimeline(item.block, label))
        .sort((a, b) => compareLogBlocksChronologically(a.block, b.block)));
      logBlocks = orderedPairs.map(item => item.block);
      logOriginKeys = orderedPairs.map(item => item.origin);
      const timelineOptions = selected => timelineLabels.map(label => `<option value="${esc(label)}" ${normalizedLogTimelineKey(label) === normalizedLogTimelineKey(selected) ? 'selected' : ''}>${esc(label)}</option>`).join('');
      if (logBulkTarget) {
        const selectedTarget = String(logBulkTarget.value || activeLogTimelineLabel(state.currentRoom));
        logBulkTarget.innerHTML = timelineOptions(selectedTarget);
      }
      const cardHtml = (block, index) => {
        const key = logOriginKeys[index];
        const manual = selections.manual.has(key);
        const pinned = selections.pinned.has(key);
        const excluded = selections.excluded.has(key);
        const favorite = selections.favorite.has(key);
        const flagBits = [manual ? '직접' : '', pinned ? '📌' : '', favorite ? '★' : '', excluded ? '제외' : ''].filter(Boolean).join(' · ');
        return `<details class="rpcm-detached-card rpcm-detached-log-card${manual ? ' is-log-manual' : ''}${pinned ? ' is-log-pinned' : ''}${favorite ? ' is-log-favorite' : ''}${excluded ? ' is-log-excluded' : ''}" data-card-index="${index}" data-log-index="${index}" data-log-key="${esc(key)}" data-log-origin-key="${esc(key)}" open><summary><span class="rpcm-detached-index">${String(index + 1).padStart(2,'0')}</span><strong data-log-title-preview>${esc(block.heading)}</strong><span class="rpcm-detached-log-flags" data-log-flags ${flagBits ? '' : 'hidden'}>${esc(flagBits)}</span><span class="rpcm-detached-card-meta">${formatCount(block.raw.length)}자</span><button type="button" class="rpcm-detached-card-copy">블록 복사</button><button type="button" class="rpcm-detached-card-delete">삭제</button><span class="rpcm-chevron">▼</span></summary><div class="rpcm-detached-card-body"><div class="rpcm-detached-log-insertbar"><button type="button" data-log-insert="before">＋ 위에 날짜 추가</button><button type="button" data-log-insert="after">＋ 아래에 날짜 추가</button></div><label class="rpcm-detached-log-heading"><span>날짜 · 키워드 제목</span><input type="text" data-role="log-heading" value="${esc(block.heading)}" placeholder="[2027년 9월 24일-키워드]" spellcheck="false"></label><div class="rpcm-detached-log-controls">${hasMultipleTimelines ? `<label class="rpcm-detached-log-timeline-choice"><span>이 블록 시간선</span><select data-role="log-timeline">${timelineOptions(logTimelineLabelOfBlock(block))}</select></label><label class="choice-bulk"><input type="checkbox" data-log-bulk-select><span>이동 선택</span></label><button type="button" class="rpcm-detached-log-select-after" title="같은 시간선에서 이 날짜부터 아래 블록까지 선택">이 날짜부터 아래 선택</button>` : ''}<label class="choice-favorite" title="즐겨찾기 목록에서 빠르게 찾을 수 있습니다."><input type="checkbox" data-log-choice="favorite" ${favorite ? 'checked' : ''}><span>★ 즐겨찾기</span></label><label class="choice-manual" title="자동 선택을 꺼도 이 날짜를 주입 후보에 포함합니다."><input type="checkbox" data-log-choice="manual" ${manual ? 'checked' : ''}><span>직접 주입</span></label><label class="choice-pinned" title="자동 선택 여부와 상관없이 항상 우선 주입 후보에 포함합니다."><input type="checkbox" data-log-choice="pinned" ${pinned ? 'checked' : ''}><span>📌 항상 주입</span></label><label class="choice-excluded" title="최근·관련 로그 자동 선택에서 제외합니다. 직접 주입은 가능합니다."><input type="checkbox" data-log-choice="excluded" ${excluded ? 'checked' : ''}><span>🚫 자동 선택 제외</span></label></div><textarea data-role="log-body" spellcheck="false">${esc(block.body)}</textarea></div></details>`;
      };
      const activeTimeline = activeLogTimelineLabel(state.currentRoom);
      const groups = timelineLabels.map(label => ({
        label,
        entries:logBlocks.map((block, index) => ({ block, index })).filter(item => blockBelongsToTimeline(item.block, label)),
      })).filter(group => group.entries.length);
      main.innerHTML = hasMultipleTimelines ? groups.map((group, groupIndex) => {
        const open = normalizedLogTimelineKey(group.label) === normalizedLogTimelineKey(activeTimeline) || (!groups.some(item => normalizedLogTimelineKey(item.label) === normalizedLogTimelineKey(activeTimeline)) && groupIndex === 0);
        const chars = group.entries.reduce((sum, item) => sum + item.block.raw.length, 0);
        return `<details class="rpcm-detached-timeline-group" data-detached-timeline="${esc(group.label)}" ${open ? 'open' : ''}><summary><strong>🗂️ ${esc(group.label)}</strong><span>${open ? '현재 편집 · ' : ''}${group.entries.length}개 · ${formatCount(chars)}자</span><span class="rpcm-chevron">${open ? '▼' : '▶'}</span></summary><div class="rpcm-detached-timeline-body">${group.entries.map(item => cardHtml(item.block, item.index)).join('')}</div></details>`;
      }).join('') : groups.flatMap(group => group.entries).map(item => cardHtml(item.block, item.index)).join('');
      nav.innerHTML = hasMultipleTimelines ? groups.map((group, groupIndex) => {
        const open = normalizedLogTimelineKey(group.label) === normalizedLogTimelineKey(activeTimeline) || (!groups.some(item => normalizedLogTimelineKey(item.label) === normalizedLogTimelineKey(activeTimeline)) && groupIndex === 0);
        return `<details class="rpcm-detached-nav-timeline" ${open ? 'open' : ''}><summary><strong>${esc(group.label)}</strong><span>${group.entries.length}</span></summary>${group.entries.map(item => `<button type="button" class="rpcm-detached-nav-item" data-nav-index="${item.index}" title="${esc(item.block.events || item.block.fullDate)}"><i data-nav-favorite aria-label="즐겨찾기"></i><span>${esc(item.block.isUnknown ? '?' : item.block.isSpecialDate ? item.block.fullDate : `${item.block.month}/${item.block.day}`)}</span><strong>${esc(item.block.events || item.block.fullDate || `날짜 ${item.index + 1}`)}</strong></button>`).join('')}</details>`;
      }).join('') : groups.flatMap(group => group.entries).map(item => `<button type="button" class="rpcm-detached-nav-item" data-nav-index="${item.index}" title="${esc(item.block.events || item.block.fullDate)}"><i data-nav-favorite aria-label="즐겨찾기"></i><span>${esc(item.block.isUnknown ? '?' : item.block.isSpecialDate ? item.block.fullDate : `${item.block.month}/${item.block.day}`)}</span><strong>${esc(item.block.events || item.block.fullDate || `날짜 ${item.index + 1}`)}</strong></button>`).join('');
      bindDetachedNavItems();
      if (formatEl) formatEl.textContent = `날짜 블록 ${logBlocks.length}개${hasMultipleTimelines ? ` · 시간선 ${groups.length}개` : ''} · [날짜-키워드]`;
      if (addLogBtn) addLogBtn.hidden = false;
      refreshDetachedLogSelectionUi();
      refreshDetachedBulkUi();
      return true;
    };

    const insertDetachedLogBlock = (position, timelineLabel = '') => {
      const cards = [...main.querySelectorAll('.rpcm-detached-log-card[data-log-index]')];
      if (!cards.length) {
        if (!renderLogBlocks(detachedNewLogHeading(timelineLabel), [''])) return;
        bindBlockActions();
        userEdited = true;
        refreshDirty();
        const input = main.querySelector('input[data-role="log-heading"]');
        requestAnimationFrame(() => { input?.focus(); input?.select(); });
        return;
      }
      const text = collectLogsFromDom();
      const blocks = parseDatedLogBlocks(text);
      if (blocks.length !== cards.length) {
        notify('날짜 제목 형식을 먼저 확인해 주세요. 제목은 [날짜-키워드] 형태여야 합니다.', 'warn', 5200);
        return;
      }
      const origins = cards.map((card, index) => String(card.dataset.logOriginKey || card.dataset.logKey || blocks[index]?.key || ''));
      const pieces = blocks.map(block => String(block.raw || '').trim());
      const at = Math.max(0, Math.min(pieces.length, Number(position)));
      pieces.splice(at, 0, detachedNewLogHeading(timelineLabel));
      origins.splice(at, 0, '');
      if (!renderLogBlocks(pieces.filter(Boolean).join('\n\n'), origins)) return;
      bindBlockActions();
      userEdited = true;
      refreshDirty();
      const card = main.querySelector(`.rpcm-detached-log-card[data-log-index="${at}"]`);
      const input = card?.querySelector('input[data-role="log-heading"]');
      card?.scrollIntoView({ behavior:'smooth', block:'center' });
      requestAnimationFrame(() => { input?.focus(); input?.select(); });
    };

    const deleteDetachedLogBlock = card => {
      const cards = [...main.querySelectorAll('.rpcm-detached-log-card[data-log-index]')];
      const index = Number(card?.dataset.logIndex);
      if (!Number.isInteger(index) || index < 0) return;
      const title = detachedLogHeading(card, index).replace(/^\[|\]$/g, '');
      if (!confirm(`‘${title}’ 날짜 블록을 삭제할까요?`)) return;
      const pieces = cards.map(item => {
        if (item === card) return '';
        const itemIndex = Number(item.dataset.logIndex);
        const heading = detachedLogHeading(item, itemIndex);
        const body = String(item.querySelector('textarea[data-role="log-body"]')?.value || '').trim();
        return `${heading}${body ? `\n${body}` : ''}`;
      }).filter(Boolean);
      const origins = cards.filter(item => item !== card).map(item => String(item.dataset.logOriginKey || item.dataset.logKey || ''));
      if (pieces.length && parseDatedLogBlocks(pieces.join('\n\n')).length !== pieces.length) {
        notify('남은 날짜 제목 형식을 먼저 확인해 주세요.', 'warn', 4200);
        return;
      }
      const originKey = String(card.dataset.logOriginKey || card.dataset.logKey || '');
      if (originKey) {
        setRoomLogSelectionKey('manualLogSelectedKeys', originKey, false);
        setRoomLogSelectionKey('autoLogPinnedKeys', originKey, false);
        setRoomLogSelectionKey('autoLogExcludedKeys', originKey, false);
        setRoomLogSelectionKey('favoriteLogKeys', originKey, false);
        logSelectionChanged = true;
        persistDetachedLogSelectionSoon();
      }
      if (pieces.length) {
        if (!renderLogBlocks(pieces.join('\n\n'), origins)) {
          notify('남은 날짜 제목 형식을 확인해 주세요.', 'warn', 4200);
          return;
        }
        bindBlockActions();
      } else {
        renderEmptyLogBlocks();
      }
      userEdited = true;
      refreshDirty();
    };

    const renderRaw = text => {
      if (logSelectionSummaryEl) logSelectionSummaryEl.hidden = true;
      if (addLogBtn) addLogBtn.hidden = true;
      main.innerHTML = `<div class="rpcm-detached-raw-wrap"><div class="rpcm-detached-raw-note">${kind === 'currentState' ? '블록 문법: 구분선 → N. 섹션명 → 동일 구분선' : kind === 'logSummary' ? '블록 문법: [날짜-키워드] 다음 줄부터 본문' : '원문 편집'}</div><textarea id="rpcm-detached-raw" spellcheck="false">${esc(text)}</textarea></div>`;
      nav.innerHTML = '<div class="rpcm-detached-nav-empty">원문 보기</div>';
      if (formatEl) formatEl.textContent = '원문 편집 모드';
      bindEditorTextareas();
    };

    const renderEmptyLogBlocks = () => {
      logBlocks = [];
      logOriginKeys = [];
      main.innerHTML = '<div class="rpcm-detached-empty-log">날짜 블록이 없습니다.<br>상단의 ‘＋ 날짜 블록 추가’로 새 블록을 만들 수 있습니다.</div>';
      renderNav([]);
      if (formatEl) formatEl.textContent = '날짜 블록 0개';
      if (addLogBtn) addLogBtn.hidden = false;
      refreshDetachedLogSelectionUi();
      return true;
    };

    const bindBlockActions = () => {
      bindEditorTextareas();
      main.querySelectorAll('.rpcm-detached-timeline-group').forEach(group => group.addEventListener('toggle', () => {
        const chev = group.querySelector(':scope > summary .rpcm-chevron');
        if (chev) chev.textContent = group.open ? '▼' : '▶';
      }));
      main.querySelectorAll('.rpcm-detached-card').forEach(card => card.addEventListener('toggle', () => {
        const chev = card.querySelector('.rpcm-chevron'); if (chev) chev.textContent = card.open ? '▼' : '▶';
      }));
      if (kind === 'logSummary') {
        main.querySelectorAll('.rpcm-detached-log-card[data-log-key]').forEach(card => {
          const headingInput = card.querySelector('input[data-role="log-heading"]');
          const timelineSelect = card.querySelector('select[data-role="log-timeline"]');
          const updateHeadingPreview = normalize => {
            const idx = Number(card.dataset.logIndex);
            const heading = detachedLogHeading(card, idx, normalize);
            const preview = card.querySelector('[data-log-title-preview]');
            if (preview) preview.textContent = heading;
            const navTitle = nav.querySelector(`[data-nav-index="${idx}"] strong`);
            if (navTitle) navTitle.textContent = heading.replace(/^\[|\]$/g, '');
          };
          if (headingInput) {
            headingInput.oninput = () => { userEdited = true; updateHeadingPreview(false); refreshDetachedAfterInput(); };
            headingInput.onblur = () => { updateHeadingPreview(true); refreshDirty(); };
          }
          if (timelineSelect) timelineSelect.onchange = () => {
            const idx = Number(card.dataset.logIndex);
            if (!headingInput) return;
            const heading = detachedLogHeading(card, idx, true);
            const body = String(card.querySelector('textarea[data-role="log-body"]')?.value || '').trim();
            const parsed = parseDatedLogBlocks(`${heading}${body ? `\n${body}` : ''}`)[0];
            if (!parsed) {
              timelineSelect.value = logTimelineLabelOfBlock(logBlocks[idx]);
              notify('시간선을 바꾸기 전에 날짜 제목 형식을 확인해 주세요.', 'warn', 4200);
              return;
            }
            headingInput.value = formatLogHeadingForTimeline(parsed, timelineSelect.value);
            userEdited = true;
            updateHeadingPreview(false);
            const originKey = String(card.dataset.logOriginKey || card.dataset.logKey || '');
            const cards = [...main.querySelectorAll('.rpcm-detached-log-card[data-log-index]')];
            const origins = cards.map(item => String(item.dataset.logOriginKey || item.dataset.logKey || ''));
            const nextText = collectLogsFromDom();
            if (renderLogBlocks(nextText, origins)) {
              bindBlockActions();
              const moved = originKey ? main.querySelector(`.rpcm-detached-log-card[data-log-origin-key="${CSS.escape(originKey)}"]`) : null;
              moved?.closest('.rpcm-detached-timeline-group')?.setAttribute('open', '');
              moved?.scrollIntoView({ behavior:'smooth', block:'center' });
            }
            refreshDetachedAfterInput();
          };
          card.querySelectorAll('[data-log-insert]').forEach(button => button.onclick = event => {
            event.preventDefault(); event.stopPropagation();
            const idx = Number(card.dataset.logIndex);
            insertDetachedLogBlock(idx + (button.dataset.logInsert === 'after' ? 1 : 0), timelineSelect?.value || logTimelineLabelOfBlock(logBlocks[idx]));
          });
          const bulkCheckbox = card.querySelector('[data-log-bulk-select]');
          if (bulkCheckbox) bulkCheckbox.onchange = refreshDetachedBulkUi;
          const selectAfterButton = card.querySelector('.rpcm-detached-log-select-after');
          if (selectAfterButton) selectAfterButton.onclick = event => {
            event.preventDefault();
            event.stopPropagation();
            const group = card.closest('.rpcm-detached-timeline-group');
            const groupCards = [...(group?.querySelectorAll('.rpcm-detached-log-card') || [])];
            const start = groupCards.indexOf(card);
            groupCards.slice(Math.max(0, start)).forEach(item => {
              const checkbox = item.querySelector('[data-log-bulk-select]');
              if (checkbox) checkbox.checked = true;
            });
            refreshDetachedBulkUi();
          };
          card.querySelectorAll('[data-log-choice]').forEach(input => input.onchange = () => {
            const key = String(card.dataset.logKey || '');
            const choice = String(input.dataset.logChoice || '');
            if (!key || !choice) return;
            if (choice === 'manual') {
              setRoomLogSelectionKey('manualLogSelectedKeys', key, input.checked);
            } else if (choice === 'favorite') {
              setRoomLogSelectionKey('favoriteLogKeys', key, input.checked);
            } else if (choice === 'pinned') {
              setRoomLogSelectionKey('autoLogPinnedKeys', key, input.checked);
              if (input.checked) {
                const excluded = card.querySelector('[data-log-choice="excluded"]');
                if (excluded) excluded.checked = false;
                setRoomLogSelectionKey('autoLogExcludedKeys', key, false);
              }
            } else if (choice === 'excluded') {
              setRoomLogSelectionKey('autoLogExcludedKeys', key, input.checked);
              if (input.checked) {
                const pinned = card.querySelector('[data-log-choice="pinned"]');
                if (pinned) pinned.checked = false;
                setRoomLogSelectionKey('autoLogPinnedKeys', key, false);
              }
            }
            logSelectionChanged = true;
            refreshDetachedLogSelectionUi();
            persistDetachedLogSelectionSoon();
          });
          const deleteButton = card.querySelector('.rpcm-detached-card-delete');
          if (deleteButton) deleteButton.onclick = event => {
            event.preventDefault();
            event.stopPropagation();
            deleteDetachedLogBlock(card);
          };
        });
      }
      main.querySelectorAll('.rpcm-detached-card-copy').forEach(btn => btn.onclick = async event => {
        event.preventDefault(); event.stopPropagation();
        const card = btn.closest('.rpcm-detached-card');
        let text = '';
        if (kind === 'currentState') {
          const idx = Number(card?.dataset.sectionIndex);
          const title = String(card?.dataset.sectionTitle || currentSections[idx]?.title || '섹션');
          const single = card?.querySelector('textarea[data-role="section-body"]');
          let body = single?.value || '';
          if (!single) {
            const intro = card?.querySelector('textarea[data-role="section-intro"]')?.value || '';
            const blocks = [...(card?.querySelectorAll('.rpcm-detached-subblock') || [])].map(sub => ({ title:String(sub.dataset.subTitle || ''), body:sub.querySelector('textarea[data-role="sub-body"]')?.value || '' }));
            body = buildCurrentStateSubblockBody({ intro, blocks });
          }
          text = `${CURRENT_STATE_SECTION_RULE}\n${idx + 1}. ${title}\n${CURRENT_STATE_SECTION_RULE}${String(body).trim() ? `\n${String(body).trim()}` : ''}`;
        } else if (kind === 'logSummary') {
          const idx = Number(card?.dataset.logIndex);
          const heading = detachedLogHeading(card, idx);
          const body = card?.querySelector('textarea[data-role="log-body"]')?.value || '';
          text = `${heading}${String(body).trim() ? `\n${String(body).trim()}` : ''}`;
        }
        const ok = await copyPlainText(text);
        notify(ok ? '이 블록을 복사했습니다.' : '블록 복사에 실패했습니다.', ok ? 'success' : 'error', 2600);
      });
      main.querySelectorAll('.rpcm-detached-subcopy').forEach(btn => btn.onclick = async event => {
        event.preventDefault(); event.stopPropagation();
        const sub = btn.closest('.rpcm-detached-subblock');
        const title = String(sub?.dataset.subTitle || '');
        const body = sub?.querySelector('textarea[data-role="sub-body"]')?.value || '';
        const ok = await copyPlainText(`[${title}]${String(body).trim() ? `\n${String(body).trim()}` : ''}`);
        notify(ok ? '하위 블록을 복사했습니다.' : '복사에 실패했습니다.', ok ? 'success' : 'error', 2400);
      });
    };

    const renderBlocks = text => {
      mode = 'blocks';
      if (kind === 'logSummary' && !String(text || '').trim()) {
        renderEmptyLogBlocks();
        if (modeBtn) modeBtn.textContent = '원문 보기';
        if (expandBtn) expandBtn.disabled = true;
        if (collapseBtn) collapseBtn.disabled = true;
        refreshDirty();
        return true;
      }
      const parsedCount = kind === 'logSummary' ? parseDatedLogBlocks(text).length : 0;
      const preservedOrigins = kind === 'logSummary' && logOriginKeys.length === parsedCount ? logOriginKeys : null;
      const ok = kind === 'currentState' ? renderCurrentStateBlocks(text) : kind === 'logSummary' ? renderLogBlocks(text, preservedOrigins) : false;
      if (!ok) {
        mode = 'raw';
        renderRaw(text);
        if (modeBtn) modeBtn.textContent = '블록 보기';
        if (expandBtn) expandBtn.disabled = true;
        if (collapseBtn) collapseBtn.disabled = true;
        if (formatEl) formatEl.textContent = kind === 'currentState' ? '⚠ 현재상태 블록 문법 미감지' : kind === 'logSummary' ? '⚠ 날짜 블록 문법 미감지' : '원문 편집 모드';
        return false;
      }
      if (modeBtn) modeBtn.textContent = '원문 보기';
      if (expandBtn) expandBtn.disabled = false;
      if (collapseBtn) collapseBtn.disabled = false;
      bindBlockActions();
      refreshDirty();
      return true;
    };

    const renderInitial = () => {
      if (kind === 'plain') { mode = 'raw'; renderRaw(originalText); modeBtn.hidden = true; expandBtn.disabled = true; collapseBtn.disabled = true; }
      else renderBlocks(originalText);
      refreshDirty();
    };

    modeBtn.onclick = () => {
      const text = activeText();
      if (mode === 'blocks') {
        mode = 'raw';
        renderRaw(text);
        modeBtn.textContent = '블록 보기';
        expandBtn.disabled = true; collapseBtn.disabled = true;
        refreshDirty();
      } else {
        if (!renderBlocks(text)) notify(kind === 'currentState' ? '현재상태 고정 3줄 문법을 찾지 못해 원문 보기를 유지합니다.' : '날짜 제목 [날짜-키워드] 블록을 찾지 못해 원문 보기를 유지합니다.', 'warn', 4400);
      }
    };

    expandBtn.onclick = () => main.querySelectorAll('.rpcm-detached-timeline-group,.rpcm-detached-card').forEach(card => { card.open = true; });
    collapseBtn.onclick = () => main.querySelectorAll('.rpcm-detached-card,.rpcm-detached-timeline-group').forEach(card => { card.open = false; });
    if (favoriteOnlyBtn) favoriteOnlyBtn.onclick = () => { favoriteOnly = !favoriteOnly; applyDetachedFavoriteFilter(); };
    if (addLogBtn) addLogBtn.onclick = () => insertDetachedLogBlock(logBlocks.length);
    backdrop.querySelector('#rpcm-detached-log-bulk-clear')?.addEventListener('click', () => {
      main.querySelectorAll('[data-log-bulk-select]').forEach(input => { input.checked = false; });
      refreshDetachedBulkUi();
    });
    backdrop.querySelector('#rpcm-detached-log-bulk-move')?.addEventListener('click', () => {
      const target = cleanLogTimelineLabel(logBulkTarget?.value) || DEFAULT_LOG_TIMELINE;
      const cards = [...main.querySelectorAll('.rpcm-detached-log-card[data-log-index]')];
      const pieces = [];
      const origins = [];
      let movedCount = 0;
      for (const card of cards) {
        const index = Number(card.dataset.logIndex);
        const heading = detachedLogHeading(card, index, true);
        const body = String(card.querySelector('textarea[data-role="log-body"]')?.value || '').trim();
        const parsed = parseDatedLogBlocks(`${heading}${body ? `\n${body}` : ''}`)[0];
        if (!parsed) {
          notify('선택한 블록 중 날짜 제목 형식을 인식하지 못한 항목이 있습니다.', 'warn', 4600);
          return;
        }
        const selected = !!card.querySelector('[data-log-bulk-select]')?.checked;
        pieces.push(`${selected ? formatLogHeadingForTimeline(parsed, target) : heading}${body ? `\n${body}` : ''}`);
        origins.push(String(card.dataset.logOriginKey || card.dataset.logKey || ''));
        if (selected) movedCount++;
      }
      if (!movedCount) return;
      if (renderLogBlocks(pieces.join('\n\n'), origins)) {
        bindBlockActions();
        userEdited = true;
        const destination = main.querySelector(`.rpcm-detached-timeline-group[data-detached-timeline="${CSS.escape(target)}"]`);
        if (destination) destination.open = true;
        refreshDirty();
        notify(`${movedCount}개 날짜 블록을 ‘${target}’으로 옮겼습니다. 적용하고 닫기를 누르면 저장됩니다.`, 'success', 4200);
      }
    });
    backdrop.querySelector('#rpcm-detached-copy').onclick = async () => {
      const ok = await copyPlainText(activeText());
      notify(ok ? `‘${slot.title}’ 전체를 복사했습니다.` : '전체 복사에 실패했습니다.', ok ? 'success' : 'error', 2800);
    };

    const clearDetachedSearchVisuals = () => {
      main.querySelectorAll('.rpcm-detached-card.is-search-hit').forEach(card => card.classList.remove('is-search-hit'));
      main.querySelectorAll('.is-search-active-field').forEach(field => field.classList.remove('is-search-active-field'));
      main.querySelectorAll('.is-search-active-label').forEach(el => el.classList.remove('is-search-active-label'));
    };

    const findAllOccurrences = (value, query) => {
      const hay = String(value || '').toLocaleLowerCase('ko-KR');
      const hits = [];
      let from = 0;
      while (query && from <= hay.length) {
        const at = hay.indexOf(query, from);
        if (at < 0) break;
        hits.push([at, at + query.length]);
        from = at + Math.max(1, query.length);
        if (hits.length >= 500) break;
      }
      return hits;
    };

    const selectionOffsetY = (textarea, start) => {
      try {
        const cs = getComputedStyle(textarea);
        const mirror = document.createElement('div');
        mirror.setAttribute('aria-hidden', 'true');
        Object.assign(mirror.style, {
          position:'fixed', left:'-100000px', top:'0', visibility:'hidden', pointerEvents:'none',
          boxSizing:'border-box', width:`${textarea.getBoundingClientRect().width}px`,
          whiteSpace:'pre-wrap', overflowWrap:'break-word', wordBreak:'break-word',
          paddingTop:cs.paddingTop, paddingRight:cs.paddingRight, paddingBottom:cs.paddingBottom, paddingLeft:cs.paddingLeft,
          borderTopWidth:cs.borderTopWidth, borderRightWidth:cs.borderRightWidth, borderBottomWidth:cs.borderBottomWidth, borderLeftWidth:cs.borderLeftWidth,
          borderStyle:'solid', fontFamily:cs.fontFamily, fontSize:cs.fontSize, fontWeight:cs.fontWeight, fontStyle:cs.fontStyle,
          lineHeight:cs.lineHeight, letterSpacing:cs.letterSpacing, tabSize:cs.tabSize || '8'
        });
        mirror.append(document.createTextNode(String(textarea.value || '').slice(0, start)));
        const marker = document.createElement('span');
        marker.textContent = String(textarea.value || '').slice(start, start + 1) || ' ';
        mirror.appendChild(marker);
        document.body.appendChild(mirror);
        const y = marker.offsetTop;
        mirror.remove();
        return Number.isFinite(y) ? y : 0;
      } catch (_) { return 0; }
    };

    const revealTextareaHit = hit => {
      const ta = hit.textarea || hit.raw;
      if (!ta) return;
      const card = hit.card || ta.closest('.rpcm-detached-card');
      if (card) {
        card.closest('.rpcm-detached-timeline-group')?.setAttribute('open', '');
        card.open = true;
        card.classList.add('is-search-hit');
      }
      ta.classList.add('is-search-active-field');
      const offsetY = selectionOffsetY(ta, hit.start);
      const mainRect = main.getBoundingClientRect();
      const taRect = ta.getBoundingClientRect();
      const desired = main.scrollTop + (taRect.top - mainRect.top) + offsetY - Math.max(80, main.clientHeight * .40);
      main.scrollTo({ top:Math.max(0, desired), behavior:'smooth' });
      // 검색어 자체가 눈에 보이도록 실제 해당 문자열을 선택합니다.
      requestAnimationFrame(() => {
        try { ta.focus({ preventScroll:true }); } catch (_) { ta.focus(); }
        try { ta.setSelectionRange(hit.start, hit.end); } catch (_) {}
      });
    };

    const collectSearchHits = () => {
      const query = String(searchInput.value || '').trim().toLocaleLowerCase('ko-KR');
      lastSearchQuery = query;
      searchHits = []; searchIndex = -1;
      clearDetachedSearchVisuals();
      if (!query) { searchCount.textContent = '0 / 0'; return; }
      if (mode === 'raw') {
        const raw = main.querySelector('#rpcm-detached-raw');
        for (const [start, end] of findAllOccurrences(raw?.value || '', query)) searchHits.push({ raw, start, end });
      } else {
        main.querySelectorAll('.rpcm-detached-card').forEach(card => {
          if (favoriteOnly && card.matches('.rpcm-detached-log-card') && !card.classList.contains('is-log-favorite')) return;
          // 본문은 '카드 단위'가 아니라 실제 등장 위치마다 검색 결과를 만듭니다.
          card.querySelectorAll('textarea,input[data-role="log-heading"]').forEach(textarea => {
            for (const [start, end] of findAllOccurrences(textarea.value, query)) searchHits.push({ card, textarea, start, end });
          });
          // 섹션/하위블록 제목도 검색 가능하게 유지합니다.
          card.querySelectorAll(':scope > summary strong, .rpcm-detached-subhead strong').forEach(label => {
            if (String(label.textContent || '').toLocaleLowerCase('ko-KR').includes(query)) searchHits.push({ card, label });
          });
        });
      }
      searchCount.textContent = searchHits.length ? `– / ${searchHits.length}` : '0 / 0';
    };

    const showSearchHit = direction => {
      const query = String(searchInput.value || '').trim().toLocaleLowerCase('ko-KR');
      if (query !== lastSearchQuery || !searchHits.length) collectSearchHits();
      if (!searchHits.length) return;
      clearDetachedSearchVisuals();
      searchIndex = (searchIndex + direction + searchHits.length) % searchHits.length;
      const hit = searchHits[searchIndex];
      if (hit.textarea || hit.raw) {
        revealTextareaHit(hit);
      } else if (hit.card) {
        hit.card.closest('.rpcm-detached-timeline-group')?.setAttribute('open', '');
        hit.card.open = true;
        hit.card.classList.add('is-search-hit');
        if (hit.label) hit.label.classList.add('is-search-active-label');
        (hit.label || hit.card).scrollIntoView({ behavior:'smooth', block:'center' });
      }
      searchCount.textContent = `${searchIndex + 1} / ${searchHits.length}`;
    };

    searchInput.oninput = collectSearchHits;
    searchInput.onkeydown = event => { if (event.key === 'Enter') { event.preventDefault(); showSearchHit(event.shiftKey ? -1 : 1); } };
    backdrop.querySelector('#rpcm-detached-search-prev').onclick = () => showSearchHit(-1);
    backdrop.querySelector('#rpcm-detached-search-next').onclick = () => showSearchHit(1);

    const close = (force = false) => {
      if (!force && isActuallyDirty() && !confirm('아직 적용하지 않은 수정사항이 있습니다. 버리고 닫을까요?')) return;
      backdrop.remove();
      if (logSelectionChanged) renderModalIfOpen();
    };
    backdrop._rpcmClose = () => close(true);
    backdrop.querySelector('#rpcm-detached-x').onclick = () => close(false);
    backdrop.querySelector('#rpcm-detached-cancel').onclick = () => close(false);
    backdrop.querySelector('#rpcm-detached-apply').onclick = () => {
      if (kind === 'logSummary' && mode === 'blocks') {
        main.querySelectorAll('input[data-role="log-heading"]').forEach((input, index) => {
          input.value = normalizeDetachedLogHeading(input.value, logBlocks[index]?.heading || '[날짜 미정-새 로그]');
        });
      }
      const rawNextText = activeText().trim();
      const nextText = kind === 'logSummary'
        ? alignNewManualLogBlocksToActiveTimeline(originalText, rawNextText, state.currentRoom)
        : rawNextText;
      const changed = userEdited && normalizeLineBreaks(nextText).trim() !== normalizeLineBreaks(originalText).trim();
      if (!changed) { close(true); return; }
      let nextLogBlocks = null;
      let logKeyMap = null;
      if (kind === 'logSummary') {
        nextLogBlocks = parseDatedLogBlocks(nextText);
        if (nextText && !nextLogBlocks.length) {
          notify('날짜 블록을 찾지 못했습니다. 제목을 [2027년 9월 24일-키워드] 형태로 입력해 주세요.', 'warn', 5600);
          return;
        }
        logKeyMap = new Map();
        if (mode === 'blocks') {
          const cards = [...main.querySelectorAll('.rpcm-detached-log-card[data-log-index]')];
          const rawBlocks = parseDatedLogBlocks(rawNextText);
          if (nextLogBlocks.length !== cards.length || rawBlocks.length !== cards.length) {
            notify('일부 날짜 제목을 블록으로 인식하지 못했습니다. 각 제목의 대괄호와 날짜 형식을 확인해 주세요.', 'warn', 6200);
            return;
          }
          const originQueues = new Map();
          cards.forEach((card, index) => {
            const origin = String(card.dataset.logOriginKey || card.dataset.logKey || '');
            const block = rawBlocks[index];
            if (!origin || !block) return;
            const signature = `${block.heading}\n${block.body}`;
            if (!originQueues.has(signature)) originQueues.set(signature, []);
            originQueues.get(signature).push(origin);
          });
          nextLogBlocks.forEach(block => {
            const signature = `${block.heading}\n${block.body}`;
            const origin = originQueues.get(signature)?.shift();
            if (origin) logKeyMap.set(origin, String(block.key));
          });
        } else {
          parseDatedLogBlocks(originalText).forEach((block, index) => {
            if (nextLogBlocks[index]) logKeyMap.set(String(block.key), String(nextLogBlocks[index].key));
          });
        }
      }
      const liveTextarea = state.modal?.querySelector(`.rpcm-slot[data-slot-id="${CSS.escape(String(slot.id))}"] .rpcm-textarea`) || sourceTextarea;
      if (!liveTextarea) { notify('원래 편집칸을 찾지 못해 적용하지 못했습니다.', 'error', 4200); return; }
      if (kind === 'logSummary' && state.currentRoom && nextLogBlocks && logKeyMap) {
        remapLogSelectionKeys(state.currentRoom, logKeyMap, nextLogBlocks);
      }
      liveTextarea.value = nextText;
      liveTextarea.dispatchEvent(new Event('input', { bubbles:true }));
      notify(`‘${slot.title}’ 크게 편집 내용을 적용했습니다.`, 'success', 3000);
      close(true);
    };
    backdrop.addEventListener('keydown', event => {
      if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); close(false); }
      if ((event.ctrlKey || event.metaKey) && event.key === 'Enter') { event.preventDefault(); backdrop.querySelector('#rpcm-detached-apply')?.click(); }
    });

    const exitDetachedMobileEditing = () => {
      backdrop.classList.remove('rpcm-detached-keyboard-editing');
      backdrop.querySelectorAll('.rpcm-mobile-active-card,.rpcm-mobile-active-editor').forEach(node => node.classList.remove('rpcm-mobile-active-card','rpcm-mobile-active-editor'));
      updateViewportMetrics();
    };
    backdrop.addEventListener('focusin', event => {
      const textarea = event.target.closest?.('.rpcm-detached-main textarea,.rpcm-detached-main input[data-role="log-heading"]');
      if (!textarea || !isMobileManagerLayout()) return;
      if (textarea.matches('input[data-role="log-heading"]')) { updateViewportMetrics(); return; }
      backdrop.querySelectorAll('.rpcm-mobile-active-card,.rpcm-mobile-active-editor').forEach(node => node.classList.remove('rpcm-mobile-active-card','rpcm-mobile-active-editor'));
      textarea.closest('.rpcm-detached-card')?.classList.add('rpcm-mobile-active-card');
      textarea.classList.add('rpcm-mobile-active-editor');
      backdrop.classList.add('rpcm-detached-keyboard-editing');
      updateViewportMetrics();
    });
    backdrop.addEventListener('focusout', () => {
      setTimeout(() => {
        if (document.activeElement?.matches?.('.rpcm-detached-main textarea,.rpcm-detached-main input[data-role="log-heading"]')) return;
        exitDetachedMobileEditing();
      }, 80);
    });
    const detachedMobileDone = backdrop.querySelector('#rpcm-detached-mobile-done');
    if (detachedMobileDone) detachedMobileDone.onclick = () => {
      const active = document.activeElement;
      if (active instanceof HTMLElement) active.blur();
      exitDetachedMobileEditing();
    };

    renderInitial();
    if (!isMobileManagerLayout()) backdrop.querySelector('#rpcm-detached-search')?.focus();
  }

  function openContextPreviewDialog(room, items) {
    document.querySelector('#rpcm-preview-backdrop')?.remove();
    const active = (items || []).filter(item => String(item.content || '').trim());
    const stats = statsForItems(active);
    const contextBlock = room.pending ? String(room.pending.contextBlock || buildContextBlockFromItems(active)) : buildContextBlockFromItems(active);
    const capacity = carrierCapacityForUi(room, stats.block, contextBlock);
    const used = Math.max(0, Number(capacity.total || contextBlock.length));
    const omittedLogTitles = room?._logBudgetInfo?.omittedTitles || [];
    const omittedLoreTitles = loreBudgetInfoFor(room)?.omittedTitles || [];
    const previousFocus = document.activeElement;
    const backdrop = document.createElement('div');
    backdrop.id = 'rpcm-preview-backdrop';
    backdrop.innerHTML = `
      <div class="rpcm-preview-dialog" role="dialog" aria-modal="true" aria-labelledby="rpcm-preview-title">
        <div class="rpcm-lib-dialog-head"><div><div class="rpcm-lib-dialog-title" id="rpcm-preview-title">${room.pending ? '현재 주입 · ' + (room.pending.verified ? '확인됨' : '서버 확인 필요') : '주입 후보 · 확인 대기'}</div><div class="rpcm-lib-dialog-desc">${formatCount(used)} / 45,000자 · 카드 ${active.length}개 · 위에서부터 순서대로</div></div><button type="button" class="rpcm-lib-close" aria-label="닫기" data-rpcm-close="icon">${rpcmUiIcon('close')}</button></div>
        <div class="rpcm-preview-gauge" role="progressbar" aria-label="주입 용량" aria-valuemin="0" aria-valuemax="45000" aria-valuenow="${Math.min(45000, used)}"><i style="width:${Math.min(100, used / 45000 * 100)}%"></i></div>
        ${omittedLogTitles.length || omittedLoreTitles.length ? `<div class="rpcm-preview-reason">용량 때문에 제외 · ${omittedLogTitles.length ? `날짜로그 ${esc(omittedLogTitles.join(', '))}` : ''}${omittedLogTitles.length && omittedLoreTitles.length ? ' / ' : ''}${omittedLoreTitles.length ? `자료집 ${esc(omittedLoreTitles.join(', '))}` : ''}</div>` : ''}
        <div class="rpcm-preview-list">
          ${active.length ? active.map((item, index) => {
            const category = itemCategory(item);
            const reason = itemReason(item);
            const evidence = relatedLogEvidence(item);
            return `<details class="rpcm-preview-card tone-${categoryTone(category)}">
              <summary><span class="rpcm-preview-index">${String(index + 1).padStart(2, '0')}</span><span class="rpcm-preview-kind">${esc(category)}</span><strong>${esc(item.title || category)}</strong><span class="rpcm-preview-meta">${formatCount(String(item.content || '').length)}자 · ${esc(reason || remainingLabelForItem(item))}</span><span class="rpcm-chevron">▶</span></summary>
              <div class="rpcm-preview-reason">${esc(reason || '직접 선택')} · ${esc(remainingLabelForItem(item))}</div>
              ${evidence ? `<div class="rpcm-preview-evidence">선정 근거 · ${esc(evidence)}</div>` : ''}
              <pre>${esc(String(item.content || '').trim())}</pre>
            </details>`;
          }).join('') : '<div class="rpcm-preview-empty">주입할 항목이 없습니다.</div>'}
        </div>
        <div class="rpcm-preview-raw" hidden><textarea readonly spellcheck="false" aria-label="주입 hidden context 전체 원문"></textarea></div>
        <div class="rpcm-lib-dialog-actions rpcm-preview-actions"><button type="button" class="rpcm-btn secondary rpcm-preview-raw-toggle">${rpcmUiIcon('eye')} 전체 원문</button><button type="button" class="rpcm-btn secondary rpcm-preview-close" aria-label="닫기" data-rpcm-close="text">닫기</button></div>
      </div>`;
    document.body.appendChild(backdrop);
    backdrop.querySelector('.rpcm-preview-raw textarea').value = contextBlock;
    const close = () => { backdrop.remove(); if (previousFocus?.isConnected) previousFocus.focus(); };
    backdrop._rpcmClose = close;
    backdrop.querySelector('.rpcm-lib-close').onclick = close;
    backdrop.querySelector('.rpcm-preview-close').onclick = close;
    backdrop.onclick = event => { if (event.target === backdrop) close(); };
    backdrop.querySelector('.rpcm-preview-raw-toggle').onclick = () => {
      const raw = backdrop.querySelector('.rpcm-preview-raw');
      raw.hidden = !raw.hidden;
      backdrop.querySelector('.rpcm-preview-list').hidden = !raw.hidden;
      if (!raw.hidden) raw.querySelector('textarea').focus();
    };
    backdrop.onkeydown = event => {
      if (event.key === 'Escape') { event.preventDefault(); close(); return; }
      if (event.key !== 'Tab') return;
      const focusable = [...backdrop.querySelectorAll('button,summary,textarea')].filter(node => !node.closest('[hidden]'));
      if (!focusable.length) return;
      const first = focusable[0], last = focusable[focusable.length - 1];
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    };
    backdrop.querySelector('.rpcm-lib-close')?.focus();
    backdrop.querySelectorAll('.rpcm-preview-card').forEach(card => card.addEventListener('toggle', () => {
      card.querySelector('.rpcm-chevron').textContent = card.open ? '▼' : '▶';
    }));
  }

  function backupRoomSummary(room) {
    const slots = Array.isArray(room?.slots) ? room.slots : [];
    const chars = slots.reduce((sum, slot) => sum + String(slot?.content || '').length, 0);
    const filled = slots.filter(slot => String(slot?.content || '').trim()).length;
    const knowledge = (Array.isArray(room?.knowledgeCards) ? room.knowledgeCards : []).filter(card => !card.archived).length;
    const personRecords = (Array.isArray(room?.personStateRecords) ? room.personStateRecords : []).filter(record => record.active !== false).length;
    const timeline = Array.isArray(room?.storyTimelineCards) ? room.storyTimelineCards.length : 0;
    const lore = (Array.isArray(room?.lorePacks) ? room.lorePacks : []);
    return `기억 ${filled}개·${formatCount(chars)}자 · 인물정보 ${knowledge + personRecords}건(인지 ${knowledge}·관계/호칭 ${personRecords}) · 타임라인 ${timeline}개 · 자료집 ${lore.length}팩/${lore.reduce((n, pack) => n + (Array.isArray(pack.cards) ? pack.cards.length : 0), 0)}카드${room?.updatedAt ? ` · ${new Date(room.updatedAt).toLocaleDateString('ko-KR')}` : ''}`;
  }

  function backupRoomSignature(room) {
    return JSON.stringify({
      slots:(room?.slots || []).map(slot => ({ id:slot.id, title:slot.title, group:slot.group, enabled:!!slot.enabled, content:String(slot.content || ''), retentionTurns:Number(slot.retentionTurns || 0), aliases:slot.aliases || [], autoPinned:!!slot.autoPinned, autoExcluded:!!slot.autoExcluded, itemFolder:String(slot.itemFolder || ''), extraCategory:String(slot.extraCategory || '') })),
      knowledgeCards:room?.knowledgeCards || [],
      lorePacks:room?.lorePacks || [],
      userCanonMemos:room?.userCanonMemos || [],
      longTermMemory:room?.longTermMemory || null,
      utilityAliases:room?.utilityAliases || [],
      personStateRecords:room?.personStateRecords || [],
      knowledgeInjectionEnabled:!!room?.knowledgeInjectionEnabled,
      personStateInjectionEnabled:!!room?.personStateInjectionEnabled,
      personPlayerName:String(room?.personPlayerName || ''),
      autoCharacterDetection:!!room?.autoCharacterDetection,
      autoCharacterLibraryId:String(room?.autoCharacterLibraryId || ''),
      autoItemDetection:room?.autoItemDetection !== false,
      autoItemResetOnReappear:room?.autoItemResetOnReappear !== false,
      allowedDuplicateItemSignatures:room?.allowedDuplicateItemSignatures || [],
      lastExtraLibraryId:String(room?.lastExtraLibraryId || ''),
      autoLogRecallEnabled:!!room?.autoLogRecallEnabled,
      autoLogRecentBlocks:Number(room?.autoLogRecentBlocks || 0),
      autoLogRelatedBlocks:Number(room?.autoLogRelatedBlocks || 0),
      autoLogPinnedKeys:room?.autoLogPinnedKeys || [], autoLogExcludedKeys:room?.autoLogExcludedKeys || [], manualLogSelectedKeys:room?.manualLogSelectedKeys || [], favoriteLogKeys:room?.favoriteLogKeys || [], acceptedUnknownLogKeys:room?.acceptedUnknownLogKeys || [], aiContextLogRerankEnabled:!!room?.aiContextLogRerankEnabled,
      aiApiUsage:room?.aiApiUsage || { version:1, features:{ summary:emptyRoomAiFeatureUsage(), timeline:emptyRoomAiFeatureUsage(), context:emptyRoomAiFeatureUsage(), itemFolder:emptyRoomAiFeatureUsage(), utility:emptyRoomAiFeatureUsage(), longTermManualFirst:emptyRoomAiFeatureUsage(), longTermAutoFirst:emptyRoomAiFeatureUsage(), longTermSecond:emptyRoomAiFeatureUsage(), longTermNative:emptyRoomAiFeatureUsage() }, history:[] },
      storyTimelineCards:(room?.storyTimelineCards || []).map(card => ({ cardId:card.cardId, timelineLabel:card.timelineLabel, dateStart:card.dateStart, dateEnd:card.dateEnd, title:card.title, content:String(card.content || ''), tags:card.tags || [], userLocked:!!card.userLocked, inject:card.inject !== false, sortOrder:Number(card.sortOrder || 0) })), storyTimelineInjectionEnabled:room?.storyTimelineInjectionEnabled !== false, storyTimelineCarryoverTurnKeys:room?.storyTimelineCarryoverTurnKeys || [], storyTimelineApiHistory:room?.storyTimelineApiHistory || [], storyTimelineAuditHistory:room?.storyTimelineAuditHistory || [], storyTimelineManualRun:room?.storyTimelineManualRun || null,
      storyLogReviews:room?.storyLogReviews || [], storyTimelineGuide:String(effectiveTimelineGuide(room)), storyTimelineGuideSource:String(room?.storyTimelineGuideSource || ''), storyTimelineGuideRevisionV15:!!room?.storyTimelineGuideRevisionV15, storyTimelinePendingReview:room?.storyTimelinePendingReview || null,
      storyTimelineLastReviewedMessageId:String(room?.storyTimelineLastReviewedMessageId || ''), storyTimelineLastReviewedAt:String(room?.storyTimelineLastReviewedAt || ''),
      storyTimelineReviewSettings:room?.storyTimelineReviewSettings || { threshold:50, menuBadge:true, topNotice:true, popup:false, dateIndicator:true, monthlyFold:true, monthlyFoldMin:8 }, storyTimelineLastDiff:room?.storyTimelineLastDiff || [], storyTimelineBackup:room?.storyTimelineBackup || null,
    });
  }

  function backupLibrarySignature(library) {
    return JSON.stringify({
      kind:String(library?.kind || ''),
      name:String(library?.presetName || library?.label || ''),
      characters:(library?.characters || []).map(item => ({ title:item.title, content:String(item.content || ''), aliases:item.aliases || [], retentionTurns:Number(item.retentionTurns || 0), autoPinned:!!item.autoPinned, autoExcluded:!!item.autoExcluded })),
      extras:(library?.extras || []).map(item => ({ title:item.title, content:String(item.content || ''), retentionTurns:Number(item.retentionTurns || 0), category:String(item.category || '') })),
    });
  }

  function emptyRoomAiUsageForTransfer() {
    return { version:1, features:{ summary:emptyRoomAiFeatureUsage(), timeline:emptyRoomAiFeatureUsage(), context:emptyRoomAiFeatureUsage(), itemFolder:emptyRoomAiFeatureUsage(), utility:emptyRoomAiFeatureUsage(), longTermManualFirst:emptyRoomAiFeatureUsage(), longTermAutoFirst:emptyRoomAiFeatureUsage(), longTermSecond:emptyRoomAiFeatureUsage(), longTermNative:emptyRoomAiFeatureUsage() }, history:[] };
  }

  function cloneBackupRoomIntoCurrent(sourceRoom, targetRoom) {
    if (!sourceRoom || !targetRoom?.chatId) throw new Error('복사할 원본 방 또는 현재 방 정보를 찾지 못했습니다.');
    const next = JSON.parse(JSON.stringify(sourceRoom));
    const sourceScopeIds = Array.isArray(sourceRoom.characterScopeIds) ? sourceRoom.characterScopeIds : [];
    const targetScopeIds = Array.isArray(targetRoom.characterScopeIds) ? targetRoom.characterScopeIds : [];
    next.chatId = String(targetRoom.chatId);
    next._rpcmRevision = Number(targetRoom._rpcmRevision || 0);
    next.apiChatId = String(targetRoom.apiChatId || state.currentApiChatId || String(targetRoom.chatId).split('::')[0]);
    next.label = String(targetRoom.label || sourceRoom.label || '복사된 RP');
    next.characterScopeId = String(targetRoom.characterScopeId || sourceRoom.characterScopeId || '');
    next.characterScopeIds = [...new Set([
      ...targetScopeIds, ...sourceScopeIds, next.characterScopeId,
    ].filter(Boolean).map(String))];
    // 다른 방의 활성 carrier와 비용 기록은 대상 방의 실제 상태가 아니므로 복사하지 않습니다.
    next.pending = null;
    next.aiApiUsage = emptyRoomAiUsageForTransfer();
    // Crack summary IDs belong to the original chat. Keep user guide edits, but
    // never transfer cursors, protected IDs or pending server mutations to another chat.
    next.longTermMemory = { version:1, guides:structuredClone(sourceRoom.longTermMemory?.guides || {}),
      firstStage:{autoEnabled:false,autoIntervalTurns:Number(sourceRoom.longTermMemory?.firstStage?.autoIntervalTurns)||20},
      nativeAuto:{enabled:false},batches:[],protectedIds:[],drafts:{} };
    next.aiContextReviewReport = null;
    next.autoRecallContextText = '';
    next.autoScanLastMessageId = '';
    next.createdAt = String(targetRoom.createdAt || nowIso());
    next.updatedAt = nowIso();
    if (!Array.isArray(next.lorePacks)) next.lorePacks = [];
    else next.lorePacks = next.lorePacks.map(pack => ({ ...pack, managedBy:'user', cards:(Array.isArray(pack.cards) ? pack.cards : []).map(card => ({ ...card, managedBy:'user', userLocked:true })) }));
    normalizeRoomSlots(next);
    return next;
  }

  async function saveRestoredRoom(room) {
    await saveRoom(room,'backup-restore');
    const stored=await readManualStoredRoom(room);
    if(!stored||JSON.stringify(stored)!==JSON.stringify(room))throw new Error('백업 복원 저장 후 실제 IndexedDB 값 확인에 실패했습니다. 복원 완료로 표시하지 않았습니다.');
    return stored;
  }

  function openBackupImportDialog(data, existingRooms = [], existingLibraries = []) {
    return new Promise(resolve => {
      document.querySelector('#rpcm-import-backdrop')?.remove();
      const existingPending = new Set((existingRooms || []).filter(room => room?.pending).map(room => String(room.chatId)));
      const existingRoomMap = new Map((existingRooms || []).map(room => [String(room.chatId), room]));
      const existingLibraryMap = new Map((existingLibraries || []).map(lib => [String(lib.scopeId), lib]));
      const rooms = (Array.isArray(data?.rooms) ? data.rooms : []).filter(room => room?.chatId);
      const libraries = (Array.isArray(data?.characterLibraries) ? data.characterLibraries : []).filter(lib => lib?.scopeId);
      const characterLibraries = libraries.filter(lib => Array.isArray(lib?.characters) && lib.characters.length);
      const extraLibraries = libraries.filter(lib => Array.isArray(lib?.extras) && lib.extras.length);
      const backdrop = document.createElement('div');
      backdrop.id = 'rpcm-import-backdrop';
      backdrop.innerHTML = `
        <div class="rpcm-import-dialog" role="dialog" aria-modal="true" aria-label="백업 선택 복원">
          <div class="rpcm-lib-dialog-head"><div><div class="rpcm-lib-dialog-title">백업 불러오기</div><div class="rpcm-lib-dialog-desc">${data.exportedAt ? `${new Date(data.exportedAt).toLocaleString('ko-KR')} 생성 · ` : ''}원래 방에 복원하거나, 백업의 RP 하나를 지금 열어 둔 방으로 통째로 복사할 수 있습니다.</div></div><button type="button" class="rpcm-lib-close" aria-label="닫기" data-rpcm-close="icon">✕</button></div>
          <div class="rpcm-import-toolbar"><button type="button" class="rpcm-lib-small" data-select-current>현재 방만</button><button type="button" class="rpcm-lib-small" data-select-all>전체 선택</button><button type="button" class="rpcm-lib-small" data-select-none>선택 해제</button><span class="rpcm-lib-selected">0개 선택</span></div>
          <div class="rpcm-import-list">
            <div class="rpcm-import-group-title">RP 채팅방 · ${rooms.length}개</div>
            ${rooms.length ? rooms.map(room => {
              const blocked = existingPending.has(String(room.chatId));
              const current = String(room.chatId) === String(state.currentChatId);
              const existing = existingRoomMap.get(String(room.chatId));
              const diff = !existing ? '신규' : backupRoomSignature(existing) === backupRoomSignature(room) ? '동일' : '변경 있음';
              return `<label class="rpcm-import-row${current ? ' is-current' : ''}${blocked ? ' is-protected' : ''}"><input type="checkbox" data-room-id="${esc(room.chatId)}" data-restore-blocked="${blocked ? '1' : '0'}"><span><strong>${current ? '● ' : ''}${esc(room.label || `RP ${shortId(room.chatId)}`)} <em class="rpcm-import-diff">${diff}</em></strong><small>${esc(backupRoomSummary(room))}${blocked ? ' · 원래 방 복원 불가 · 현재 방 복사는 가능' : ''}</small></span></label>`;
            }).join('') : '<div class="rpcm-empty">백업에 채팅방 데이터가 없습니다.</div>'}
            <div class="rpcm-import-group-title">캐릭터 설정집 · ${characterLibraries.length}개</div>
            ${characterLibraries.length ? characterLibraries.map(lib => { const existing = existingLibraryMap.get(String(lib.scopeId)); const diff = !existing ? '신규' : backupLibrarySignature(existing) === backupLibrarySignature(lib) ? '동일' : '변경 있음'; return `<label class="rpcm-import-row"><input type="checkbox" data-library-id="${esc(lib.scopeId)}"><span><strong>${esc(libraryDisplayName(lib) || lib.scopeId)} <em class="rpcm-import-diff">${diff}</em></strong><small>${lib.characters.length}명</small></span></label>`; }).join('') : '<div class="rpcm-empty">백업에 캐릭터 설정집이 없습니다.</div>'}
            <div class="rpcm-import-group-title">기타 설정집 · ${extraLibraries.length}개</div>
            ${extraLibraries.length ? extraLibraries.map(lib => { const existing = existingLibraryMap.get(String(lib.scopeId)); const diff = !existing ? '신규' : backupLibrarySignature(existing) === backupLibrarySignature(lib) ? '동일' : '변경 있음'; return `<label class="rpcm-import-row"><input type="checkbox" data-library-id="${esc(lib.scopeId)}"><span><strong>${esc(extraLibraryDisplayName(lib) || lib.scopeId)} <em class="rpcm-import-diff">${diff}</em></strong><small>${lib.extras.length}개 항목</small></span></label>`; }).join('') : '<div class="rpcm-empty">백업에 기타 설정집이 없습니다.</div>'}
          </div>
          <div class="rpcm-import-note">‘현재 방에 복사’는 지금 열어 둔 방의 RP Manager 데이터를 덮어씁니다. 활성 주입 상태·AI 맥락 검토 결과·원본 방의 API 비용은 복사하지 않습니다.</div>
          <div class="rpcm-lib-dialog-actions"><button type="button" class="rpcm-btn secondary rpcm-import-cancel">취소</button><button type="button" class="rpcm-btn secondary rpcm-import-clone" disabled>선택한 RP를 현재 방에 복사</button><button type="button" class="rpcm-btn primary rpcm-import-apply" disabled>원래 방에 복원</button></div>
        </div>`;
      document.body.appendChild(backdrop);
      const boxes = () => [...backdrop.querySelectorAll('input[type="checkbox"]:not(:disabled)')];
      const update = () => {
        const count = boxes().filter(box => box.checked).length;
        const selectedRoomCount = boxes().filter(box => box.checked && box.dataset.roomId).length;
        const restoreBlocked = boxes().some(box => box.checked && box.dataset.roomId && box.dataset.restoreBlocked === '1');
        backdrop.querySelector('.rpcm-lib-selected').textContent = `${count}개 선택`;
        backdrop.querySelector('.rpcm-import-apply').disabled = count === 0 || restoreBlocked;
        backdrop.querySelector('.rpcm-import-clone').disabled = selectedRoomCount !== 1 || !!state.currentRoom?.pending;
      };
      const close = value => { backdrop.remove(); resolve(value); };
      backdrop._rpcmClose = () => close(null);
      backdrop.querySelector('.rpcm-lib-close').onclick = () => close(null);
      backdrop.querySelector('.rpcm-import-cancel').onclick = () => close(null);
      backdrop.onclick = event => { if (event.target === backdrop) close(null); };
      backdrop.onkeydown = event => { if (event.key === 'Escape') close(null); };
      backdrop.querySelector('[data-select-current]').onclick = () => {
        boxes().forEach(box => { box.checked = box.dataset.roomId === String(state.currentChatId); });
        update();
      };
      backdrop.querySelector('[data-select-all]').onclick = () => { boxes().forEach(box => { box.checked = true; }); update(); };
      backdrop.querySelector('[data-select-none]').onclick = () => { boxes().forEach(box => { box.checked = false; }); update(); };
      boxes().forEach(box => box.onchange = update);
      backdrop.querySelector('.rpcm-import-apply').onclick = () => close({
        mode:'restore-original',
        roomIds: boxes().filter(box => box.checked && box.dataset.roomId).map(box => box.dataset.roomId),
        libraryIds: boxes().filter(box => box.checked && box.dataset.libraryId).map(box => box.dataset.libraryId),
      });
      backdrop.querySelector('.rpcm-import-clone').onclick = () => close({
        mode:'clone-current',
        roomIds: boxes().filter(box => box.checked && box.dataset.roomId).map(box => box.dataset.roomId),
        libraryIds: boxes().filter(box => box.checked && box.dataset.libraryId).map(box => box.dataset.libraryId),
      });
      if (data?.backupMode === 'room-transfer') boxes().forEach(box => { box.checked = true; });
      update();
      backdrop.querySelector('.rpcm-lib-close')?.focus();
    });
  }

  // ---------------------------------------------------------------------------
  // Injection lifecycle
  // ---------------------------------------------------------------------------

  function rerollControlFromEventTarget(target) {
    const control = target?.closest?.('button,[role="button"],[role="menuitem"],a');
    if (!control || control.closest?.('#rpcm-overlay,#rpcm-toast-wrap,#rpcm-notice-popups,#rpcm-lib-dialog-backdrop,[data-rpcm-settings-entry="1"]')) return null;
    const label = [
      control.getAttribute?.('aria-label'),
      control.getAttribute?.('title'),
      control.getAttribute?.('data-testid'),
      control.getAttribute?.('data-action'),
      control.textContent,
    ].filter(Boolean).join(' ').replace(/\s+/g, ' ').trim().toLowerCase();
    if (!label) return null;
    return /(?:리롤|다시\s*생성|재생성|reroll|regenerate|retry\s*(?:response|answer))/.test(label) ? control : null;
  }

  function replayRerollControl(control) {
    if (!control?.isConnected || typeof control.click !== 'function') return;
    state.rerollBypassElement = control;
    try { control.click(); }
    finally {
      queueMicrotask(() => {
        if (state.rerollBypassElement === control) state.rerollBypassElement = null;
      });
    }
  }

  function activeItemsFittedForCarrier(room, pending, originalText) {
    return fitItemsToCarrierLimits(room, originalText, activePendingItems(pending));
  }

  async function settleCarrierBeforeReroll(room, maxWaitMs = 9000) {
    const deadline = Date.now() + Math.max(2000, Number(maxWaitMs) || 9000);
    let lastError = null;
    while (Date.now() < deadline) {
      if (!room?.pending) return { active:false };
      if (state.recovering) {
        await sleep(250);
        continue;
      }
      if (room.pending.reroll) {
        try { await checkPendingRoom(room); }
        catch (error) { lastError = error; }
        if (room.pending?.reroll) {
          await sleep(450);
          continue;
        }
      }

      const recent = await fetchRecentMessages(apiChatIdOf(room), 50);
      const latestAssistant = recent.find(message => messageRoleOf(message) === 'assistant');
      const latestId = messageIdOf(latestAssistant);
      if (!latestId) throw new Error('최근 AI 답변을 찾지 못했습니다.');
      if (String(latestId) !== String(room.pending.messageId || '')) {
        try {
          await reanchorAfterResponse(room, latestAssistant, { countTurn:false, reason:'reroll-sync' });
        } catch (error) {
          lastError = error;
          await sleep(450);
          continue;
        }
      }
      if (!room.pending) return { active:false };
      if (!room.pending.reroll && String(room.pending.messageId || '') === String(latestId)) {
        return { active:true, messageId:String(latestId) };
      }
      await sleep(350);
    }
    throw new Error(`이전 리롤의 주입 이동이 아직 끝나지 않았습니다.${lastError?.message ? ` · ${lastError.message}` : ''}`);
  }

  async function prepareRerollBridgeNow(room) {
    const p = room?.pending;
    if (!p) return { prepared: false, reason: 'inactive' };
    if (p.reroll) throw new Error('이전 리롤을 처리 중입니다. 잠시 뒤 다시 눌러 주세요.');

    const recent = await fetchRecentMessages(apiChatIdOf(room), 50);
    const sourceIndex = recent.findIndex(m => String(messageIdOf(m) || '') === String(p.messageId || ''));
    if (sourceIndex < 0 || messageRoleOf(recent[sourceIndex]) !== 'assistant') {
      throw new Error('리롤할 최신 AI 답변을 서버에서 찾지 못했습니다.');
    }
    const latestAssistant = recent.find(m => messageRoleOf(m) === 'assistant');
    if (String(messageIdOf(latestAssistant) || '') !== String(p.messageId || '')) {
      throw new Error('주입 위치가 최신 답변과 달라 먼저 자동 이동을 기다려야 합니다.');
    }

    const sourceLive = await carrierOriginalFromServer(room, p);
    if (!sourceLive.currentText) throw new Error('리롤할 AI 답변 원문을 읽지 못했습니다.');
    const sourceOriginal = sourceLive.original;
    const maxChars = Number(room.maxChars) || APP.defaultMaxChars;
    const originUserIndex = recent.findIndex((message, index) => index > sourceIndex && messageRoleOf(message) === 'user');
    if (originUserIndex < 0) throw new Error('리롤 대상 USER 입력을 서버 기록에서 찾지 못했습니다.');
    const originUserMessageId = String(messageIdOf(recent[originUserIndex]) || recent[originUserIndex]?.turnId || '');
    let bridgeMessage = null;
    let bridgeOriginal = '';
    let bridgeItems = [];
    let contextBlock = '';
    let injectedText = '';

    // 같은 USER 입력에서 갈라진 이전 리롤 답변은 새 답변의 생성 문맥에 포함되지 않습니다.
    // 따라서 반드시 리롤 대상 USER 입력보다 앞에 있는 AI 답변을 임시 carrier로 사용합니다.
    // 길이 제한에 걸리면 한 단계 더 오래된 AI 답변을 찾습니다.
    for (const candidate of recent.slice(originUserIndex + 1)) {
      if (messageRoleOf(candidate) !== 'assistant' || !messageIdOf(candidate)) continue;
      const raw = messageTextOf(candidate);
      if (!raw) continue;
      const clean = stripOurContextBlock(raw).text || raw;
      const items = activeItemsFittedForCarrier(room, p, clean);
      const block = buildContextBlockFromItems(items);
      const injected = block ? buildInjectedMessage(clean, block) : '';
      if (!block || injected.length > maxChars || !carrierRequestWithinLimits(room, injected)) continue;
      bridgeMessage = candidate;
      bridgeOriginal = clean;
      bridgeItems = items;
      contextBlock = block;
      injectedText = injected;
      break;
    }
    if (!bridgeMessage) throw new Error('리롤용 컨텍스트를 옮길 이전 AI 답변을 찾지 못했습니다.');

    const bridgeId = messageIdOf(bridgeMessage);
    const previousPending = { ...p, items: clonePendingItems(p.items) };
    let bridgeInjected = false;
    let sourceRestored = false;
    try {
      await patchMessage(apiChatIdOf(room), bridgeId, injectedText);
      const bridgePending = { ...p, messageId: bridgeId, originalText: bridgeOriginal };
      const verification = await verifyInjectedCarrier(room, bridgePending, injectedText);
      if (!verification.verified) throw new Error('리롤용 이전 답변에 숨김 컨텍스트를 붙이지 못했습니다.');
      bridgeInjected = true;

      await restoreCarrierOnly(room, p);
      sourceRestored = true;

      const nextPending = {
        ...p,
        messageId: bridgeId,
        originalText: bridgeOriginal,
        baselineAssistantId: String(p.messageId),
        armedAt: Date.now(),
        carrierArmedAt: Date.now(),
        contextBlock,
        injectedChars: contextBlock.length,
        originalChars: bridgeOriginal.length,
        carrierChars: injectedText.length,
        carrierMessageBytes: carrierRequestMetrics(injectedText).messageBytes,
        carrierPayloadBytes: carrierRequestMetrics(injectedText).payloadBytes,
        serverChars: verification.serverChars,
        verified: true,
        verifiedAt: Date.now(),
        reroll: {
          sourceMessageId: String(p.messageId),
          sourceOriginalText: sourceOriginal,
          originUserMessageId,
          bridgeMessageId: String(bridgeId),
          startedAt: Date.now(),
        },
      };
      // 예산에 맞춰 임시 carrier에 들어간 항목만 유지합니다. 유지 횟수 값은 그대로입니다.
      nextPending.items = clonePendingItems(bridgeItems);
      stampVerifiedPendingSnapshot(nextPending, bridgeItems, contextBlock);
      room.pending = nextPending;
      savePendingBackup(room.chatId, nextPending);
      await saveRoom(room);
      if (room.chatId === state.currentChatId) state.currentRoom = room;
      sanitizeRenderedContextSoon();
      return { prepared: true, bridgeId, sourceId: p.messageId };
    } catch (error) {
      // 리롤 실행 전 준비가 실패하면 기존 carrier 상태로 최대한 되돌립니다.
      if (bridgeInjected) {
        try { await patchMessage(apiChatIdOf(room), bridgeId, bridgeOriginal); } catch (_) {}
      }
      if (sourceRestored) {
        try {
          const previousBlock = previousPending.contextBlock || buildContextBlockFromItems(activePendingItems(previousPending));
          await patchMessage(apiChatIdOf(room), previousPending.messageId, buildInjectedMessage(sourceOriginal, previousBlock));
        } catch (_) {}
      }
      room.pending = previousPending;
      savePendingBackup(room.chatId, previousPending);
      try { await saveRoom(room); } catch (_) {}
      if (room.chatId === state.currentChatId) state.currentRoom = room;
      throw error;
    }
  }

  function prepareRerollBridge(room) {
    return queuePendingCarrierOperation(room, () => prepareRerollBridgeNow(room));
  }

  function bindRerollBridge() {
    if (state.rerollClickBound) return;
    state.rerollClickBound = true;
    document.addEventListener('click', event => {
      const control = rerollControlFromEventTarget(event.target);
      if (!control) return;
      if (state.rerollBypassElement === control) {
        state.rerollBypassElement = null;
        return;
      }
      const room = state.currentRoom;
      if (!room?.pending) return;

      event.preventDefault();
      event.stopPropagation();
      event.stopImmediatePropagation();
      if (state.rerollPreparing) {
        notify('리롤용 컨텍스트를 준비 중입니다. 잠시 뒤 다시 눌러 주세요.', 'warn', 4200);
        return;
      }

      state.rerollPreparing = true;
      (async () => {
        let prepared = false;
        let replay = false;
        try {
          const settled = await settleCarrierBeforeReroll(room);
          if (!settled.active) {
            replay = true;
            return;
          }
          const result = await prepareRerollBridge(room);
          prepared = !!result.prepared;
          replay = prepared;
        } catch (e) {
          console.warn('[RP매니저] reroll bridge preparation failed:', e);
          notify(`리롤을 잠시 멈췄습니다 · 주입문 없이 재생성하지 않도록 보호했습니다. 다시 눌러 주세요: ${e.message}`, 'warn', 7000);
        } finally {
          state.rerollPreparing = false;
          if (replay) replayRerollControl(control);
          if (prepared) scheduleRecovery(800);
        }
      })();
    }, true);
  }

  async function verifyInjectedCarrier(room, pending, expectedText, attempts = 4) {
    let lastText = '';
    for (let i = 0; i < attempts; i++) {
      if (i) await sleep([300, 650, 1100, 1600][Math.min(i - 1, 3)]);
      const current = await fetchMessage(apiChatIdOf(room), pending.messageId);
      if (!current) continue;
      const text = messageTextOf(current);
      lastText = text;
      const hasMarkers = text.includes(APP.markerStart) && text.includes(APP.markerEnd);
      const stripped = stripOurContextBlock(text);
      const originalMatches = stripped.found && normalizeLineBreaks(stripped.text) === normalizeLineBreaks(String(pending.originalText || '').replace(/\s+$/, ''));
      const exactMatches = normalizeLineBreaks(text) === normalizeLineBreaks(expectedText);
      if (hasMarkers && originalMatches && exactMatches) {
        return { verified: true, serverChars: text.length, text };
      }
    }
    return { verified: false, serverChars: lastText.length, text: lastText };
  }

  async function reverifyPending(room) {
    const p = room.pending;
    if (!p) throw new Error('현재 예약된 임시 주입이 없습니다.');
    const current = await fetchMessage(apiChatIdOf(room), p.messageId);
    if (!current) throw new Error('carrier AI 메시지를 서버에서 다시 읽지 못했습니다.');
    const text = messageTextOf(current);
    const stripped = stripOurContextBlock(text);
    const ok = stripped.found && normalizeLineBreaks(stripped.text) === normalizeLineBreaks(String(p.originalText || '').replace(/\s+$/, ''));
    p.verified = ok;
    p.verifiedAt = ok ? Date.now() : null;
    p.serverChars = text.length;
    await saveRoom(room);
    if (room.chatId === state.currentChatId) state.currentRoom = room;
    return { verified: ok, text, serverChars: text.length };
  }

  async function showInjectedRaw(room) {
    if (!room.pending) throw new Error('현재 예약된 임시 주입이 없습니다.');
    const result = await reverifyPending(room);
    const overlay = state.modal;
    if (!overlay) return;
    let viewer = overlay.querySelector('#rpcm-raw-viewer');
    if (viewer) viewer.remove();
    viewer = document.createElement('div');
    viewer.id = 'rpcm-raw-viewer';
    viewer.innerHTML = `
      <div class="rpcm-raw-card">
        <div class="rpcm-raw-head">
          <div><strong>${result.verified ? '✅ 서버 주입 확인됨' : '⚠️ 서버 주입 확인 실패'}</strong><div>carrier AI ${esc(shortId(room.pending.messageId))} · 서버 raw ${formatCount(result.serverChars)}자</div></div>
          <button class="rpcm-iconbtn" id="rpcm-raw-close" aria-label="닫기" data-rpcm-close="icon">✕</button>
        </div>
        <div class="rpcm-raw-note">${result.verified ? '아래는 서버에서 다시 읽은 현재 carrier AI의 실제 raw입니다. 일반 채팅 화면에는 숨김 블록이 보이지 않는 것이 정상이며, AI 응답이 생기면 이 블록은 최신 AI 메시지로 자동 이동합니다. 이 창에서는 수정하지 않습니다.' : '<b>숨김 주입 블록을 확인하지 못했습니다. 이 창을 닫고 ‘지금 해제’를 누른 뒤 다시 주입해 주세요.</b><br>아래는 서버에서 다시 읽은 현재 carrier AI의 실제 raw입니다.'}</div>
        <textarea class="rpcm-raw-text" readonly></textarea>
      </div>`;
    overlay.appendChild(viewer);
    viewer.querySelector('.rpcm-raw-text').value = result.text || '(서버 원문 없음)';
    viewer.querySelector('#rpcm-raw-close').onclick = () => viewer.remove();
  }

  async function carrierOriginalFromServer(room, p) {
    const current = await fetchMessage(apiChatIdOf(room), p.messageId);
    if (!current) return { found: false, original: '', currentText: '' };
    const currentText = messageTextOf(current);
    const stripped = stripOurContextBlock(currentText);
    if (stripped.found) {
      // Refiner가 주입 중인 메시지의 가시 본문을 교정했을 수 있습니다.
      // 세션 시작 때 저장한 p.originalText보다 서버의 최신 가시 본문을 우선합니다.
      return { found: true, original: stripped.text, currentText };
    }
    return { found: false, original: currentText, currentText };
  }

  async function verifyCarrierClean(room, messageId, expectedText, attempts = 3) {
    for (let i = 0; i < attempts; i++) {
      if (i) await sleep([250, 600][Math.min(i - 1, 1)]);
      const current = await fetchMessage(apiChatIdOf(room), messageId);
      if (!current) return { clean: true, reason: 'message_missing' };
      const text = messageTextOf(current);
      if (!stripOurContextBlock(text).found && normalizeLineBreaks(text) === normalizeLineBreaks(expectedText)) {
        return { clean: true, reason: 'verified' };
      }
    }
    return { clean: false, reason: 'verify_failed' };
  }

  async function restoreCarrierOnly(room, p) {
    const info = await carrierOriginalFromServer(room, p);
    if (!info.currentText) return { restored: false, reason: 'message_missing' };
    if (!stripOurContextBlock(info.currentText).found) return { restored: false, reason: 'already_clean' };
    const restoreText = info.original;
    if (restoreText == null) throw new Error('복원할 최신 AI 원문을 찾지 못했습니다.');
    await patchMessage(apiChatIdOf(room), p.messageId, restoreText);
    const verification = await verifyCarrierClean(room, p.messageId, restoreText);
    if (!verification.clean) throw new Error('AI 원문 복원 후 서버 재검증에 실패했습니다. 복구 정보는 유지됩니다.');
    return { restored: true, reason: 'ok' };
  }

  function clonePendingItems(items) {
    return (Array.isArray(items) ? items : []).map(i => ({ ...i }));
  }

  function pendingCarrierSyncKey(room) {
    return String(room?.chatId || room?.apiChatId || 'unknown-room');
  }

  function ensureVerifiedPendingSnapshot(pending) {
    if (!pending) return;
    if (!Array.isArray(pending.lastVerifiedItems)) pending.lastVerifiedItems = clonePendingItems(pending.items);
    if (typeof pending.lastVerifiedContextBlock !== 'string') pending.lastVerifiedContextBlock = String(pending.contextBlock || '');
  }

  function stampVerifiedPendingSnapshot(pending, items, contextBlock) {
    if (!pending) return pending;
    pending.lastVerifiedItems = clonePendingItems(items);
    pending.lastVerifiedContextBlock = String(contextBlock || '');
    return pending;
  }

  async function rollbackPendingCarrierUpdate(room, pending, previousInjectedText) {
    let rollbackVerified = false;
    try {
      await patchMessage(apiChatIdOf(room), pending.messageId, previousInjectedText);
      const rollback = await verifyInjectedCarrier(room, pending, previousInjectedText, 3);
      rollbackVerified = !!rollback.verified;
    } catch (_) {}
    if (!rollbackVerified) return false;

    const rollbackItems = clonePendingItems(pending.lastVerifiedItems);
    const rollbackBlock = String(pending.lastVerifiedContextBlock || pending.contextBlock || '');
    const restoredItems = rollbackItems.length ? rollbackItems : clonePendingItems(pending.items);
    const restored = stampVerifiedPendingSnapshot({
      ...pending,
      items: restoredItems,
      contextBlock: rollbackBlock,
      injectedChars: rollbackBlock.length,
      carrierChars: previousInjectedText.length,
      serverChars: previousInjectedText.length,
      verified: true,
      verifiedAt: Date.now(),
    }, restoredItems, rollbackBlock);
    room.pending = restored;
    savePendingBackup(room.chatId, restored);
    await saveRoom(room);
    if (room.chatId === state.currentChatId) state.currentRoom = room;
    return true;
  }

  function slotToPendingItem(slot) {
    return {
      slotId: slot.id,
      title: String(slot.title || slot.id || '메모').trim(),
      group: slot.group || 'extra',
      content: String(slot.content || '').trim(),
      totalTurns: normalizeRetentionTurns(slot.retentionTurns),
      usedTurns: 0,
      autoType: slot.lastAutoMatch ? (slot.group === 'character' ? 'character' : slot.group === 'item' ? 'important-item' : undefined) : undefined,
      matchedAlias: (slot.group === 'character' || slot.group === 'item') ? String(slot.lastAutoMatch || '') : '',
      autoConfidence: (slot.group === 'character' || slot.group === 'item') ? Number(slot.lastAutoConfidence || 0) : 0,
      autoDetectionReason: (slot.group === 'character' || slot.group === 'item') ? String(slot.lastAutoReason || '') : '',
      recallReason: (slot.group === 'character' || slot.group === 'item') && slot.lastAutoMatch ? (slot.lastAutoMatch === '사용자 고정' ? '사용자 고정' : (slot.lastAutoReason ? `신뢰도 ${Number(slot.lastAutoConfidence || 0)}% · 감지: ${slot.lastAutoReason}` : `“${slot.lastAutoMatch}” 감지`)) : '',
    };
  }

  function ensureDirectReleasePendingItems(room, pending) {
    if (!room || !pending) return { added: 0 };
    const items = Array.isArray(pending.items) ? pending.items : (pending.items = []);
    let added = 0;

    // 유지주기 0(직접 해제)은 AI 응답마다 차감되지 않아야 하며,
    // 다른 자동 갱신 과정에서 빠졌더라도 사용자가 체크를 유지 중이면 복구합니다.
    for (const slot of selectedSlots(room)) {
      if (slot.id === 'logSummary') continue;
      if (normalizeRetentionTurns(slot.retentionTurns) !== 0) continue;
      if (!String(slot.content || '').trim()) continue;
      const exists = activePendingItems(pending).some(i => i.slotId === slot.id);
      if (!exists) { items.push(slotToPendingItem(slot)); added++; }
    }

    // v0.8 로그요약은 원문 자체가 아니라 날짜 블록들이 carrier에 들어갑니다.
    // 로그요약이 '직접 해제'이고 체크된 상태라면 활성 로그가 통째로 유실된 경우에만 재구성합니다.
    const logSlot = (room.slots || []).find(s => s.id === 'logSummary');
    if (logSlot?.enabled && normalizeRetentionTurns(logSlot.retentionTurns) === 0 && String(logSlot.content || '').trim()) {
      const hasActiveLog = activePendingItems(pending).some(i => i.sourceSlotId === 'logSummary' || i.group === 'log-auto' || i.slotId === 'logSummary');
      if (!hasActiveLog) {
        const base = activePendingItems(pending).filter(i => i.sourceSlotId !== 'logSummary' && i.group !== 'log-auto' && i.slotId !== 'logSummary');
        const recalled = logRecallItems(room, room.autoRecallContextText || '', base, contextBudgetForCarrier(room, String(pending.originalText || '').length));
        if (recalled.length) { items.push(...recalled); added += recalled.length; }
      }
    }
    return { added };
  }

  async function syncPendingCarrierNow(room, reason = 'update') {
    const p = room.pending;
    if (!p) return { active: 0, cleared: false };
    ensureVerifiedPendingSnapshot(p);
    // 다른 편집기가 carrier의 가시 본문을 수정했다면 그 최신값을 기준으로
    // 숨김 블록을 다시 붙입니다. 과거 p.originalText로 교정 결과를 덮어쓰지 않습니다.
    const live = await carrierOriginalFromServer(room, p);
    if (live.currentText) p.originalText = live.original;
    ensureDirectReleasePendingItems(room, p);
    // 간편 주입 관리에서 끈 항목은 자동 최근로그 갱신이나 자동 고정 복구가 다시
    // 추가하더라도 현재 주입 세션이 끝날 때까지 제외 상태를 유지합니다.
    applyQuickItemSuppression(p);
    // 새 답변으로 carrier 이동이 실패한 복구 대기 상태에서는 이미 원문으로 복원된
    // 이전 AI 메시지에 다시 주입하지 않습니다. 편집한 항목은 pending에 보존하고
    // 같은 답변 재시도 또는 다음 AI 답변에서 새 carrier로 옮깁니다.
    if (p.reanchorRetry) {
      p.verified = false;
      savePendingBackup(room.chatId, p);
      await saveRoom(room);
      if (room.chatId === state.currentChatId) state.currentRoom = room;
      return { active:activePendingItems(p).length, cleared:false, suspended:true, reason };
    }
    let active = fitItemsToCarrierLimits(room, p.originalText, activePendingItems(p));
    const activeLogIds = new Set(active.filter(i => i.sourceSlotId === 'logSummary' || i.group === 'log-auto' || i.slotId === 'logSummary').map(i => i.slotId));
    const activeLoreIds = new Set(active.filter(i => i.group === 'lore').map(i => i.slotId));
    const activeLoreById = new Map(active.filter(i => i.group === 'lore').map(i => [i.slotId, i]));
    p.items = (p.items || []).filter(i => i.group === 'lore' ? activeLoreIds.has(i.slotId) : !(i.sourceSlotId === 'logSummary' || i.group === 'log-auto' || i.slotId === 'logSummary') || activeLogIds.has(i.slotId)).map(i => i.group === 'lore' ? (activeLoreById.get(i.slotId) || i) : i);
    if (!active.length) {
      await restoreCarrierOnly(room, p);
      room.pending = null;
      clearPendingBackup(room.chatId);
      await saveRoom(room);
      if (room.chatId === state.currentChatId) {
        state.currentRoom = room;
        notifyInjectionEnded(room, 'empty');
      }
      renderModalIfOpen();
      return { active: 0, cleared: true };
    }
    const contextBlock = buildContextBlockFromItems(active);
    const injectedText = buildInjectedMessage(p.originalText, contextBlock);
    const requestMetrics = assertCarrierRequestWithinLimits(room, injectedText, '변경 후 carrier 총 길이');
    const previousInjectedText = buildInjectedMessage(p.originalText, p.contextBlock || buildContextBlockFromItems(activePendingItems(p)));
    try {
      await patchMessage(apiChatIdOf(room), p.messageId, injectedText);
    } catch (patchError) {
      const rollbackVerified = await rollbackPendingCarrierUpdate(room, p, previousInjectedText);
      throw new Error(`주입 내용 서버 갱신 실패: ${patchError.message}. ${rollbackVerified ? '직전 정상 주입본으로 복원했으며 저장된 로그 원문은 유지됩니다.' : '복원 확인 전이므로 주입 백업을 유지했습니다.'}`);
    }
    const next = { ...p, contextBlock, injectedChars: contextBlock.length, carrierChars: injectedText.length, carrierMessageBytes:requestMetrics.messageBytes, carrierPayloadBytes:requestMetrics.payloadBytes, verified: false, verifiedAt: null };
    const verification = await verifyInjectedCarrier(room, next, injectedText);
    if (!verification.verified) {
      const rollbackVerified = await rollbackPendingCarrierUpdate(room, p, previousInjectedText);
      throw new Error(`변경된 주입문의 서버 확인에 실패했습니다. ${rollbackVerified ? '직전 정상 주입본으로 복원했으며 저장된 로그 원문은 유지됩니다.' : '복원 확인 전이므로 주입 백업을 유지했습니다.'} 전송 ${formatCount(requestMetrics.chars)}자 · 요청 본문 UTF-8 ${formatCount(requestMetrics.payloadBytes)}바이트`);
    }
    next.verified = true; next.verifiedAt = Date.now(); next.serverChars = verification.serverChars;
    stampVerifiedPendingSnapshot(next, active, contextBlock);
    room.pending = next;
    savePendingBackup(room.chatId, next);
    await saveRoom(room);
    if (room.chatId === state.currentChatId) state.currentRoom = room;
    sanitizeRenderedContextSoon();
    return { active: active.length, cleared: false, reason };
  }

  function queuePendingCarrierOperation(room, operation) {
    const key = pendingCarrierSyncKey(room);
    const previous = state.pendingCarrierSyncQueues.get(key) || Promise.resolve();
    // 앞 작업이 실패해도 다음 작업은 서버의 최신 상태를 다시 확인한 뒤 실행합니다.
    const task = previous.catch(() => {}).then(operation);
    state.pendingCarrierSyncQueues.set(key, task);
    return task.finally(() => {
      if (state.pendingCarrierSyncQueues.get(key) === task) state.pendingCarrierSyncQueues.delete(key);
    });
  }

  function syncPendingCarrier(room, reason = 'update') {
    if (!room?.pending) return Promise.resolve({ active: 0, cleared: false });
    const statusRevision = setCarrierSyncStatusUi(room, 'syncing');
    const withStatus = promise => promise.then(result => {
      finishCarrierSyncStatusUi(room, statusRevision, result.suspended ? 'suspended' : 'applied');
      return result;
    }, error => {
      finishCarrierSyncStatusUi(room, statusRevision, 'error');
      throw error;
    });
    const key = pendingCarrierSyncKey(room);
    const existing = state.pendingCarrierSyncRequests.get(key);
    if (existing) {
      // 진행 중 새 편집이 들어오면 오래된 요청을 계속 쌓지 않고 마지막 상태만 한 번 더 반영합니다.
      existing.requested = true;
      existing.reason = reason;
      return withStatus(existing.promise);
    }

    const request = { requested:true, reason, promise:null };
    request.promise = queuePendingCarrierOperation(room, async () => {
      let result = { active:0, cleared:false };
      while (request.requested && room.pending) {
        request.requested = false;
        try {
          result = await syncPendingCarrierNow(room, request.reason);
        } catch (error) {
          // 실패하는 동안 더 최신 편집이 예약됐다면 그 최신 상태로 한 번 다시 시도합니다.
          if (!request.requested) throw error;
        }
      }
      return result;
    }).finally(() => {
      if (state.pendingCarrierSyncRequests.get(key) === request) state.pendingCarrierSyncRequests.delete(key);
    });
    state.pendingCarrierSyncRequests.set(key, request);
    return withStatus(request.promise);
  }

  function replacePendingLogItems(room) {
    if (!room.pending) return 0;
    const p = room.pending;
    const previousLogs = activePendingItems(p).filter(i => i.slotId === 'logSummary' || i.sourceSlotId === 'logSummary' || i.group === 'log-auto');
    const previousBySource = new Map(previousLogs.map(i => [String(i.sourceKey || i.slotId || ''), i]));
    p.items = (Array.isArray(p.items) ? p.items : []).filter(i => i.slotId !== 'logSummary' && i.sourceSlotId !== 'logSummary' && i.group !== 'log-auto');
    const slot = (room.slots || []).find(s => s.id === 'logSummary');
    if (!slot?.enabled || !String(slot.content || '').trim()) return 0;
    const blocks = parseDatedLogBlocks(slot.content);
    if (blocks.length) pruneLogSelectionKeys(room, blocks);
    const base = activePendingItems(p).filter(i => i.slotId !== 'logSummary' && i.sourceSlotId !== 'logSummary' && i.group !== 'log-auto');
    const next = logRecallItems(room, room.autoRecallContextText || '', base, contextBudgetForCarrier(room, String(p.originalText || '').length));
    for (const item of next) {
      const prev = previousBySource.get(String(item.sourceKey || item.slotId || ''));
      if (!prev) continue;
      // 같은 날짜 블록이 재선정되면 이미 사용한 유지턴은 그대로 이어갑니다.
      // 관련성이 확인된 최근 연속로그는 다음 응답에서도 선정되면 유지턴을 다시 시작할 수 있습니다.
      const previousTotal = Number(prev.totalTurns || 0);
      const previousUsed = Number(prev.usedTurns || 0);
      const previousActive = previousTotal === 0 || previousUsed < previousTotal;
      item.usedTurns = item.autoType === 'recent-log' && !previousActive ? 0 : previousUsed;
      item.totalTurns = normalizeRetentionTurns(slot.retentionTurns);
    }
    p.items.push(...next);
    return next.length;
  }

  async function rebuildPendingLogItems(room, reason = 'log-mode-change') {
    if (!room.pending) return;
    replacePendingLogItems(room);
    return await syncPendingCarrier(room, reason);
  }

  function isStoryTimelinePendingItem(item) {
    return pendingItemIdentity(item) === pendingItemIdentity({ slotId:'story-timeline:master', group:'story-timeline' });
  }

  function mergeStoryTimelinePendingItem(previous, fresh) {
    if (!fresh) return null;
    return {
      ...fresh,
      totalTurns:previous ? Number(previous.totalTurns || 0) : Number(fresh.totalTurns || 0),
      usedTurns:previous ? Number(previous.usedTurns || 0) : Number(fresh.usedTurns || 0),
    };
  }

  function sameStoryTimelinePendingPayload(a, b) {
    if (!a || !b) return !a && !b;
    return String(a.slotId || '') === String(b.slotId || '')
      && String(a.title || '') === String(b.title || '')
      && String(a.group || '') === String(b.group || '')
      && String(a.autoType || '') === String(b.autoType || '')
      && String(a.content || '') === String(b.content || '');
  }

  async function rebuildPendingStoryTimelineItem(room, reason = 'story-timeline-edit') {
    if (!room?.pending) return { payloadChanged:false, synced:false, suppressed:false };
    const pending = room.pending;
    ensureVerifiedPendingSnapshot(pending);

    const items = Array.isArray(pending.items) ? pending.items : (pending.items = []);
    const removedItems = quickRemovedPendingItems(pending);
    const activeStoryItems = items.filter(isStoryTimelinePendingItem);
    const activeStory = activeStoryItems[0] || null;
    const removedStoryItems = removedItems.filter(isStoryTimelinePendingItem);
    const removedStory = removedStoryItems[0] || null;
    const freshStory = storyTimelineInjectionItems(room)[0] || null;

    // 간편 주입 관리에서 타임라인을 직접 꺼둔 경우에는 그 선택을 보존합니다.
    // 다시 켤 때 구버전 타임라인이 들어가지 않도록 꺼진 항목의 복사본만 최신화합니다.
    if (removedStory) {
      const refreshedRemoved = freshStory
        ? mergeStoryTimelinePendingItem(removedStory, freshStory)
        : { ...removedStory, content:'' };
      const nextRemoved = [];
      let storyAdded = false;
      for (const item of removedItems) {
        if (!isStoryTimelinePendingItem(item)) { nextRemoved.push(item); continue; }
        if (!storyAdded) { nextRemoved.push(refreshedRemoved); storyAdded = true; }
      }
      if (!storyAdded) nextRemoved.push(refreshedRemoved);

      const hadActiveStory = activeStoryItems.length > 0;
      const removedChanged = removedStoryItems.length !== 1 || !sameStoryTimelinePendingPayload(removedStory, refreshedRemoved);
      if (!hadActiveStory && !removedChanged) return { payloadChanged:false, synced:false, suppressed:true };

      pending.items = items.filter(item => !isStoryTimelinePendingItem(item));
      pending.quickRemovedItems = nextRemoved;
      savePendingBackup(room.chatId, pending);
      await saveRoom(room);

      if (hadActiveStory) {
        const result = await syncPendingCarrier(room, reason);
        return { payloadChanged:true, synced:true, suppressed:true, ...result };
      }
      if (room.chatId === state.currentChatId) state.currentRoom = room;
      return { payloadChanged:true, synced:false, suppressed:true };
    }

    const nextItems = items.filter(item => !isStoryTimelinePendingItem(item));
    if (freshStory) nextItems.push(mergeStoryTimelinePendingItem(activeStory, freshStory));

    const expectedCount = freshStory ? 1 : 0;
    const payloadChanged = activeStoryItems.length !== expectedCount || !sameStoryTimelinePendingPayload(activeStory, freshStory);
    if (!payloadChanged) return { payloadChanged:false, synced:false, suppressed:false };

    // 타임라인 항목만 교체하고 현재상태·로그·캐릭터·중요 물품·기타의 유지 진행도는 건드리지 않습니다.
    pending.items = nextItems;
    const result = await syncPendingCarrier(room, reason);
    return { payloadChanged:true, synced:true, suppressed:false, ...result };
  }

  async function syncEditedSlotIntoPending(room, slot, reason = 'slot-content-edit') {
    if (!room?.pending || !slot) return false;
    // 편집으로 pending.items가 바뀌기 전에 직전 서버 검증 상태를 확보합니다.
    // 실패 시 편집한 저장 원문은 유지하면서 carrier만 이 상태로 되돌립니다.
    ensureVerifiedPendingSnapshot(room.pending);
    if (slot.id === 'logSummary') {
      await rebuildPendingLogItems(room, reason === 'slot-content-edit' ? 'log-content-edit' : reason);
      return true;
    }

    const items = Array.isArray(room.pending.items) ? room.pending.items : (room.pending.items = []);
    const idx = items.findIndex(i => i.slotId === slot.id && (Number(i.totalTurns || 0) === 0 || Number(i.usedTurns || 0) < Number(i.totalTurns || 0)));
    if (idx < 0) return false;

    if (!String(slot.content || '').trim()) {
      items.splice(idx, 1);
      await syncPendingCarrier(room, reason);
      return true;
    }

    // 본문을 수정해도 기존 유지턴 진행도는 리셋하지 않습니다.
    items[idx] = {
      ...items[idx],
      title: String(slot.title || slot.id || '메모').trim(),
      group: slot.group || items[idx].group || 'extra',
      content: String(slot.content || '').trim(),
    };
    await syncPendingCarrier(room, reason);
    return true;
  }

  async function setSlotEnabledDuringPending(room, slot, enabled) {
    if (!room.pending) {
      slot.enabled = enabled;
      await saveRoom(room);
      return;
    }
    const previousEnabled = !!slot.enabled;
    const previousItems = clonePendingItems(room.pending.items);
    const previousQuickRemoved = clonePendingItems(room.pending.quickRemovedItems);
    slot.enabled = enabled;
    try {
      const items = Array.isArray(room.pending.items) ? room.pending.items : (room.pending.items = []);
      if (slot.id === 'logSummary') {
        if (enabled) room.pending.quickRemovedItems = quickRemovedPendingItems(room.pending).filter(item => !(item.sourceSlotId === 'logSummary' || item.group === 'log-auto' || item.slotId === 'logSummary'));
        replacePendingLogItems(room);
      } else {
        if (enabled) {
          const key = pendingItemIdentity({ slotId:slot.id, group:slot.group });
          room.pending.quickRemovedItems = quickRemovedPendingItems(room.pending).filter(item => pendingItemIdentity(item) !== key);
        }
        const idx = items.findIndex(i => i.slotId === slot.id);
        if (enabled) {
          const nextItem = slotToPendingItem(slot);
          if (idx >= 0) items[idx] = nextItem;
          else items.push(nextItem);
        } else if (idx >= 0) {
          items.splice(idx, 1);
        }
      }
      await syncPendingCarrier(room, enabled ? 'manual-add' : 'manual-remove');
      notify(enabled ? `‘${slot.title}’ 현재 주입에 추가 · ${retentionLabel(slot.retentionTurns)} 새로 시작` : `‘${slot.title}’ 현재 주입에서 제거`, 'success', 4200);
    } catch (e) {
      slot.enabled = previousEnabled;
      if (room.pending) {
        room.pending.items = previousItems;
        room.pending.quickRemovedItems = previousQuickRemoved;
      }
      await saveRoom(room);
      throw e;
    }
  }

  function closeQuickInjectionPanel({ cancelQueued = false } = {}) {
    if (cancelQueued) {
      clearTimeout(state.quickApplyTimer);
      state.quickApplyTimer = null;
      state.quickDesired.clear();
    }
    state.quickPanel?.remove();
    state.quickPanel = null;
    updateFab();
  }

  async function applyQueuedQuickChanges() {
    state.quickApplyTimer = null;
    if (state.quickApplying || !state.quickDesired.size) return;
    const room = state.currentRoom;
    const pending = room?.pending;
    if (!room || !pending) {
      state.quickDesired.clear();
      closeQuickInjectionPanel({ cancelQueued:true });
      return;
    }

    const desired = new Map(state.quickDesired);
    state.quickDesired.clear();
    const previousItems = clonePendingItems(pending.items);
    const previousRemoved = clonePendingItems(pending.quickRemovedItems);
    const known = new Map();
    for (const item of [...previousItems, ...previousRemoved]) {
      const key = pendingItemIdentity(item);
      if (key && !known.has(key)) known.set(key, item);
    }

    state.quickApplying = true;
    renderQuickInjectionPanel();
    let changed = 0;
    try {
      for (const [key, enabled] of desired) {
        const source = known.get(key);
        if (!source) continue;
        const isActive = (pending.items || []).some(item => pendingItemIdentity(item) === key);
        if (enabled && !isActive) {
          pending.quickRemovedItems = quickRemovedPendingItems(pending).filter(item => pendingItemIdentity(item) !== key);
          pending.items = Array.isArray(pending.items) ? pending.items : [];
          pending.items.push({ ...source });
          changed++;
        } else if (!enabled && isActive) {
          pending.quickRemovedItems = quickRemovedPendingItems(pending).filter(item => pendingItemIdentity(item) !== key);
          pending.quickRemovedItems.push({ ...source });
          pending.items = (pending.items || []).filter(item => pendingItemIdentity(item) !== key);
          changed++;
        }
      }
      if (!changed) return;
      const result = await syncPendingCarrier(room, 'quick-panel');
      if (result.cleared || !room.pending) {
        closeQuickInjectionPanel({ cancelQueued:true });
        return;
      }
      notify(`현재 주입 항목 ${result.active}개로 변경했습니다.`, 'success', 3000);
    } catch (e) {
      if (room.pending) {
        room.pending.items = previousItems;
        room.pending.quickRemovedItems = previousRemoved;
        savePendingBackup(room.chatId, room.pending);
        await saveRoom(room).catch(() => {});
      }
      notify(`간편 주입 변경 실패: ${e.message}`, 'error', 6500);
    } finally {
      state.quickApplying = false;
      renderQuickInjectionPanel();
      updateFab();
      if (state.quickDesired.size) {
        clearTimeout(state.quickApplyTimer);
        state.quickApplyTimer = setTimeout(() => applyQueuedQuickChanges(), 450);
      }
    }
  }

  function queueQuickItemToggle(key, enabled) {
    if (!key) return;
    state.quickDesired.set(String(key), !!enabled);
    clearTimeout(state.quickApplyTimer);
    state.quickApplyTimer = setTimeout(() => applyQueuedQuickChanges(), 450);
  }

  function quickMonitorStatus(room) {
    if (!room) return { items:[], used:0, percent:0, armed:false, warningCount:0, warning:false, capacityNear:false, busy:false, label:'주입 OFF' };
    const pending = room?.pending;
    const items = pending ? activePendingItems(pending) : [];
    const used = pending ? Number(pending.carrierChars || pending.injectedChars || 0) : 0;
    const percent = Math.max(0, Math.min(100, Math.round(used / APP.defaultMaxChars * 100)));
    const cache = state.quickMonitorWarningCache;
    const stamp = String(room?.updatedAt || '');
    let warningCount = 0;
    if (cache && cache.chatId === room.chatId && cache.stamp === stamp && Date.now() - cache.at < 3000) warningCount = cache.count;
    else { warningCount = room ? getDataWarnings(room).length : 0; state.quickMonitorWarningCache = { chatId:room?.chatId, stamp, count:warningCount, at:Date.now() }; }
    const loreOmitted = Math.max(0, Number(loreBudgetInfoFor(room)?.candidates || 0) - Number(loreBudgetInfoFor(room)?.included || 0));
    warningCount += loreOmitted ? 1 : 0;
    const carrierWarning = !!pending && (!pending.verified || !!pending.reanchorRetry || used > APP.defaultMaxChars);
    warningCount += carrierWarning ? 1 : 0;
    const warning = warningCount > 0;
    const busy = !!state.quickApplying || !!manualUpdateRuntime?.commits?.size;
    const capacityNear = !!pending && (statusForChars(used, APP.defaultMaxChars).cls === 'warn' || statusForChars(used, APP.defaultMaxChars).cls === 'bad');
    return { items, used, percent, armed:!!pending, warningCount, warning, capacityNear, busy, label:pending ? (warning ? '주입 ON · 확인 필요' : '주입 ON') : '주입 OFF' };
  }

  function quickMonitorRing(status) {
    return `<span class="rpcm-monitor-ring${status.warning ? ' is-warning' : ''}${status.busy ? ' is-busy' : ''}${!status.armed ? ' is-off' : ''}" style="--rpcm-ring:${status.armed ? status.percent : 0}%" role="img" aria-label="${status.label} · 현재 주입 용량 ${status.percent}%"><b>${status.armed ? 'ON' : 'OFF'}</b></span>`;
  }

  function quickMonitorCategories(items) {
    const counts = new Map();
    for (const item of items) { const key = itemCategory(item); counts.set(key, (counts.get(key) || 0) + 1); }
    return counts.size ? [...counts].map(([label, count]) => `<span class="rpcm-monitor-category tone-${categoryTone(label)}">${esc(label)} <b>${count}</b></span>`).join('') : '<span class="rpcm-monitor-category">현재 주입 0개</span>';
  }

  function renderQuickInjectionPanel() {
    const backdrop = state.quickPanel;
    if (!backdrop?.isConnected) return;
    const room = state.currentRoom;
    const pending = room?.pending;
    const rows = pending ? quickManageItems(pending) : [];
    const active = rows.filter(row => row.active);
    const removed = rows.filter(row => !row.active);
    const stats = statsForItems(active.map(row => row.item));
    const capacity = carrierCapacityForUi(room, stats.block, buildContextBlockFromItems(active.map(row => row.item)));
    const monitor = quickMonitorStatus(room);
    const rowHtml = (row, index) => {
      const item = row.item;
      const category = itemCategory(item);
      const queued = state.quickDesired.has(row.key) ? state.quickDesired.get(row.key) : row.active;
      return `<label data-key="quick-${esc(row.key)}" class="rpcm-quick-row${queued ? '' : ' is-off'}">
        <input type="checkbox" data-rpcm-quick-index="${index}" ${queued ? 'checked' : ''} ${state.quickApplying ? 'disabled' : ''}>
        <span class="rpcm-quick-badge tone-${categoryTone(category)}">${esc(category)}</span>
        <span class="rpcm-quick-copy"><strong>${esc(item.title || category)}</strong><small>${formatCount(String(item.content || '').length)}자 · ${esc(remainingLabelForItem(item))}${itemReason(item) ? ` · ${esc(itemReason(item))}` : ''}${relatedLogEvidence(item) ? ` · ${esc(relatedLogEvidence(item))}` : ''}</small></span>
      </label>`;
    };
    const ordered = [...active, ...removed];
    rpcmPatchHtml(backdrop, `<div class="rpcm-quick-shade" data-key="shade"></div><aside class="rpcm-quick-panel" data-key="panel" role="dialog" aria-modal="true" aria-label="Quick Monitor">
      <div class="rpcm-quick-head">${quickMonitorRing(monitor)}<div><strong>Quick Monitor</strong><span>${monitor.label} · ${active.length}개 · ${formatCount(monitor.used)} / 45,000자 · ${monitor.percent}%${capacity.byteKnown && pending ? ` · UTF-8 요청 ${formatCount(capacity.payloadBytes)} / ${formatCount(capacity.byteLimit)}바이트` : ''}</span></div><button type="button" class="rpcm-quick-close" aria-label="닫기" data-rpcm-close="icon">✕</button></div>
      <div class="rpcm-monitor-summary"><span class="rpcm-monitor-state${monitor.warning ? ' is-warning' : ''}">${monitor.label}</span><span class="rpcm-monitor-issues">확인할 일 ${monitor.warningCount}</span>${monitor.capacityNear ? '<span class="rpcm-monitor-issues">정리 권장</span>' : ''}<div class="rpcm-monitor-categories">${quickMonitorCategories(monitor.items)}</div></div>
      <div class="rpcm-quick-note">${pending ? '체크를 끄면 현재 주입에서만 빠집니다. 저장된 원문과 다음 주입의 기본 선택은 바뀌지 않습니다.' : '현재 주입은 꺼져 있습니다. 전체 RP Manager에서 자료집을 포함한 다음 주입 구성을 확인할 수 있습니다.'}${room?._logBudgetInfo?.omitted ? ` · 로그 ${room._logBudgetInfo.omitted}개 용량 제외${room._logBudgetInfo.omittedTitles?.length ? `: ${esc(room._logBudgetInfo.omittedTitles.join(', '))}` : ''}` : ''}${loreBudgetInfoFor(room)?.candidates > loreBudgetInfoFor(room)?.included ? ` · 자료집 ${loreBudgetInfoFor(room).candidates - loreBudgetInfoFor(room).included}개 용량 제외${loreBudgetInfoFor(room)?.omittedTitles?.length ? `: ${esc(loreBudgetInfoFor(room).omittedTitles.join(', '))}` : ''}` : ''}</div>
      <div class="rpcm-quick-list" data-key="list">
        ${active.length ? `<div class="rpcm-quick-group-title">주입 중 ${active.length}</div>${active.map((row, index) => rowHtml(row, index)).join('')}` : '<div class="rpcm-quick-empty">현재 주입 중인 항목이 없습니다.</div>'}
        ${removed.length ? `<div class="rpcm-quick-group-title is-muted">이번 주입에서 끈 항목 ${removed.length}</div>${removed.map((row, index) => rowHtml(row, active.length + index)).join('')}` : ''}
      </div>
      <div class="rpcm-quick-foot"><span>${state.quickApplying ? '서버에 반영 중…' : state.quickDesired.size ? '변경 사항을 곧 반영합니다…' : pending ? '여러 항목을 연달아 바꾸면 한 번에 반영됩니다.' : '주입 시작 전 구성을 확인하세요.'}</span><button type="button" class="rpcm-btn secondary rpcm-quick-open-full">전체 RP Manager</button>${pending ? '<button type="button" class="rpcm-btn warn rpcm-quick-disarm">주입 해제</button>' : '<button type="button" class="rpcm-btn primary rpcm-quick-arm">주입 시작</button>'}<button type="button" class="rpcm-btn secondary rpcm-quick-done" aria-label="닫기" data-rpcm-close="text">닫기</button></div>
    </aside>`);

    backdrop.querySelector('.rpcm-quick-shade').onclick = () => closeQuickInjectionPanel();
    backdrop.querySelector('.rpcm-quick-close').onclick = () => closeQuickInjectionPanel();
    backdrop.querySelector('.rpcm-quick-done').onclick = () => closeQuickInjectionPanel();
    if (backdrop.querySelector('.rpcm-quick-arm')) backdrop.querySelector('.rpcm-quick-arm').onclick = async event => { event.currentTarget.disabled = true; try { await armInjection(room); renderQuickInjectionPanel(); updateFab(); } catch (error) { notify(`주입 시작 실패: ${error.message}`, 'error'); event.currentTarget.disabled = false; } };
    if (backdrop.querySelector('.rpcm-quick-disarm')) backdrop.querySelector('.rpcm-quick-disarm').onclick = async event => {
      event.currentTarget.disabled = true;
      clearTimeout(state.quickApplyTimer); state.quickApplyTimer = null; state.quickDesired.clear();
      try { await restorePending(room, 'manual'); renderQuickInjectionPanel(); updateFab(); }
      catch (error) { notify(`주입 해제 실패: ${error.message}`, 'error'); if (event.currentTarget.isConnected) event.currentTarget.disabled = false; }
    };

    backdrop.querySelector('.rpcm-quick-open-full').onclick = async () => {
      if (state.quickDesired.size) {
        clearTimeout(state.quickApplyTimer);
        state.quickApplyTimer = null;
        await applyQueuedQuickChanges();
      }
      closeQuickInjectionPanel();
      await openModal();
    };
    backdrop.querySelectorAll('[data-rpcm-quick-index]').forEach(input => {
      input.onchange = () => {
        const row = ordered[Number(input.dataset.rpcmQuickIndex)];
        if (!row) return;
        input.closest('.rpcm-quick-row')?.classList.toggle('is-off', !input.checked);
        queueQuickItemToggle(row.key, input.checked);
        const note = backdrop.querySelector('.rpcm-quick-foot>span');
        if (note) note.textContent = '변경 사항을 곧 반영합니다…';
      };
    });
  }

  // 버튼을 누르는 동안 필요한 방 초기화를 시작합니다. 현재 방이 준비돼 있으면
  // 여는 순간 메타 API를 다시 기다리지 않고 같은 메모리 상태를 사용합니다.
  function prepareManagerOpenRoom(chatId) {
    const roomKey = getRoomScopeKey(chatId);
    if (state.currentChatId === roomKey && state.currentRoom?.chatId === roomKey) return state.currentRoom;
    if (state.managerOpenRoomScope === roomKey && state.managerOpenRoomPromise) return state.managerOpenRoomPromise;
    state.managerOpenRoomScope = roomKey;
    const pending = ensureCurrentRoom(chatId).then(() => {
      if (getRoomScopeKey(getChatIdFromPath()) !== roomKey || state.currentRoom?.chatId !== roomKey) {
        throw new Error('채팅방이 바뀌었습니다. 현재 방에서 다시 열어 주세요.');
      }
      return state.currentRoom;
    }).finally(() => {
      if (state.managerOpenRoomPromise === pending) {
        state.managerOpenRoomPromise = null;
        state.managerOpenRoomScope = '';
      }
    });
    state.managerOpenRoomPromise = pending;
    return pending;
  }

  async function openQuickInjectionPanel() {
    const chatId = getChatIdFromPath();
    if (!chatId) {
      notify('채팅방 화면에서만 사용할 수 있습니다.', 'warn');
      return;
    }
    const roomReady = prepareManagerOpenRoom(chatId);
    if (roomReady?.then) await roomReady;
    manualRestoreDrafts(state.currentRoom);
    if (state.modal) closeModal();
    closeQuickInjectionPanel();
    const backdrop = document.createElement('div');
    backdrop.id = 'rpcm-quick-backdrop';
    document.body.appendChild(backdrop);
    state.quickPanel = backdrop;
    backdrop.addEventListener('keydown', event => {
      if (event.key === 'Escape') closeQuickInjectionPanel();
    });
    renderQuickInjectionPanel();
    backdrop.querySelector('.rpcm-quick-close')?.focus();
    updateFab();
  }

  // v0.14.94: pseudo-element 원형 채움 진행률을 브라우저별 transform 표현 차이에도 안전하게 읽습니다.
  function rpcmMonitorFillProgress(trigger, pressedAt, holdMs) {
    const fallback=Math.max(0,Math.min(1,(performance.now()-pressedAt)/Math.max(1,holdMs)));
    try {
      const transform=getComputedStyle(trigger,'::before').transform;
      if(!transform||transform==='none')return fallback;
      const Matrix=globalThis.DOMMatrixReadOnly||globalThis.WebKitCSSMatrix;
      if(typeof Matrix==='function'){
        const matrix=new Matrix(transform),scale=Math.hypot(Number(matrix.a??matrix.m11??0),Number(matrix.b??matrix.m12??0));
        if(Number.isFinite(scale)&&scale>=0)return Math.max(0,Math.min(1,scale));
      }
      const match=transform.match(/^matrix\(([^)]+)\)$/);
      if(match){const scale=Math.abs(Number(match[1].split(',')[0]));if(Number.isFinite(scale))return Math.max(0,Math.min(1,scale));}
    } catch (_) {}
    return fallback;
  }

  // The monitor lives in the stable header action row; composer controls are never used as anchors.
  function rpcmBindMonitorPress(trigger) {
    let holdTimer=0, openTimer=0, resetTimer=0, fired=false, pointerId=null, pressRoomId='', pressedAt=0, startX=0, startY=0;
    const tapMs=360, holdMs=540;
    const warmRoom=()=>{const chatId=getChatIdFromPath();if(chatId){const ready=prepareManagerOpenRoom(chatId);if(ready?.then)ready.catch(()=>{});}};
    const releasePointer=()=>{
      const id=pointerId;pointerId=null;
      try{if(id!=null&&trigger.hasPointerCapture(id))trigger.releasePointerCapture(id);}catch(_){}
    };
    const clear=(completed=false)=>{
      clearTimeout(holdTimer);holdTimer=0;clearTimeout(openTimer);openTimer=0;
      clearTimeout(resetTimer);resetTimer=0;trigger.classList.remove('is-holding','is-hold-complete');
      releasePointer();trigger.rpcmPressRoomId='';trigger.style.removeProperty('--rpcm-fill-start');
      if(completed){trigger.classList.add('is-hold-complete');resetTimer=setTimeout(()=>trigger.classList.remove('is-hold-complete'),180);}
    };
    const valid=()=>trigger.isConnected&&!trigger.disabled&&pressRoomId===String(state.currentChatId||'');
    const cancel=()=>{fired=true;clear();};trigger.rpcmCancelHold=cancel;
    const finishQuick=()=>{
      if(!valid()){cancel();return;}clear(true);
      if(state.quickPanel)closeQuickInjectionPanel();else openQuickInjectionPanel().catch(error=>notify(error.message,'error'));
    };
    trigger.oncontextmenu=event=>event.preventDefault();
    document.addEventListener('visibilitychange',()=>{if(document.hidden)cancel();});
    trigger.onpointerdown=event=>{
      if(trigger.disabled||event.isPrimary===false||(event.button!==undefined&&event.button!==0)||openTimer)return;
      event.preventDefault();event.stopPropagation();clear();fired=false;pointerId=event.pointerId;pressRoomId=String(state.currentChatId||'');trigger.rpcmPressRoomId=pressRoomId;pressedAt=performance.now();startX=event.clientX;startY=event.clientY;
      trigger.style.setProperty('--rpcm-hold-ms',`${holdMs}ms`);
      trigger.classList.add('is-holding');warmRoom();
      try{trigger.setPointerCapture(pointerId);}catch(_){}
      holdTimer=setTimeout(()=>{
        if(!valid()){cancel();return;}fired=true;clear(true);
        try{navigator.vibrate?.(12);}catch(_){}
        closeQuickInjectionPanel();openModal().catch(error=>notify(error.message,'error'));
      },holdMs);
    };
    trigger.onpointermove=event=>{if(pointerId===event.pointerId&&Math.hypot(event.clientX-startX,event.clientY-startY)>14)cancel();};
    trigger.onpointercancel=cancel;
    trigger.onlostpointercapture=()=>{if(pointerId!==null&&holdTimer&&!fired)cancel();};
    trigger.onpointerup=event=>{
      if(pointerId===null||pointerId!==event.pointerId)return;
      event.stopPropagation();const tapped=!fired;clearTimeout(holdTimer);holdTimer=0;releasePointer();fired=true;
      if(tapped){
        const elapsed=performance.now()-pressedAt;
        const remaining=Math.max(0,tapMs-elapsed);
        // 길게 누르기 진행률을 유지하고, 손을 떼면 남은 채우기만 짧게 마칩니다.
        const progress=rpcmMonitorFillProgress(trigger,pressedAt,holdMs);
        trigger.classList.remove('is-holding');
        trigger.style.setProperty('--rpcm-fill-start',String(progress));
        trigger.style.setProperty('--rpcm-hold-ms',`${remaining}ms`);
        void trigger.offsetWidth;
        trigger.classList.add('is-holding');
        if(!remaining)finishQuick();
        else openTimer=setTimeout(()=>{openTimer=0;finishQuick();},remaining);
      }else clear();
    };
    trigger.onclick=event=>{
      if(event.detail!==0||trigger.disabled||openTimer||pointerId!==null)return;
      clear();pressRoomId=String(state.currentChatId||'');trigger.rpcmPressRoomId=pressRoomId;
      trigger.style.setProperty('--rpcm-hold-ms','360ms');trigger.classList.add('is-holding');warmRoom();
      openTimer=setTimeout(()=>{openTimer=0;finishQuick();},360);
    };
  }
  function updateQuickInjectionTrigger() {
    const trigger = state.fab;
    const draftPopup=document.getElementById('rpcm-ai-draft-popup');
    if(draftPopup&&draftPopup.dataset.roomId!==String(state.currentChatId||''))draftPopup.remove();
    // Remove a trigger left by an earlier script instance without touching host controls.
    document.getElementById('rpcm-monitor-slot')?.remove();
    document.getElementById('rpcm-quick-trigger')?.remove();
    if (!trigger) return;
    if (trigger.rpcmPressRoomId && trigger.rpcmPressRoomId !== String(state.currentChatId || '')) trigger.rpcmCancelHold?.();
    const monitor = quickMonitorStatus(state.currentRoom);
    trigger.classList.toggle('is-on', monitor.armed);
    trigger.classList.toggle('is-off', !monitor.armed);
    trigger.classList.toggle('is-warning', monitor.warning || monitor.capacityNear);
    trigger.classList.toggle('is-busy', monitor.busy);
    trigger.classList.toggle('is-active', !!state.quickPanel);
    trigger.classList.toggle('is-manager-open', !!state.modal);
    trigger.setAttribute('aria-expanded',String(!!state.quickPanel));
    trigger.setAttribute('aria-label',`WISH · ${monitor.armed?'주입 켜짐':'주입 꺼짐'}${monitor.busy?' · 반영 중':''} · 짧게 누르면 빠른 관리, 길게 누르면 전체 RP Manager`);
    trigger.title=`WISH · ${monitor.armed?'주입 켜짐':'주입 꺼짐'}${monitor.warning?' · 확인할 일 있음':''} · 짧게 누르면 빠른 관리, 길게 누르면 전체 RP Manager`;
    trigger.querySelector('.rpcm-header-monitor-label').textContent='WISH';
    if (state.modal) trigger.rpcmCancelHold?.();
    trigger.disabled = !!state.modal;
  }

  function newMessagesSinceLastScan(room, recentMessages) {
    const recent = (recentMessages || []).filter(m => ['user','assistant'].includes(messageRoleOf(m)));
    if (!recent.length) return [];
    const lastId = String(room.autoScanLastMessageId || '');
    let fresh;
    if (!lastId) fresh = recent.slice(0, Math.min(APP.autoScanMessageLimit, recent.length));
    else {
      const idx = recent.findIndex(m => String(messageIdOf(m) || '') === lastId);
      fresh = idx >= 0 ? recent.slice(0, idx) : recent.slice(0, Math.min(4, recent.length));
    }
    room.autoScanLastMessageId = String(messageIdOf(recent[0]) || room.autoScanLastMessageId || '');
    return fresh;
  }

  async function autoDetectCharacters(room, freshMessages) {
    if (!room.autoCharacterDetection) return { detected: [], added: 0, reset: 0 };
    const library = room.autoCharacterLibraryId ? await getCharacterLibrary(room.autoCharacterLibraryId) : null;
    // Manager/로어가 숨겨 주입한 기억은 후보 근거로 쓰지 않습니다.
    // 마커 블록을 제거하고 남은 실제 RP 본문에서만 등록 이름·별칭을 찾습니다.
    const text = (freshMessages || []).map(m => stripAutomationNoise(messageTextOf(m), true)).filter(Boolean).join('\n\n');
    const chars = (room.slots || []).filter(s => s.group === 'character');
    const byKey = new Map(chars.map(s => [libraryItemKey(s), s]));
    const detected = [];
    let added = 0, reset = 0;

    for (const src of (library?.characters || [])) {
      const key = libraryItemKey(src);
      let slot = byKey.get(key);
      const evidence = text ? characterRpDetectionEvidence(text, src) : { accepted:false };
      const matched = evidence.accepted ? evidence.matched : null;
      // 📌 자동 고정은 '감지 이벤트'가 아니라 항상 유지되는 사용자 상태입니다.
      // 매 폴링마다 감지된 것으로 반환하면 토스트가 반복되고 모달이 재렌더링되어 스크롤이 위로 튀므로
      // 실제 최근 RP에서 이름/별칭이 잡힌 경우에만 detected에 포함합니다.
      if (!matched) continue;
      if (slot?.autoExcluded) continue;
      if (!slot) {
        slot = makeDynamicSlot('character', String(src.title || '캐릭터'));
        slot.aliases = Array.isArray(src.aliases) ? [...src.aliases] : [];
        slot.content = String(src.content || '');
        slot.retentionTurns = normalizeRetentionTurns(src.retentionTurns);
        slot.autoExcluded = false;
        slot.autoPinned = false;
        room.slots.push(slot);
        byKey.set(key, slot);
        added++;
      }
      if (!String(slot.content || '').trim()) slot.content = String(src.content || '');
      if (!Array.isArray(slot.aliases) || !slot.aliases.length) slot.aliases = Array.isArray(src.aliases) ? [...src.aliases] : [];
      slot.enabled = true;
      slot.lastAutoMatch = matched;
      slot.lastAutoConfidence = Number(evidence.confidence || 0);
      slot.lastAutoReason = String(evidence.reason || '실제 RP 본문 감지');
      slot.lastAutoDetectedAt = Date.now();
      detected.push({ slot, matched, confidence:slot.lastAutoConfidence, reason:slot.lastAutoReason });

      if (room.pending) {
        const items = Array.isArray(room.pending.items) ? room.pending.items : (room.pending.items = []);
        const idx = items.findIndex(i => i.slotId === slot.id);
        const next = slotToPendingItem(slot);
        next.autoType = 'character';
        next.matchedAlias = matched;
        next.autoConfidence = slot.lastAutoConfidence;
        next.autoDetectionReason = slot.lastAutoReason;
        next.recallReason = `신뢰도 ${slot.lastAutoConfidence}% · 감지: ${slot.lastAutoReason}`;
        if (idx < 0) items.push(next);
        else if (room.autoCharacterResetOnReappear || matched === '사용자 고정') { items[idx] = next; reset++; }
      }
    }

    // 설정집에 없는 현재 방 캐릭터라도 사용자가 📌 고정했다면 조용히 항상 유지합니다.
    // 고정 자체는 자동 '감지'로 취급하지 않아 반복 토스트/모달 재렌더링을 발생시키지 않습니다.
    for (const slot of (room.slots || []).filter(s => s.group === 'character' && s.autoPinned)) {
      if (detected.some(x => x.slot.id === slot.id)) continue;
      slot.enabled = true;
      slot.lastAutoMatch = '사용자 고정';
      if (room.pending) {
        const items = Array.isArray(room.pending.items) ? room.pending.items : (room.pending.items = []);
        const idx = items.findIndex(i => i.slotId === slot.id);
        const next = slotToPendingItem(slot);
        next.autoType = 'character';
        next.matchedAlias = '사용자 고정';
        next.recallReason = '사용자 고정';
        if (idx < 0) items.push(next); else items[idx] = next;
      }
    }
    normalizeRoomSlots(room);
    return { detected, added, reset };
  }

  function autoDetectImportantItems(room, freshMessages) {
    if (!room.autoItemDetection) return { detected: [], reset: 0 };
    // 숨김 주입문·상태창·외부 로어 참고 블록은 제외하고 실제 RP 문장만 검사합니다.
    const text = (freshMessages || []).map(m => stripAutomationNoise(messageTextOf(m), true)).filter(Boolean).join('\n\n');
    const detected = [];
    let reset = 0;
    for (const slot of (room.slots || []).filter(s => s.group === 'item')) {
      if (slot.autoExcluded || !String(slot.content || '').trim()) continue;
      const evidence = text ? importantItemRpDetectionEvidence(text, slot) : { accepted:false };
      if (!evidence.accepted) continue;
      slot.enabled = true;
      slot.lastAutoMatch = evidence.matched;
      slot.lastAutoConfidence = Number(evidence.confidence || 0);
      slot.lastAutoReason = String(evidence.reason || '실제 RP 본문 물품 언급 감지');
      slot.lastAutoDetectedAt = Date.now();
      detected.push({ slot, matched:evidence.matched, confidence:slot.lastAutoConfidence, reason:slot.lastAutoReason });

      if (room.pending) {
        const items = Array.isArray(room.pending.items) ? room.pending.items : (room.pending.items = []);
        const idx = items.findIndex(item => item.slotId === slot.id);
        const next = slotToPendingItem(slot);
        next.autoType = 'important-item';
        next.matchedAlias = evidence.matched;
        next.autoConfidence = slot.lastAutoConfidence;
        next.autoDetectionReason = slot.lastAutoReason;
        next.recallReason = `신뢰도 ${slot.lastAutoConfidence}% · 감지: ${slot.lastAutoReason}`;
        if (idx < 0) items.push(next);
        else if (room.autoItemResetOnReappear) { items[idx] = next; reset++; }
      }
    }

    for (const slot of (room.slots || []).filter(s => s.group === 'item' && s.autoPinned)) {
      if (detected.some(entry => entry.slot.id === slot.id)) continue;
      slot.enabled = true;
      slot.lastAutoMatch = '사용자 고정';
      if (room.pending) {
        const items = Array.isArray(room.pending.items) ? room.pending.items : (room.pending.items = []);
        const idx = items.findIndex(item => item.slotId === slot.id);
        const next = slotToPendingItem(slot);
        next.autoType = 'important-item';
        next.matchedAlias = '사용자 고정';
        next.recallReason = '사용자 고정';
        if (idx < 0) items.push(next); else items[idx] = next;
      }
    }
    return { detected, reset };
  }

  function refreshAutoRecentLogsToPending(room) {
    if (!room.pending || !room.autoLogRecallEnabled) return 0;
    const slot = (room.slots || []).find(s => s.id === 'logSummary');
    if (!slot?.enabled || !String(slot.content || '').trim()) return 0;
    const blocks = parseDatedLogBlocks(slot.content);
    if (!blocks.length) return 0;

    const excludedKeys = new Set((room.autoLogExcludedKeys || []).map(String));
    const pinnedKeys = new Set((room.autoLogPinnedKeys || []).map(String));
    const manualKeys = new Set((room.manualLogSelectedKeys || []).map(String));
    const occupied = new Set([...pinnedKeys, ...manualKeys]);
    const eligible = autoRecallVisibleLogBlocks(blocks, room).filter(b => !excludedKeys.has(b.key));
    const latest = recentContinuityLogBlocks(room, eligible, excludedKeys);
    const scored = eligibleRelatedLogScores(room, eligible, room.autoRecallContextText || '', new Set([...excludedKeys, ...occupied]));
    const recent = latest.filter(block => !occupied.has(String(block.key)));

    // 활성 시간선의 최신 eligible 날짜 두 개를 직전 흐름으로 유지합니다.
    // 매 응답 뒤 최신 목록을 다시 계산해 오래된 자동 최근로그는 빼고, 새 최신 로그는 유지턴이
    // 끝났더라도 0턴부터 다시 시작시킵니다. 같은 항목이 아직 활성 상태라면 진행도는 이어갑니다.
    const items = Array.isArray(room.pending.items) ? room.pending.items : [];
    const previousRecent = items.filter(item => item?.autoType === 'recent-log');
    const previousBySource = new Map(previousRecent.map(item => [
      String(item.sourceKey || item.slotId || '').replace(/^auto-log:/, ''),
      item,
    ]));
    room.pending.items = items.filter(item => item?.autoType !== 'recent-log');

    for (const block of recent) {
      const rank = scored.findIndex(entry => entry.block.key === block.key);
      const next = makeRecentContinuityLogItem(block, slot, rank < 0 ? null : scored[rank], rank < 0 ? null : rank + 1, scored.length);
      const previous = previousBySource.get(String(block.key));
      const previousTotal = Number(previous?.totalTurns || 0);
      const previousUsed = Number(previous?.usedTurns || 0);
      const previousActive = !!previous && (previousTotal === 0 || previousUsed < previousTotal);
      if (previousActive) next.usedTurns = previousUsed;
      room.pending.items.push(next);
    }
    return recent.length;
  }

  const AI_CONTEXT_RESPONSE_SCHEMA = Object.freeze({
    type:'OBJECT',
    properties:{
      situation:{ type:'STRING' },
      keys:{ type:'ARRAY', items:{ type:'STRING' } },
    },
    required:['situation','keys'],
  });

  function safeAiContextRawExcerpt(value) {
    return normalizeLineBreaks(String(value || '')).trim().slice(0, 1200)
      .replace(/AIza[0-9A-Za-z_-]{20,}/g, '[인증정보 숨김]')
      .replace(/((?:api[_-]?key|private[_-]?key|client[_-]?email|project[_-]?id)\s*["']?\s*[:=]\s*)[^,\n}]+/gi, '$1[인증정보 숨김]');
  }

  function parseAiContextResponse(value) {
    const raw = normalizeLineBreaks(String(value || '')).trim();
    if (!raw) throw new Error('응답 형식 오류: 빈 응답입니다.');
    let jsonText = raw;
    const fenced = raw.match(/^```(?:json)?[ \t]*\n([\s\S]*?)\n```[ \t]*$/i);
    if (fenced) jsonText = fenced[1].trim();
    else if (/^```/.test(raw)) throw new Error('응답 형식 오류: JSON 코드블록 형식을 확인할 수 없습니다.');
    let parsed;
    try { parsed = JSON.parse(jsonText); }
    catch (_) { throw new Error('응답 형식 오류: 전체 응답이 하나의 JSON 객체가 아닙니다.'); }
    if (!parsed || Array.isArray(parsed) || typeof parsed !== 'object' || typeof parsed.situation !== 'string' || !Array.isArray(parsed.keys)) {
      throw new Error('응답 형식 오류: {"situation":"...","keys":[...]} schema가 필요합니다.');
    }
    if (Object.keys(parsed).some(key => !['situation','keys'].includes(key)) || parsed.keys.some(key => typeof key !== 'string')) {
      throw new Error('응답 형식 오류: situation 문자열과 keys 문자열 배열 외의 값이 포함되었습니다.');
    }
    const situation = normalizeLineBreaks(parsed.situation).replace(/\s+/g, ' ').trim();
    if (!situation) throw new Error('응답 형식 오류: 현재 상황 설명이 비어 있습니다.');
    return {
      situation:situation.slice(0, 500),
      keys:parsed.keys.map(key => key.trim()).filter(Boolean),
    };
  }

  function assertAiContextResponseComplete(result) {
    const finishReason = String(result?.finishReason || '').trim();
    if (/(?:MAX_TOKENS|LENGTH|TOKEN_LIMIT|INCOMPLETE)/i.test(finishReason)) {
      throw new Error(`응답 출력 한도 초과: JSON이 중간에 끊겼습니다. finishReason=${finishReason}`);
    }
  }

  async function aiRerankRelatedLogCandidates(room, contextText, candidates, count) {
    if (!room?.aiContextLogRerankEnabled || !candidates.length) return candidates;
    const settings = aiFeatureSettings(loadAiSummarySettings(), 'context');
    const provider = settings.provider;
    const secret = readAiSecret(provider);
    const candidateText = candidates.slice(0, 12).map((entry, index) => {
      const block = entry.block;
      return `[후보 ${index + 1}]\nKEY=${block.key}\n시간선=${logTimelineLabelOfBlock(block)}\n제목=${block.heading}\n내용=${String(block.body || '').slice(0, 2200)}`;
    }).join('\n\n');
    const prompt = `먼저 [현재 RP]만 읽고, 지금 진행 중인 상황을 확인된 사실만으로 한국어 1~2문장(최대 220자)으로 정리한다. 누가 누구에게 무엇을 하고 있으며 어떤 사건·대화·쟁점이 진행 중인지 구체적으로 쓴다. 감정·의도·행동을 추측하거나 아직 발생하지 않은 일을 확정하지 않는다. [키워드 검색 후보]의 과거 내용을 현재 상황에 섞지 않는다.\n\n그다음 현재 RP 맥락과 실제로 이어지는 날짜로그를 고른다. 인물 이름만 겹치는 로그보다 사건·장소·물건·관계 변화·미해결 단서가 이어지는 로그를 우선한다. 후보에 없는 KEY는 만들지 않는다. 최대 ${count}개를 관련도순으로 고른다. 적합한 로그가 없으면 keys는 빈 배열로 반환한다.\n\n[현재 RP]\n${String(contextText || '').slice(-12000)}\n\n[키워드 검색 후보]\n${candidateText}\n\nJSON 한 줄만 출력:\n{"situation":"현재 RP에서 확인된 상황","keys":["후보의 KEY"]}`;
    const systemInstruction = '현재 RP 상황을 사실대로 정리하고 날짜로그 후보를 맥락 기준으로 재정렬하는 선택기다. 설명 없이 지정된 JSON만 출력한다.';
    const callOptions = { feature:'context', room, responseJsonSchema:AI_CONTEXT_RESPONSE_SCHEMA, allowEmptyText:true, thinkingLevel:'low' };
    let result = await callAiSummaryProvider(provider, settings, secret, systemInstruction, prompt, 2048, () => {}, callOptions);
    let parsedResponse;
    let formatRetried = false;
    try {
      assertAiContextResponseComplete(result);
      parsedResponse = parseAiContextResponse(result.text);
    } catch (firstError) {
      formatRetried = true;
      const firstRaw = safeAiContextRawExcerpt(result.text);
      const retryPrompt = `${prompt}\n\n[응답 형식 재요청]\nJSON 외 텍스트 출력 금지. 설명 금지. 코드블록 금지. {"situation":"현재 RP에서 확인된 상황","keys":["후보의 KEY"]} schema만 반환한다.`;
      let retryResult = null;
      try {
        retryResult = await callAiSummaryProvider(provider, settings, secret, systemInstruction, retryPrompt, 4096, () => {}, callOptions);
        assertAiContextResponseComplete(retryResult);
        parsedResponse = parseAiContextResponse(retryResult.text);
        result = retryResult;
      } catch (retryError) {
        const failure = new Error(`응답 형식 오류: 1차 파싱 실패 후 자동 재요청도 실패했습니다. ${String(retryError?.message || retryError || '')}`.trim());
        failure.aiRaw = [firstRaw, safeAiContextRawExcerpt(retryResult?.text || '')].filter(Boolean).join('\n\n[자동 재요청 응답]\n');
        failure.parseFailure = `${String(firstError?.message || firstError)} / ${String(retryError?.message || retryError)}`;
        failure.finishReason = String(retryResult?.finishReason || result?.finishReason || '');
        throw failure;
      }
    }
    const byKey = new Map(candidates.slice(0, 12).map(entry => [String(entry.block.key), entry]));
    const selected = [];
    for (const key of parsedResponse.keys) {
      const entry = byKey.get(key);
      if (entry && !selected.includes(entry)) selected.push(entry);
      if (selected.length >= count) break;
    }
    const totalLogs = parseDatedLogBlocks((room.slots || []).find(slot => slot.id === 'logSummary')?.content || '').length;
    room.aiContextReviewReport = {
      state:'success', checkedAt:nowIso(), totalLogs, candidateCount:candidates.length, inspectedCount:Math.min(12, candidates.length), selectedCount:selected.length,
      provider, model:String(result.model || settings.models?.[provider] || ''), fallback:false, formatRetried,
      managerVersion:APP.version, finishReason:String(result.finishReason || ''),
      situation:parsedResponse.situation,
      keywords:[...new Set(selected.flatMap(item => [...(item.matchedPhrases || []), ...(item.matchedCoreTokens || []), ...(item.matchedRareTokens || [])]))].slice(0, 12),
      characters:[...new Set(selected.flatMap(item => item.matchedCharacterTerms || []))].slice(0, 8),
      items:selected.map((item, index) => ({ key:String(item.block.key), title:String(item.block.titleText || item.block.heading || ''), rank:index + 1, candidateRank:candidates.indexOf(item) + 1, score:Number(item.score || 0), reason:relatedLogReason(item) })),
    };
    setAiFeatureStatus('context', 'ok', provider, room.aiContextReviewReport.model, '최근 검토 정상');
    return selected;
  }

  function recordAiContextFallback(room, error, candidates, selected) {
    const failure = classifyAiFailure(error);
    const settings = aiFeatureSettings(loadAiSummarySettings(), 'context');
    const provider = settings.provider;
    const totalLogs = parseDatedLogBlocks((room.slots || []).find(slot => slot.id === 'logSummary')?.content || '').length;
    room.aiContextReviewReport = {
      state:'fallback', checkedAt:nowIso(), totalLogs, candidateCount:(candidates || []).length, inspectedCount:Math.min(12, (candidates || []).length), selectedCount:(selected || []).length,
      provider, model:String(settings.models?.[provider] || ''), fallback:true, failureCategory:failure.category, failureDetail:failure.detail,
      managerVersion:APP.version, finishReason:String(error?.finishReason || ''),
      situation:'',
      failureRaw:safeAiContextRawExcerpt(error?.aiRaw || ''), parseFailure:String(error?.parseFailure || ''),
      items:(selected || []).map((item, index) => ({ key:String(item.block.key), title:String(item.block.titleText || item.block.heading || ''), rank:index + 1, candidateRank:(candidates || []).indexOf(item) + 1, score:Number(item.score || 0), reason:relatedLogReason(item) })),
    };
    setAiFeatureStatus('context', 'error', provider, room.aiContextReviewReport.model, failure.category, failure.detail);
    return failure;
  }

  async function refreshAiContextReviewNow(room) {
    if (!room?.aiContextLogRerankEnabled) throw new Error('AI 맥락 검토가 꺼져 있습니다. API 설정에서 먼저 켜 주세요.');
    if (!room.autoLogRecallEnabled) throw new Error('최근·관련 로그 자동 선택이 꺼져 있습니다. 먼저 켜 주세요.');
    const slot = (room.slots || []).find(item => item.id === 'logSummary');
    if (!slot?.enabled || !String(slot.content || '').trim()) throw new Error('검토할 날짜로그가 없습니다.');

    const recent = await fetchRecentMessages(apiChatIdOf(room), Math.max(12, APP.autoScanMessageLimit));
    const contextText = recent
      .filter(message => ['user','assistant'].includes(messageRoleOf(message)))
      .map(message => stripAutomationNoise(messageTextOf(message)))
      .filter(Boolean)
      .join('\n')
      .slice(-12000);
    if (!contextText) throw new Error('현재 RP 맥락을 불러오지 못했습니다.');
    room.autoRecallContextText = contextText;
    room.aiContextReviewReport = null;

    if (room.pending) {
      await addAutoRelatedLogsToPending(room, contextText);
      await syncPendingCarrier(room, 'manual-ai-context-refresh');
    } else {
      const previewBudget = contextBudgetForPreview(room);
      const baseItems = snapshotSelectedItems(room, contextText, previewBudget);
      await rerankInitialRelatedLogItems(room, baseItems, contextText, previewBudget);
      if (!room.aiContextReviewReport) {
        const settings = aiFeatureSettings(loadAiSummarySettings(), 'context');
        room.aiContextReviewReport = {
          state:'success', checkedAt:nowIso(), totalLogs:parseDatedLogBlocks(slot.content).length,
          candidateCount:0, inspectedCount:0, selectedCount:0, provider:settings.provider,
          model:String(settings.models?.[settings.provider] || ''), fallback:false, formatRetried:false,
          managerVersion:APP.version, finishReason:'', situation:'', keywords:[], characters:[], items:[],
        };
        setAiFeatureStatus('context', 'ok', settings.provider, room.aiContextReviewReport.model, '검토할 후보 없음');
      }
      await saveRoom(room);
    }
    return room.aiContextReviewReport;
  }

  async function rerankInitialRelatedLogItems(room, items, contextText, contextBudget) {
    if (!room?.aiContextLogRerankEnabled || !room.autoLogRecallEnabled) return items;
    const slot = (room.slots || []).find(s => s.id === 'logSummary');
    if (!slot?.enabled || !String(slot.content || '').trim()) return items;
    const blocks = parseDatedLogBlocks(slot.content);
    if (!blocks.length) return items;

    const excludedKeys = new Set((room.autoLogExcludedKeys || []).map(String));
    const pinnedKeys = new Set((room.autoLogPinnedKeys || []).map(String));
    const manualKeys = new Set((room.manualLogSelectedKeys || []).map(String));
    const eligible = autoRecallVisibleLogBlocks(blocks, room).filter(block => !excludedKeys.has(block.key));
    const occupied = new Set([...pinnedKeys, ...manualKeys]);
    const existingNonRelatedKeys = new Set((items || []).filter(item => item.autoType !== 'related-log').map(item => String(item.sourceKey || '')));
    const skip = new Set([...excludedKeys, ...occupied, ...existingNonRelatedKeys]);
    const relatedCandidates = eligibleRelatedLogScores(room, eligible, contextText, skip);
    if (!relatedCandidates.length) return items;

    let selected;
    try {
      const reranked = await aiRerankRelatedLogCandidates(room, contextText, relatedCandidates, Math.min(12, relatedCandidates.length));
      selected = [...reranked, ...relatedCandidates.filter(entry => !reranked.includes(entry))];
    } catch (error) {
      const fallback = relatedCandidates;
      const failure = recordAiContextFallback(room, error, relatedCandidates, fallback);
      console.warn('[RP Manager] 최초 주입 AI 맥락 검토 실패, 키워드 결과를 사용합니다.', error);
      notify(`AI 맥락 검토 실패 · ${failure.category}\n기본 키워드 방식으로 대체됨`, 'warn', 6500);
      return items;
    }

    const nonLogs = (items || []).filter(item => item.sourceSlotId !== 'logSummary' && item.group !== 'log-auto' && item.slotId !== 'logSummary');
    const fixedLogs = (items || []).filter(item => (item.sourceSlotId === 'logSummary' || item.group === 'log-auto' || item.slotId === 'logSummary') && item.autoType !== 'related-log');
    const aiRelated = selected.slice(0, 5).map((scored, index) => makeLogRecallItem(
      scored.block,
      slot,
      'related-log',
      '관련로그',
      `${logTimelineLabelOfBlock(scored.block)} · AI 맥락 검토`,
      {
        score:scored.score,
        coreScore:scored.coreScore,
        characterScore:scored.characterScore,
        rank:index + 1,
        candidateCount:relatedCandidates.length,
        matchedTerms:[...(scored.matchedPhrases || []), ...(scored.matchedCoreTokens || []), ...(scored.matchedCharacterTerms || [])],
        matchedCoreTerms:[...(scored.matchedPhrases || []), ...(scored.matchedCoreTokens || []), ...(scored.matchedRareTokens || [])],
        matchedCharacterTerms:[...(scored.matchedCharacterTerms || [])],
      },
    ));
    return [...nonLogs, ...fitLogItemsToBudget(room, nonLogs, [...fixedLogs, ...aiRelated], contextBudget)];
  }

  async function addAutoRelatedLogsToPending(room, contextText) {
    if (!room.pending || !room.autoLogRecallEnabled) return 0;
    const slot = (room.slots || []).find(s => s.id === 'logSummary');
    if (!slot?.enabled || !String(slot.content || '').trim()) return 0;
    const blocks = parseDatedLogBlocks(slot.content);
    if (!blocks.length) return 0;
    const excludedKeys = new Set((room.autoLogExcludedKeys || []).map(String));
    const pinnedKeys = new Set((room.autoLogPinnedKeys || []).map(String));
    const manualKeys = new Set((room.manualLogSelectedKeys || []).map(String));
    const eligible = autoRecallVisibleLogBlocks(blocks, room).filter(b => !excludedKeys.has(b.key));
    const occupied = new Set([...pinnedKeys, ...manualKeys]);
    const latestKeys = new Set(recentContinuityLogBlocks(room, eligible, excludedKeys).map(block => String(block.key)));
    const allEligible = eligibleRelatedLogScores(room, eligible, contextText, new Set([...excludedKeys, ...occupied]));
    const relatedCandidates = allEligible.filter(entry => !latestKeys.has(String(entry.block.key)));
    let related = relatedCandidates;
    if (room.aiContextLogRerankEnabled && relatedCandidates.length) {
      try {
        const reranked = await aiRerankRelatedLogCandidates(room, contextText, relatedCandidates, Math.min(12, relatedCandidates.length));
        related = [...reranked, ...relatedCandidates.filter(entry => !reranked.includes(entry))];
      } catch (error) {
        const fallback = relatedCandidates;
        const failure = recordAiContextFallback(room, error, relatedCandidates, fallback);
        related = fallback;
        console.warn('[RP Manager] AI 맥락 검토 실패, 키워드 결과를 사용합니다.', error);
        notify(`AI 맥락 검토 실패 · ${failure.category}\n기본 키워드 방식으로 대체됨`, 'warn', 6500);
      }
    }

    // 이전 턴의 관련로그를 계속 쌓지 않고 이번 검색 결과로 교체합니다.
    // 같은 로그가 다시 선정되면 남은 유지턴은 이어가되, 순위에서 빠진 로그는 즉시 제외합니다.
    const items = Array.isArray(room.pending.items) ? room.pending.items : [];
    const previousRelated = items.filter(item => item?.autoType === 'related-log');
    const previousBySource = new Map(previousRelated.map(item => [
      String(item.sourceKey || item.slotId || '').replace(/^auto-log:/, ''),
      item,
    ]));
    room.pending.items = items.filter(item => item?.autoType !== 'related-log');
    const nextItems = room.pending.items;
    let added = 0;
    for (let relatedIndex = 0; relatedIndex < Math.min(5, related.length); relatedIndex++) {
      const scored = related[relatedIndex];
      const b = scored.block;
      // 최초 주입 경로와 자동 갱신 경로가 같은 메타데이터 구조를 사용하게 해서
      // 총점만 있고 핵심/인물 점수·매칭어·후보순위가 사라지는 현상을 막습니다.
      const selectionMethod = room.aiContextLogRerankEnabled
        ? (room.aiContextReviewReport?.state === 'success' ? 'AI 맥락 검토로 선정' : 'AI 검토 실패 후 키워드 선정')
        : 'AI 맥락 검토 OFF · 기본 검색';
      const next = makeLogRecallItem(b, slot, 'related-log', '관련로그', `${logTimelineLabelOfBlock(b)} · ${selectionMethod} · ${relatedLogReason(scored)}`, {
        score: scored.score,
        coreScore: scored.coreScore,
        characterScore: scored.characterScore,
        rank: relatedIndex + 1,
        candidateCount: relatedCandidates.length,
        matchedTerms:[...(scored.matchedPhrases || []), ...(scored.matchedCoreTokens || []), ...(scored.matchedCharacterTerms || [])],
        matchedCoreTerms:[...(scored.matchedPhrases || []), ...(scored.matchedCoreTokens || []), ...(scored.matchedRareTokens || [])],
        matchedCharacterTerms:[...(scored.matchedCharacterTerms || [])],
      });
      const previous = previousBySource.get(String(b.key));
      const previousTotal = Number(previous?.totalTurns || 0);
      const previousUsed = Number(previous?.usedTurns || 0);
      const previousActive = !!previous && (previousTotal === 0 || previousUsed < previousTotal);
      if (previousActive) next.usedTurns = previousUsed;

      const activeNow = activePendingItems(room.pending);
      const canFit = buildContextBlockFromItems([...activeNow, next]).length <= contextBudgetForCarrier(room, String(room.pending.originalText || '').length);
      if (!canFit) continue;
      nextItems.push(next);
      if (!previousActive) added++;
    }
    return added;
  }

  async function removePendingRecallItem(room, identity, sourceKey = '', autoType = '') {
    const pending = room?.pending;
    const current = pending ? activePendingItems(pending).find(item => pendingItemIdentity(item) === identity) : null;
    const resolvedType = String(current?.autoType || autoType || '');
    const resolvedKey = String(current?.sourceKey || sourceKey || '').replace(/^auto-log:/, '');

    // 직접 선택은 임시 carrier 속성이 아니라 다음 주입에도 유지되는 사용자 설정입니다.
    // 따라서 `빼기`를 누르면 pending 유무와 관계없이 선택 원본에서도 제거합니다.
    if (resolvedType === 'manual-log' && resolvedKey) {
      room.manualLogSelectedKeys = (room.manualLogSelectedKeys || []).map(String).filter(key => key !== resolvedKey);
    }

    if (!pending) {
      if (!resolvedKey) throw new Error('빼 로그를 찾지 못했습니다.');
      if (resolvedType === 'related-log' || resolvedType === 'recent-log' || resolvedType === 'pinned-log') {
        const excluded = new Set((room.autoLogExcludedKeys || []).map(String));
        excluded.add(resolvedKey);
        room.autoLogExcludedKeys = [...excluded];
        if (resolvedType === 'pinned-log') room.autoLogPinnedKeys = (room.autoLogPinnedKeys || []).map(String).filter(key => key !== resolvedKey);
      }
      await saveRoom(room);
      return;
    }

    if (!current) throw new Error('이미 빠졌거나 찾을 수 없는 항목입니다.');
    const removed = quickRemovedPendingItems(pending);
    if (!removed.some(item => pendingItemIdentity(item) === identity)) removed.push({ ...current });
    pending.quickRemovedItems = removed;
    pending.items = (pending.items || []).filter(item => pendingItemIdentity(item) !== identity);
    await syncPendingCarrier(room, 'main-log-remove');
    await saveRoom(room);
  }

  async function applyManualRelatedLog(room, sourceKey, replaceIdentity = '') {
    const slot = (room?.slots || []).find(item => item.id === 'logSummary');
    const blocks = parseDatedLogBlocks(slot?.content || '');
    const block = blocks.find(item => String(item.key) === String(sourceKey));
    if (!slot || !block) throw new Error('선택한 날짜로그를 찾지 못했습니다.');

    const manual = new Set((room.manualLogSelectedKeys || []).map(String));
    const excluded = new Set((room.autoLogExcludedKeys || []).map(String));
    const pending = room.pending;
    const visibleItems = pending ? activePendingItems(pending) : snapshotSelectedItems(room);
    const previous = replaceIdentity
      ? visibleItems.find(item => pendingItemIdentity(item) === replaceIdentity)
      : null;
    const previousKey = String(previous?.sourceKey || '').replace(/^auto-log:/, '');
    if (previous?.autoType === 'manual-log' && previousKey) manual.delete(previousKey);
    if (['related-log','recent-log','pinned-log'].includes(String(previous?.autoType || '')) && previousKey) {
      excluded.add(previousKey);
      if (previous?.autoType === 'pinned-log') {
        room.autoLogPinnedKeys = (room.autoLogPinnedKeys || []).map(String).filter(key => key !== previousKey);
      }
    }
    manual.add(String(block.key));
    excluded.delete(String(block.key));

    if (pending) {
      const next = makeLogRecallItem(block, slot, 'manual-log', '직접주입', '사용자 직접 주입');
      const remaining = activePendingItems(pending).filter(item => {
        const id = pendingItemIdentity(item);
        return id !== replaceIdentity && id !== pendingItemIdentity(next);
      });
      const budget = contextBudgetForCarrier(room, String(pending.originalText || '').length);
      if (buildContextBlockFromItems([...remaining, next]).length > budget) {
        throw new Error('주입 한도를 넘어 이 로그를 추가할 수 없습니다. 다른 항목을 먼저 빼 주세요.');
      }
      if (previous && replaceIdentity) {
        const removed = quickRemovedPendingItems(pending);
        if (!removed.some(item => pendingItemIdentity(item) === replaceIdentity)) removed.push({ ...previous });
        pending.quickRemovedItems = removed;
      }
      pending.quickRemovedItems = quickRemovedPendingItems(pending).filter(item => {
        const key = String(item?.sourceKey || '').replace(/^auto-log:/, '');
        return key !== String(block.key);
      });
      pending.items = [...remaining, next];
      await syncPendingCarrier(room, replaceIdentity ? 'main-related-log-manual-replace' : 'main-related-log-manual-add');
    }

    room.manualLogSelectedKeys = [...manual];
    room.autoLogExcludedKeys = [...excluded];
    await saveRoom(room);
  }

  function openRelatedLogPickerDialog(room, { replaceIdentity = '' } = {}) {
    return new Promise(resolve => {
      document.querySelector('#rpcm-related-picker-backdrop')?.remove();
      const slot = (room?.slots || []).find(item => item.id === 'logSummary');
      const blocks = parseDatedLogBlocks(slot?.content || '');
      if (!blocks.length) { notify('선택할 날짜로그가 없습니다.', 'warn'); resolve(null); return; }

      const activeItems = room.pending ? activePendingItems(room.pending) : snapshotSelectedItems(room);
      const activeKeys = new Set(activeItems.filter(item => item.sourceSlotId === 'logSummary' || item.group === 'log-auto').map(item => String(item.sourceKey || '').replace(/^auto-log:/, '')));
      const replacing = activeItems.find(item => pendingItemIdentity(item) === replaceIdentity);
      const replacingKey = String(replacing?.sourceKey || '').replace(/^auto-log:/, '');
      const favorites = new Set((room.favoriteLogKeys || []).map(String));
      const recentKeys = new Set(blocks.slice(-10).map(block => String(block.key)));
      const scored = scoreRelatedLogBlocks(blocks, room.autoRecallContextText || '', new Set(), room);
      const scoreByKey = new Map(scored.map((item, index) => [String(item.block.key), { ...item, rank:index + 1 }]));
      const timelines = [...new Set(blocks.map(logTimelineLabelOfBlock).filter(Boolean))];
      const expanded = new Set();
      const filters = { search:'', date:'', keyword:'', timeline:'', favorites:false, recent:false };
      const backdrop = document.createElement('div');
      backdrop.id = 'rpcm-related-picker-backdrop';
      backdrop.innerHTML = `<div class="rpcm-related-picker" role="dialog" aria-modal="true" aria-label="관련로그 선택"><header><div><h2>${replaceIdentity ? '관련로그 교체' : '관련로그 추가'}</h2><p>본문을 펼쳐 확인한 뒤 ‘선택’을 누르세요. AI 후보가 아닌 전체 날짜로그도 고를 수 있습니다.</p></div><button type="button" data-related-act="close" aria-label="닫기" data-rpcm-close="icon">✕</button></header><div class="rpcm-related-picker-filters"><label class="wide"><span>통합 검색</span><input type="search" data-related-filter="search" placeholder="제목·날짜·키워드·본문"></label><label><span>날짜</span><input type="search" data-related-filter="date" placeholder="2027.10.25"></label><label><span>키워드</span><input type="search" data-related-filter="keyword" placeholder="인물·사건"></label><label><span>시간선</span><select data-related-filter="timeline"><option value="">전체 시간선</option>${timelines.map(label => `<option value="${esc(label)}">${esc(label)}</option>`).join('')}</select></label><label class="check"><input type="checkbox" data-related-filter="favorites"> ★ 즐겨찾기만</label><label class="check"><input type="checkbox" data-related-filter="recent"> 최근 10개만</label></div><div class="rpcm-related-picker-count"></div><div class="rpcm-related-picker-list"></div><footer><span>펼쳐보기는 선택으로 처리되지 않습니다.</span><button type="button" class="rpcm-btn secondary" data-related-act="close">취소</button></footer></div>`;
      document.body.appendChild(backdrop);
      const list = backdrop.querySelector('.rpcm-related-picker-list');
      const count = backdrop.querySelector('.rpcm-related-picker-count');

      const filteredBlocks = () => blocks.filter(block => {
        const key = String(block.key);
        const heading = String(block.heading || block.titleText || '');
        const content = String(block.raw || '');
        const timeline = logTimelineLabelOfBlock(block);
        const search = filters.search.toLowerCase();
        const date = filters.date.toLowerCase();
        const keyword = filters.keyword.toLowerCase();
        if (search && !`${heading}\n${content}\n${timeline}`.toLowerCase().includes(search)) return false;
        if (date && !`${block.fullDate || ''}\n${heading}`.toLowerCase().includes(date)) return false;
        if (keyword && !`${heading}\n${block.events || ''}\n${content}`.toLowerCase().includes(keyword)) return false;
        if (filters.timeline && normalizedLogTimelineKey(timeline) !== normalizedLogTimelineKey(filters.timeline)) return false;
        if (filters.favorites && !favorites.has(key)) return false;
        if (filters.recent && !recentKeys.has(key)) return false;
        return true;
      }).sort((a, b) => {
        const ar = scoreByKey.get(String(a.key))?.rank || 999999;
        const br = scoreByKey.get(String(b.key))?.rank || 999999;
        return ar - br || Number(b.index || 0) - Number(a.index || 0);
      });

      const renderList = () => {
        const visible = filteredBlocks();
        count.textContent = `${visible.length}/${blocks.length}개 로그${scoreByKey.size ? ' · AI 후보 우선 표시' : ''}`;
        list.innerHTML = visible.length ? visible.map(block => {
          const key = String(block.key);
          const ai = scoreByKey.get(key);
          const already = activeKeys.has(key) && key !== replacingKey;
          const isOpen = expanded.has(key);
          return `<article class="rpcm-related-picker-card${favorites.has(key) ? ' is-favorite' : ''}${already ? ' is-active' : ''}" data-related-key="${esc(key)}"><div class="rpcm-related-picker-row"><button type="button" class="rpcm-related-star" data-related-act="favorite" aria-label="${favorites.has(key) ? '즐겨찾기 해제' : '즐겨찾기 추가'}">${favorites.has(key) ? '★' : '☆'}</button><div><strong>${esc(block.titleText || block.heading || '날짜로그')}</strong><span>${esc(logTimelineLabelOfBlock(block))}${ai ? ` · AI 후보 ${ai.rank}위 · 관련도 ${Number(ai.score || 0).toFixed(1)}` : ''}${already ? ' · 이미 주입 중' : ''}</span></div><button type="button" data-related-act="toggle">${isOpen ? '내용 접기 ▲' : '내용 보기 ▼'}</button><button type="button" class="primary" data-related-act="select" ${already ? 'disabled' : ''}>선택</button></div><pre ${isOpen ? '' : 'hidden'}>${esc(String(block.raw || '').trim())}</pre></article>`;
        }).join('') : '<div class="rpcm-story-empty compact">조건에 맞는 날짜로그가 없습니다.</div>';
      };

      const finish = value => { backdrop.remove(); resolve(value); };
      backdrop.querySelectorAll('[data-related-filter]').forEach(control => {
        const update = () => {
          const name = String(control.dataset.relatedFilter || '');
          filters[name] = control.type === 'checkbox' ? control.checked : String(control.value || '').trim();
          renderList();
        };
        control.addEventListener(control.tagName === 'SELECT' || control.type === 'checkbox' ? 'change' : 'input', update);
      });
      list.addEventListener('click', async event => {
        const button = event.target.closest('button[data-related-act]');
        const card = button?.closest('[data-related-key]');
        if (!button || !card) return;
        const key = String(card.dataset.relatedKey || '');
        const action = button.dataset.relatedAct;
        if (action === 'toggle') { if (expanded.has(key)) expanded.delete(key); else expanded.add(key); renderList(); return; }
        if (action === 'favorite') {
          if (favorites.has(key)) favorites.delete(key); else favorites.add(key);
          room.favoriteLogKeys = [...favorites];
          await saveRoom(room);
          renderList();
          return;
        }
        if (action === 'select') finish(key);
      });
      backdrop.querySelectorAll('[data-related-act="close"]').forEach(button => button.onclick = () => finish(null));
      backdrop.onclick = event => { if (event.target === backdrop) finish(null); };
      backdrop.onkeydown = event => { if (event.key === 'Escape') finish(null); };
      renderList();
    });
  }

  async function replacePendingRelatedLog(room, identity) {
    const pending = room?.pending;
    if (!pending) throw new Error('현재 주입 중인 항목이 없습니다.');
    const current = activePendingItems(pending).find(item => pendingItemIdentity(item) === identity && item.autoType === 'related-log');
    if (!current) throw new Error('교체할 관련로그를 찾지 못했습니다.');
    const slot = (room.slots || []).find(item => item.id === 'logSummary');
    const blocks = parseDatedLogBlocks(slot?.content || '');
    const activeKeys = new Set(activePendingItems(pending).filter(item => item.sourceSlotId === 'logSummary' || item.group === 'log-auto').map(item => String(item.sourceKey || '').replace(/^auto-log:/, '')));
    const removedKeys = new Set(quickRemovedPendingItems(pending).map(item => String(item.sourceKey || '').replace(/^auto-log:/, '')));
    const excluded = new Set([...(room.autoLogExcludedKeys || []).map(String), ...activeKeys, ...removedKeys]);
    let candidates = eligibleRelatedLogScores(room, autoRecallVisibleLogBlocks(blocks, room), room.autoRecallContextText || '', excluded);
    if (room.aiContextLogRerankEnabled && candidates.length) {
      const keywordCandidates = candidates;
      try { candidates = await aiRerankRelatedLogCandidates(room, room.autoRecallContextText || '', candidates, 1); }
      catch (error) { recordAiContextFallback(room, error, keywordCandidates, keywordCandidates.slice(0, 1)); candidates = keywordCandidates; }
    }
    const scored = candidates[0];
    if (!scored) throw new Error('현재 맥락에 맞는 다른 관련로그 후보가 없습니다.');
    const rerollMethod = room.aiContextLogRerankEnabled
      ? (room.aiContextReviewReport?.state === 'success' ? 'AI 맥락 검토로 선정' : 'AI 검토 실패 후 키워드 선정')
      : 'AI 맥락 검토 OFF · 기본 검색';
    const next = makeLogRecallItem(scored.block, slot, 'related-log', '관련로그', `${logTimelineLabelOfBlock(scored.block)} · ${rerollMethod} · ${relatedLogReason(scored)}`, {
      score:scored.score, coreScore:scored.coreScore, characterScore:scored.characterScore, rank:1, candidateCount:candidates.length,
      matchedTerms:[...(scored.matchedPhrases || []), ...(scored.matchedCoreTokens || []), ...(scored.matchedCharacterTerms || [])],
      matchedCoreTerms:[...(scored.matchedPhrases || []), ...(scored.matchedCoreTokens || []), ...(scored.matchedRareTokens || [])],
      matchedCharacterTerms:[...(scored.matchedCharacterTerms || [])],
    });
    const removed = quickRemovedPendingItems(pending);
    if (!removed.some(item => pendingItemIdentity(item) === identity)) removed.push({ ...current });
    pending.quickRemovedItems = removed;
    const index = (pending.items || []).findIndex(item => pendingItemIdentity(item) === identity);
    if (index < 0) throw new Error('교체할 관련로그 위치를 찾지 못했습니다.');
    pending.items[index] = next;
    await syncPendingCarrier(room, 'main-related-log-reroll');
  }

  function autoDetectPersonProfiles(room, cleanFreshText) {
    const found = knowledgeInjectionItems(room, cleanFreshText);
    if (!room.pending) return found.map(item => item.personName);
    const items = Array.isArray(room.pending.items) ? room.pending.items : (room.pending.items = []);
    const removedKeys = new Set(quickRemovedPendingItems(room.pending).map(item => item.slotId));
    room.pending.items = items.filter(item => item.slotId !== 'knowledge:master');
    for (const item of found) {
      // 빠른 주입 관리에서 제외한 인물은 이 주입 세션 동안 재선택하지 않습니다.
      if (removedKeys.has(item.slotId)) continue;
      const index = room.pending.items.findIndex(existing => existing.slotId === item.slotId);
      if (index < 0) room.pending.items.push(item);
      else room.pending.items[index] = item; // 직접 재등장 시 묶음 전체의 유지 턴을 갱신합니다.
    }
    return found.map(item => item.personName);
  }

  function refreshPendingLoreItems(room, contextText = '') {
    if (!room?.pending) return 0;
    const pending = room.pending;
    const active = activePendingItems(pending);
    const core = active.filter(item => item.group !== 'lore' && item.group !== 'log-auto' && item.sourceSlotId !== 'logSummary');
    const selected = fitLoreItemsToBudget(room, core, loreInjectionCandidates(room, contextText || room.autoRecallContextText || ''), contextBudgetForPreview(room));
    const removed = new Set(quickRemovedPendingItems(pending).map(pendingItemIdentity));
    pending.items = (pending.items || []).filter(item => item.group !== 'lore');
    pending.items.push(...selected.filter(item => !removed.has(pendingItemIdentity(item))));
    return selected.length;
  }

  async function refreshAutomaticMemories(room, recentMessages, freshMessages = null) {
    const fresh = freshMessages || newMessagesSinceLastScan(room, recentMessages);
    if (!fresh.length) return { detected: [], added: 0, reset: 0, itemDetected: [], itemReset: 0, logAdded: 0, freshCount: 0 };
    const cleanFreshText = fresh.map(m => stripAutomationNoise(messageTextOf(m))).filter(Boolean).join('\n');
    if (cleanFreshText) room.autoRecallContextText = cleanFreshText.slice(-12000);
    const charResult = await autoDetectCharacters(room, fresh);
    const itemResult = autoDetectImportantItems(room, fresh);
    const personDetected = autoDetectPersonProfiles(room, cleanFreshText);
    refreshPendingLoreItems(room, cleanFreshText);
    refreshAutoRecentLogsToPending(room);
    const logAdded = await addAutoRelatedLogsToPending(room, cleanFreshText);
    await saveRoom(room);
    if (room.chatId === state.currentChatId) state.currentRoom = room;
    return { ...charResult, itemDetected:itemResult.detected, itemReset:itemResult.reset, personDetected, logAdded, freshCount: fresh.length };
  }

  async function armInjectionNow(room) {
    if (room.pending) throw new Error('이미 자동 유지 컨텍스트가 활성화되어 있습니다. 먼저 지금 해제해 주세요.');

    const recentForAuto = await fetchRecentMessages(apiChatIdOf(room), APP.autoScanMessageLimit);
    await refreshAutomaticMemories(room, recentForAuto, recentForAuto.filter(m => ['user','assistant'].includes(messageRoleOf(m))).slice(0, APP.autoScanMessageLimit));
    const firstAutoMessage = recentForAuto.find(m => ['user','assistant'].includes(messageRoleOf(m)));
    if (firstAutoMessage) room.autoScanLastMessageId = String(messageIdOf(firstAutoMessage) || room.autoScanLastMessageId || '');
    const recallText = recentForAuto.map(m => stripAutomationNoise(messageTextOf(m))).filter(Boolean).join('\n');
    room.autoRecallContextText = recallText.slice(-12000);
    const recent = await fetchRecentMessages(apiChatIdOf(room), 40);
    if (!recent.length) throw new Error('채팅 메시지를 찾지 못했습니다.');
    const newest = recent[0];
    if (messageRoleOf(newest) !== 'assistant') throw new Error('가장 최근 메시지가 AI 응답이 아닙니다. AI 생성이 끝난 뒤 주입을 시작해 주세요.');
    const latestAssistant = recent.find(m => messageRoleOf(m) === 'assistant');
    if (!latestAssistant) throw new Error('컨텍스트를 붙일 AI 메시지가 없습니다.');

    const targetId = messageIdOf(latestAssistant);
    if (!targetId) throw new Error('AI 메시지 ID를 찾지 못했습니다.');
    const rawOriginal = messageTextOf(latestAssistant);
    if (!rawOriginal) throw new Error('최근 AI 메시지 원문을 읽지 못했습니다.');
    const cleanOriginal = stripOurContextBlock(rawOriginal).text || rawOriginal;
    const initialContextBudget = contextBudgetForCarrier(room, cleanOriginal.length);
    let items = snapshotSelectedItems(room, recallText, initialContextBudget);
    // 최초 주입에는 아직 pending이 없으므로, 갱신 경로와 별도로 AI 맥락 검토를 적용합니다.
    // API가 실패하면 이미 계산된 로컬 키워드 결과를 그대로 사용합니다.
    items = await rerankInitialRelatedLogItems(room, items, recallText, initialContextBudget);
    items = fitItemsToCarrierLimits(room, cleanOriginal, items);
    const contextBlock = buildContextBlockFromItems(items);
    if (!contextBlock) throw new Error('주입할 항목이 없습니다. 현재상태/캐릭터/중요 물품/자료집/기타 또는 날짜 로그의 직접 주입·최근·관련 자동 선택 설정을 확인해 주세요.');
    const injectedText = buildInjectedMessage(cleanOriginal, contextBlock);
    const requestMetrics = assertCarrierRequestWithinLimits(room, injectedText);

    const pending = {
      messageId: targetId,
      originalText: cleanOriginal,
      baselineAssistantId: targetId,
      sessionStartedAt: Date.now(), armedAt: Date.now(), carrierArmedAt: Date.now(),
      injectedChars: contextBlock.length, originalChars: cleanOriginal.length, carrierChars: injectedText.length,
      carrierMessageBytes:requestMetrics.messageBytes, carrierPayloadBytes:requestMetrics.payloadBytes,
      carrierRole: 'assistant', mode: 'append-hidden-html-comment-reanchor-per-item',
      verified: false, verifiedAt: null, serverChars: 0,
      logRecallRevision: APP.logRecallRevision,
      contextBlock, items,
    };
    stampVerifiedPendingSnapshot(pending, items, contextBlock);

    savePendingBackup(room.chatId, pending);
    await patchMessage(apiChatIdOf(room), targetId, injectedText);
    const verification = await verifyInjectedCarrier(room, pending, injectedText);
    if (!verification.verified) {
      try {
        await restoreCarrierOnly(room, pending);
        clearPendingBackup(room.chatId);
      } catch (rollbackError) {
        // 롤백을 확인하지 못한 경우 복구 가능한 pending/백업을 반드시 남깁니다.
        room.pending = pending;
        savePendingBackup(room.chatId, pending);
        await saveRoom(room);
        throw new Error(`서버 주입 검증과 원문 롤백 확인에 실패했습니다. 복구 정보는 유지했습니다: ${rollbackError.message}`);
      }
      throw new Error('서버 재확인에서 숨김 컨텍스트를 확인하지 못해 AI 원문으로 안전 복원했습니다. 주입 해제 후 다시 주입해 주세요.');
    }
    pending.verified = true; pending.verifiedAt = Date.now(); pending.serverChars = verification.serverChars;
    stampVerifiedPendingSnapshot(pending, items, contextBlock);
    savePendingBackup(room.chatId, pending);
    room.pending = pending; await saveRoom(room);
    if (room.chatId === state.currentChatId) state.currentRoom = room;
    scheduleRecovery(APP.activePollMs);
    sanitizeRenderedContextSoon();
    notify(`서버 주입 확인됨 ✓ · ${items.length}개 항목 독립 유지 시작`, 'success', 6500);
    renderModalIfOpen();
  }

  function armInjection(room) {
    return queuePendingCarrierOperation(room, () => armInjectionNow(room));
  }

  async function restorePendingNow(room, reason = 'manual') {
    const p = room.pending;
    if (!p) return { restored: false, reason: 'none' };

    // 네트워크/PATCH 오류 때 finally에서 백업을 지우면 서버에는 숨김 블록이 남고
    // 복원 정보만 사라질 수 있습니다. 복원 또는 이미 정리됨이 확인된 뒤에만 해제합니다.
    const result = await restoreCarrierOnly(room, p);
    room.pending = null;
    clearPendingBackup(room.chatId);
    await saveRoom(room);

    if (room.chatId === state.currentChatId) {
      state.currentRoom = room;
      if (reason === 'manual') notifyInjectionEnded(room, 'manual');
      else if (reason === 'completed') notifyInjectionEnded(room, 'completed');
      else notify(`숨김 컨텍스트 원문 복원 완료 · ${reason === 'recovery' ? '복구 처리' : reason}`, 'success', 5000);
      renderModalIfOpen();
    }
    return result;
  }

  function restorePending(room, reason = 'manual') {
    return queuePendingCarrierOperation(room, () => restorePendingNow(room, reason));
  }

  async function reanchorAfterResponseNow(room, latestAssistant, options = {}) {
    const p = room.pending;
    if (!p) return;
    const countTurn = options.countTurn !== false;
    const rerollMove = options.reason === 'reroll';
    const newId = messageIdOf(latestAssistant);
    if (!newId || newId === p.messageId) return;
    await sleep(APP.reanchorDelayMs);

    // 이전 carrier 원문 복원
    await restoreCarrierOnly(room, p);

    // 일반 새 응답만 유지 횟수를 차감합니다. 리롤은 같은 USER 턴의 대체 답변이므로
    // 컨텍스트 위치만 옮기고 유지 횟수는 그대로 둡니다.
    const items = Array.isArray(p.items) ? p.items : [];
    if (countTurn) {
      for (const item of items) {
        const total = Number(item.totalTurns || 0);
        if (total !== 0 && Number(item.usedTurns || 0) < total) item.usedTurns = Number(item.usedTurns || 0) + 1;
      }
    }

    // v0.8.9에서 이어진 pending은 최근로그가 저장소 뒤쪽 순서로 고정되어 있을 수 있습니다.
    // 새 carrier로 옮기기 전에 한 번만 현재 로그 저장소 기준으로 다시 선정합니다.
    if (Number(p.logRecallRevision || 0) < APP.logRecallRevision) {
      replacePendingLogItems(room);
      refreshPendingLoreItems(room, room.autoRecallContextText || '');
    }

    // 방금 완료된 USER→AI 흐름에서 새 등장 캐릭터/관련 과거로그를 찾아 다음 응답용 컨텍스트에 추가합니다.
    const recentForAuto = await fetchRecentMessages(apiChatIdOf(room), APP.autoScanMessageLimit);
    const autoResult = countTurn
      ? await refreshAutomaticMemories(room, recentForAuto)
      : { detected: [], added: 0, reset: 0, itemDetected: [], itemReset: 0, logAdded: 0, freshCount: 0 };
    if (room.pending) room.pending.items = p.items;
    refreshAutoRecentLogsToPending(room);
    const persistenceRepair = ensureDirectReleasePendingItems(room, p);
    if (persistenceRepair.added) console.info('[RP매니저] 직접 해제 항목 유지 복구:', persistenceRepair.added);
    applyQuickItemSuppression(p);
    let active = activePendingItems(p);
    if (!active.length) {
      room.pending = null; clearPendingBackup(room.chatId); await saveRoom(room);
      if (room.chatId === state.currentChatId) {
        state.currentRoom = room;
        notifyInjectionEnded(room, 'completed');
        renderModalIfOpen();
      }
      return;
    }

    const fresh = await fetchMessage(apiChatIdOf(room), newId) || latestAssistant;
    if (messageRoleOf(fresh) !== 'assistant') throw new Error('새 carrier가 AI 메시지가 아니어서 자동 유지를 중단합니다.');
    const newRaw = messageTextOf(fresh);
    if (!newRaw) throw new Error('새 AI 응답 원문을 읽지 못해 자동 유지를 중단합니다.');
    const stripped = stripOurContextBlock(newRaw);
    const newOriginal = stripped.found ? stripped.text : newRaw;
    active = fitItemsToCarrierLimits(room, newOriginal, active);
    if (!active.length) {
      room.pending = null; clearPendingBackup(room.chatId); await saveRoom(room);
      if (room.chatId === state.currentChatId) { state.currentRoom = room; notifyInjectionEnded(room, 'empty'); renderModalIfOpen(); }
      return;
    }
    const activeLogIds = new Set(active.filter(i => i.sourceSlotId === 'logSummary' || i.group === 'log-auto' || i.slotId === 'logSummary').map(i => i.slotId));
    const activeLoreIds = new Set(active.filter(i => i.group === 'lore').map(i => i.slotId));
    const activeLoreById = new Map(active.filter(i => i.group === 'lore').map(i => [i.slotId, i]));
    p.items = (p.items || []).filter(i => i.group === 'lore' ? activeLoreIds.has(i.slotId) : !(i.sourceSlotId === 'logSummary' || i.group === 'log-auto' || i.slotId === 'logSummary') || activeLogIds.has(i.slotId)).map(i => i.group === 'lore' ? (activeLoreById.get(i.slotId) || i) : i);
    const contextBlock = buildContextBlockFromItems(active);
    if (!contextBlock) throw new Error('유지할 활성 컨텍스트가 없어 자동 유지를 중단합니다.');
    const nextInjected = buildInjectedMessage(newOriginal, contextBlock);
    const requestMetrics = carrierRequestMetrics(nextInjected);
    const maxChars = Number(room.maxChars) || APP.defaultMaxChars;
    if (nextInjected.length > maxChars || requestMetrics.payloadBytes > APP.safeCarrierPayloadBytes) {
      throw new Error(`새 AI 응답 + 숨김 컨텍스트가 주입 안전선을 넘어 이번 carrier 이동을 보류했습니다. 설정과 계속 유지 항목은 보존하며 다음 답변에서 다시 시도합니다. ${formatCount(nextInjected.length)} / ${formatCount(maxChars)}자 · UTF-8 요청 ${formatCount(requestMetrics.payloadBytes)} / ${formatCount(APP.safeCarrierPayloadBytes)}바이트`);
    }

    const nextPending = { ...p, messageId: newId, originalText: newOriginal, baselineAssistantId: newId,
      armedAt: Date.now(), carrierArmedAt: Date.now(), originalChars: newOriginal.length, carrierChars: nextInjected.length,
      carrierMessageBytes:requestMetrics.messageBytes, carrierPayloadBytes:requestMetrics.payloadBytes,
      verified: false, verifiedAt: null, serverChars: 0, logRecallRevision: APP.logRecallRevision, contextBlock, injectedChars: contextBlock.length, items: p.items };
    delete nextPending.reanchorRetry;
    stampVerifiedPendingSnapshot(nextPending, active, contextBlock);
    if (rerollMove) delete nextPending.reroll;

    await patchMessage(apiChatIdOf(room), newId, nextInjected);
    const verification = await verifyInjectedCarrier(room, nextPending, nextInjected);
    if (!verification.verified) {
      try {
        await restoreCarrierOnly(room, nextPending);
      } catch (rollbackError) {
        room.pending = nextPending;
        savePendingBackup(room.chatId, nextPending);
        await saveRoom(room);
        throw new Error(`새 carrier 검증과 원문 롤백 확인에 실패했습니다. 복구 정보는 유지했습니다: ${rollbackError.message}`);
      }
      throw new Error('새 carrier 서버 검증에 실패해 새 AI 원문으로 안전 복원했습니다. 설정과 계속 유지 항목은 보존하며 자동으로 다시 시도합니다.');
    }
    nextPending.verified = true; nextPending.verifiedAt = Date.now(); nextPending.serverChars = verification.serverChars;
    stampVerifiedPendingSnapshot(nextPending, active, contextBlock);
    room.pending = nextPending; savePendingBackup(room.chatId, nextPending); await saveRoom(room);
    if (room.chatId === state.currentChatId) {
      state.currentRoom = room;
      sanitizeRenderedContextSoon();
      const autoBits = [];
      if (autoResult?.detected?.length) autoBits.push(`캐릭터 ${autoResult.detected.map(x => x.slot.title).join(', ')}`);
      if (autoResult?.itemDetected?.length) autoBits.push(`중요 물품 ${autoResult.itemDetected.map(x => x.slot.title).join(', ')}`);
      if (autoResult?.logAdded) autoBits.push(`관련로그 ${autoResult.logAdded}개`);
      notify(`${rerollMove ? '리롤 컨텍스트 유지 완료' : '컨텍스트 자동 이동 완료'} ✓ · ${active.length}개 항목 유지 중${autoBits.length ? ` · 자동호출 ${autoBits.join(' / ')}` : ''}`, 'context-move', autoBits.length ? 4800 : 3200);
      renderModalIfOpen();
    }
  }

  function reanchorAfterResponse(room, latestAssistant, options = {}) {
    return queuePendingCarrierOperation(room, () => reanchorAfterResponseNow(room, latestAssistant, options));
  }

  async function checkPendingRoom(room) {
    const p = room.pending;
    if (!p) return;

    const recent = await fetchRecentMessages(apiChatIdOf(room), 20);
    const latestAssistant = recent.find(m => messageRoleOf(m) === 'assistant');
    const latestAssistantId = messageIdOf(latestAssistant);
    if (!latestAssistantId) return;
    const recovery = p.reanchorRetry && typeof p.reanchorRetry === 'object' ? p.reanchorRetry : null;
    const retryingSameAssistant = !!recovery && String(recovery.failedMessageId || '') === String(latestAssistantId);
    if (retryingSameAssistant) {
      if (recovery.holdUntilNextAssistant) return;
      if (Number(recovery.nextRetryAt || 0) > Date.now()) return;
      if (Number(recovery.attempts || 0) >= 3) return;
    }

    if (p.reroll) {
      const reroll = p.reroll;
      const timedOut = Date.now() - Number(reroll.startedAt || 0) >= APP.rerollRecoveryMs;
      // 재생성 도중에는 대상 답변이 잠시 사라져 임시 carrier가 최신 AI로 보일 수 있습니다.
      // 이때는 완료된 답변으로 오인해 같은 메시지에 다시 주입하지 않습니다.
      if (String(latestAssistantId) === String(p.messageId)) {
        if (timedOut) {
          delete p.reroll;
          p.baselineAssistantId = p.messageId;
          savePendingBackup(room.chatId, p);
          await saveRoom(room);
          if (room.chatId === state.currentChatId) state.currentRoom = room;
          notify('리롤 완료 답변을 확인하지 못해 이전 AI 답변에서 컨텍스트 유지를 계속합니다.', 'warn', 5600);
        }
        return;
      }

      const latestRaw = messageTextOf(latestAssistant);
      const latestOriginal = stripOurContextBlock(latestRaw).text || latestRaw;
      const sourceUnchanged = String(latestAssistantId) === String(reroll.sourceMessageId)
        && normalizeLineBreaks(latestOriginal) === normalizeLineBreaks(String(reroll.sourceOriginalText || ''));
      if (sourceUnchanged && !timedOut) return;

      // 스트리밍 중간 내용을 완료 답변으로 잡지 않도록 같은 서버 원문이 잠시 유지되는지 한 번 확인합니다.
      const signature = `${String(latestAssistantId)}:${latestOriginal.length}:${simpleHash(latestOriginal)}`;
      if (!timedOut && (reroll.observedSignature !== signature || Date.now() - Number(reroll.observedAt || 0) < 1000)) {
        if (reroll.observedSignature !== signature) {
          reroll.observedSignature = signature;
          reroll.observedAt = Date.now();
          savePendingBackup(room.chatId, p);
          await saveRoom(room);
        }
        scheduleRecovery(1200);
        return;
      }

      await reanchorAfterResponse(room, latestAssistant, { countTurn: false, reason: 'reroll' });
      return;
    }

    if (latestAssistantId === p.baselineAssistantId) {
      // v0.8.9에서 이어진 활성 주입은 새 버전에서 한 번만 로그 후보를 다시 계산합니다.
      // 따라서 업데이트 직후에도 사용자가 로그 칸을 다시 건드리지 않아도 최신 날짜가 반영됩니다.
      if (Number(p.logRecallRevision || 0) < APP.logRecallRevision) {
        replacePendingLogItems(room);
        refreshPendingLoreItems(room, room.autoRecallContextText || '');
        await syncPendingCarrier(room, 'log-recall-upgrade');
        if (room.pending) {
          room.pending.logRecallRevision = APP.logRecallRevision;
          savePendingBackup(room.chatId, room.pending);
          await saveRoom(room);
        }
        return;
      }
      // carrier 무결성 확인은 매 폴링마다 하지 않습니다. 기존 코드는 활성 주입 중
      // 2초마다 최근 메시지 + carrier 본문을 연속 조회해 탭과 서버 모두에 부담을 줬습니다.
      const verifyKey = `${room.chatId}:${p.messageId}`;
      const lastVerifiedAt = state.lastCarrierVerifyKey === verifyKey
        ? Number(state.lastCarrierVerifyAt || 0)
        : Number(p.verifiedAt || 0);
      if (Date.now() - lastVerifiedAt < APP.carrierVerifyMs) return;
      state.lastCarrierVerifyKey = verifyKey;
      state.lastCarrierVerifyAt = Date.now();
      // 새로고침/렌더링 재구성 후에도 현재 carrier의 서버 주입이 살아있는지 주기적으로 확인합니다.
      try {
        await queuePendingCarrierOperation(room, async () => {
          if (room.pending !== p) return;
          const carrier = await fetchMessage(apiChatIdOf(room), p.messageId);
          const carrierText = messageTextOf(carrier);
          const carrierHasContext = !!carrierText && stripOurContextBlock(carrierText).found;
          if (carrierHasContext && p.reanchorRetry) {
            delete p.reanchorRetry;
            p.verified = true;
            p.verifiedAt = Date.now();
            savePendingBackup(room.chatId, p);
            await saveRoom(room);
          } else if (carrierText && !carrierHasContext) {
            const active = fitItemsToCarrierLimits(room, carrierText, activePendingItems(p));
            const activeLogIds = new Set(active.filter(i => i.sourceSlotId === 'logSummary' || i.group === 'log-auto' || i.slotId === 'logSummary').map(i => i.slotId));
            p.items = (p.items || []).filter(i => !(i.sourceSlotId === 'logSummary' || i.group === 'log-auto' || i.slotId === 'logSummary') || activeLogIds.has(i.slotId));
            const contextBlock = buildContextBlockFromItems(active);
            if (contextBlock) {
              // Refiner가 마커 없이 최신 교정문을 저장했을 수 있으므로 현재 서버 본문을 새 원문으로 채택합니다.
              p.originalText = carrierText;
              const injected = buildInjectedMessage(carrierText, contextBlock);
              const requestMetrics = assertCarrierRequestWithinLimits(room, injected, 'carrier 재주입 총 길이');
              await patchMessage(apiChatIdOf(room), p.messageId, injected);
              const reapplied = await verifyInjectedCarrier(room, p, injected, 3);
              if (!reapplied.verified) throw new Error('carrier 재주입 서버 검증 실패');
              p.contextBlock = contextBlock; p.carrierChars = injected.length; p.carrierMessageBytes = requestMetrics.messageBytes; p.carrierPayloadBytes = requestMetrics.payloadBytes; p.serverChars = reapplied.serverChars;
              p.verified = true; p.verifiedAt = Date.now();
              delete p.reanchorRetry;
              savePendingBackup(room.chatId, p); await saveRoom(room);
            }
          }
        });
      } catch (e) { console.warn('[RP매니저] carrier verify/reapply failed:', room.chatId, e); }
      return;
    }

    if (latestAssistantId !== p.baselineAssistantId) {
      const beforeReanchor = { ...p, items: clonePendingItems(p.items) };
      try {
        await reanchorAfterResponse(room, latestAssistant, retryingSameAssistant ? { countTurn:false, reason:'recovery' } : {});
      } catch (e) {
        console.warn('[RP매니저] reanchor failed:', room.chatId, e);
        // 실패 시 이전/새 carrier 양쪽이 깨끗한지 확인합니다. 네트워크 오류로 확인하지 못했다면
        // pending과 이중 백업을 남겨 다음 recoveryTick 또는 수동 해제로 재시도할 수 있게 합니다.
        let cleanupConfirmed = true;
        for (const messageId of [...new Set([beforeReanchor.messageId, latestAssistantId].filter(Boolean))]) {
          try { await restoreCarrierOnly(room, { ...beforeReanchor, messageId }); }
          catch (cleanupError) {
            cleanupConfirmed = false;
            console.warn('[RP매니저] reanchor cleanup not confirmed:', messageId, cleanupError);
          }
        }
        const failedCurrent = room.pending;
        const failedItems = clonePendingItems(failedCurrent?.items || p.items || beforeReanchor.items);
        const activeAfterFailure = activePendingItems({ items:failedItems });
        if (activeAfterFailure.length) {
          const attempts = retryingSameAssistant ? Number(recovery?.attempts || 0) + 1 : 1;
          const holdUntilNextAssistant = /안전선을 넘어/.test(String(e.message || '')) || attempts >= 3;
          const preserved = cleanupConfirmed
            ? { ...beforeReanchor, items:failedItems }
            : { ...(failedCurrent || beforeReanchor), items:failedItems };
          preserved.verified = false;
          preserved.verifiedAt = null;
          preserved.reanchorRetry = {
            failedMessageId:String(latestAssistantId),
            failedAt:Date.now(),
            attempts,
            nextRetryAt:Date.now() + 15000,
            holdUntilNextAssistant,
            reason:String(e.message || 'carrier 자동 이동 실패'),
          };
          room.pending = preserved;
          savePendingBackup(room.chatId, preserved);
        } else if (cleanupConfirmed) {
          room.pending = null;
          clearPendingBackup(room.chatId);
        } else {
          room.pending = failedCurrent || beforeReanchor;
          savePendingBackup(room.chatId, room.pending);
        }
        await saveRoom(room);
        if (room.chatId === state.currentChatId) {
          state.currentRoom = room;
          if (room.pending) notify(`자동 이동 보류 · 계속 유지 설정과 주입 항목을 보존했습니다. ${room.pending.reanchorRetry?.holdUntilNextAssistant ? '다음 AI 답변에서 다시 시도합니다.' : '잠시 후 자동으로 다시 시도합니다.'} ${e.message}`, 'warn', 8500);
          else if (cleanupConfirmed) notifyInjectionEnded(room, 'error', e.message);
          else notify(`자동 이동 오류 · 복구 확인 전이라 주입 백업을 유지했습니다: ${e.message}`, 'error', 7500);
          renderModalIfOpen();
        }
      }
    }
  }

  async function recoveryTick() {
    if (state.recovering || state.rerollPreparing || !state.db) return;
    state.recovering = true;
    try {
      // 화면에 없는 모든 방을 getAll()로 복제하지 않습니다. 현재 보고 있는 방만
      // 검사하고, 다른 방의 pending은 그 방에 다시 들어갔을 때 이어서 복구합니다.
      const room = state.currentRoom;
      if (!room || room.chatId !== state.currentChatId) return;
      try {
        normalizeRoomSlots(room);
        // 자동 캐릭터·중요 물품 감지는 주입 전에도 현재 방에서 동작해 다음 주입 준비를 해둡니다.
        const hasAutoItems = room.autoItemDetection && (room.slots || []).some(slot => slot.group === 'item' && !slot.autoExcluded && String(slot.content || '').trim());
        if (!room.pending && (room.autoCharacterDetection || room.autoLogRecallEnabled || hasAutoItems)) {
          const lastScanAt = Number(state.idleAutoScanAt.get(room.chatId) || 0);
          if (Date.now() - lastScanAt < APP.idleAutoScanMs) return;
          state.idleAutoScanAt.set(room.chatId, Date.now());
          const recent = await fetchRecentMessages(apiChatIdOf(room), APP.autoScanMessageLimit);
          const auto = await refreshAutomaticMemories(room, recent);
          if (auto.detected?.length && room.chatId === state.currentChatId) {
            notify(`RP 등장 캐릭터 자동 선택 · ${auto.detected.map(x => x.slot.title).join(', ')} 현재 주입 활성화`, 'success', 3800);
            renderModalIfOpen();
          }
          if (auto.itemDetected?.length && room.chatId === state.currentChatId) {
            notify(`중요 물품 언급 감지 · ${auto.itemDetected.map(x => x.slot.title).join(', ')} 현재 주입 활성화`, 'success', 4200);
            renderModalIfOpen();
          }
          return;
        }
        if (!room.pending) return;
        if (!Array.isArray(room.pending.items) || !room.pending.items.length) {
          const legacyTotal = room.pending.totalTurns == null ? APP.defaultRetentionTurns : normalizeRetentionTurns(room.pending.totalTurns);
          const legacyUsed = Number(room.pending.usedTurns || 0);
          room.pending.items = selectedSlots(room).map(slot => ({ slotId: slot.id, title: slot.title, group: slot.group, content: String(slot.content || ''), totalTurns: normalizeRetentionTurns(slot.retentionTurns ?? legacyTotal), usedTurns: legacyUsed }));
        }
        await checkPendingRoom(room);
      } catch (e) {
        console.warn('[RP매니저] pending check failed:', room.chatId, e);
      }
    } finally {
      state.recovering = false;
    }
  }

  function nextRecoveryDelay() {
    if (document.hidden) return APP.backgroundPollMs;
    if (state.currentRoom?.pending) return APP.activePollMs;
    if (state.currentRoom?.autoCharacterDetection || state.currentRoom?.autoLogRecallEnabled) return APP.idleAutoScanMs;
    return APP.idlePollMs;
  }

  function scheduleRecovery(delay = nextRecoveryDelay()) {
    clearTimeout(state.recoveryTimer);
    state.recoveryTimer = setTimeout(async () => {
      state.recoveryTimer = null;
      try { await recoveryTick(); }
      catch (e) { console.warn('[RP매니저] recovery loop failed', e); }
      scheduleRecovery();
    }, Math.max(0, Number(delay) || 0));
  }

  // ---------------------------------------------------------------------------
  // Render-only sanitizer: 서버 raw는 유지하고 일반 채팅 화면에서만 RP 블록 숨김
  // ---------------------------------------------------------------------------

  function cleanupRenderedMarkerArtifacts(root) {
    if (!root) return;
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_COMMENT);
    const removeNodes = []; let n;
    while ((n = walker.nextNode())) {
      if (n.nodeType === Node.COMMENT_NODE) {
        if (String(n.nodeValue || '').includes('RP_CONTEXT_MANAGER')) removeNodes.push(n);
        continue;
      }
      if (n.parentElement?.closest('#rpcm-overlay,#rpcm-toast-wrap,#rpcm-notice-popups,#rpcm-lib-dialog-backdrop')) continue;
      const before = n.nodeValue || '';
      // 🪽위시 RP Manager는 자기 마커가 포함된 흔적만 정리합니다.
      // 빈 <!----> 자체는 Crack/다른 확장이 사용할 수 있으므로 전역 삭제하지 않습니다.
      const beforeNorm = String(before || '');
      const after = /RP_CONTEXT_MANAGER(?:_START|_END)?/i.test(beforeNorm)
        ? beforeNorm.replace(/\?<!--?[^\n]*RP_CONTEXT_MANAGER[^\n]*>?/gi, '').replace(/^[\\\s]+$/g, m => m.includes('\\') ? m.replace(/\\/g, '') : m)
        : beforeNorm;
      if (after !== before) n.nodeValue = after;
    }
    removeNodes.forEach(x => x.remove());
  }

  function sanitizeOneRenderedBlock(startNode) {
    if (!startNode || startNode.nodeType !== Node.TEXT_NODE) return false;
    if (startNode.parentElement?.closest('#rpcm-overlay,#rpcm-toast-wrap,#rpcm-notice-popups,#rpcm-lib-dialog-backdrop')) return false;
    let root = startNode.parentElement;
    for (let i = 0; root && i < 12; i++, root = root.parentElement) {
      if (root.id === 'rpcm-overlay' || root.id === 'rpcm-toast-wrap' || root.id === 'rpcm-notice-popups' || root.id === 'rpcm-lib-dialog-backdrop') return false;
      const text = root.textContent || '';
      if (!text.includes('RP_CONTEXT_MANAGER_END')) continue;

      const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
      const nodes = []; let joined = ''; let n;
      while ((n = walker.nextNode())) {
        if (n.parentElement?.closest('#rpcm-overlay,#rpcm-toast-wrap,#rpcm-notice-popups,#rpcm-lib-dialog-backdrop')) continue;
        nodes.push({ node: n, start: joined.length, end: joined.length + n.nodeValue.length });
        joined += n.nodeValue;
      }
      let start = joined.indexOf('<!--RP_CONTEXT_MANAGER_START');
      if (start < 0) start = joined.indexOf('RP_CONTEXT_MANAGER_START');
      let end = joined.indexOf('RP_CONTEXT_MANAGER_END-->', start >= 0 ? start : 0);
      let endLen = 'RP_CONTEXT_MANAGER_END-->'.length;
      if (end < 0) { end = joined.indexOf('RP_CONTEXT_MANAGER_END', start >= 0 ? start : 0); endLen = 'RP_CONTEXT_MANAGER_END'.length; }
      if (start < 0 || end < 0) continue;
      // Markdown renderer가 HTML 주석 앞의 escape 백슬래시를 따로 남기는 경우까지 같이 제거합니다.
      if (start > 0 && joined[start - 1] === '\\') start--;
      const cutEnd = end + endLen;

      for (const part of nodes) {
        if (part.end <= start || part.start >= cutEnd) continue;
        const localStart = Math.max(0, start - part.start);
        const localEnd = Math.min(part.node.nodeValue.length, cutEnd - part.start);
        part.node.nodeValue = part.node.nodeValue.slice(0, localStart) + part.node.nodeValue.slice(localEnd);
      }
      cleanupRenderedMarkerArtifacts(root);
      return true;
    }
    return false;
  }

  function isManagerUiNode(node) {
    const element=node?.nodeType===Node.ELEMENT_NODE?node:node?.parentElement;
    return !!element?.closest?.('[id^="rpcm-"],[id^="wish-rpcore-"],script,style,textarea');
  }
  function renderedContextWalker(root) {
    return document.createTreeWalker(root,NodeFilter.SHOW_ELEMENT|NodeFilter.SHOW_TEXT|NodeFilter.SHOW_COMMENT,{
      acceptNode:node=>node.nodeType===Node.ELEMENT_NODE?(isManagerUiNode(node)?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_SKIP):NodeFilter.FILTER_ACCEPT
    });
  }
  function sanitizeRenderedContextBlocks(root = document.body) {
    if (!root || isManagerUiNode(root)) return;
    const walker = renderedContextWalker(root);
    const starts = [];
    const comments = [];
    let node;
    while ((node = walker.nextNode())) {
      const v = node.nodeValue || '';
      if (!v.includes('RP_CONTEXT_MANAGER')) continue;
      if (node.nodeType === Node.COMMENT_NODE) {
        comments.push(node);
        continue;
      }
      if (node.parentElement?.closest('#rpcm-overlay,#rpcm-toast-wrap,#rpcm-notice-popups,#rpcm-lib-dialog-backdrop')) continue;
      if (v.includes('RP_CONTEXT_MANAGER_START')) starts.push(node);
    }
    // Markdown이 실제 HTML 주석으로 만든 경우에는 4만 자짜리 Comment 노드 자체를 제거합니다.
    comments.forEach(comment => comment.remove());
    for (const start of starts) sanitizeOneRenderedBlock(start);
  }

  function sanitizeRenderedContextSoon() {
    clearTimeout(state.domSanitizeTimer);
    state.domSanitizeTimer = setTimeout(() => sanitizeRenderedContextBlocks(document.body || document.documentElement || document), 0);
  }

  function nodeContainsRenderedContextMarker(node) {
    if (!node || isManagerUiNode(node)) return false;
    if (node.nodeType === Node.TEXT_NODE || node.nodeType === Node.COMMENT_NODE) {
      return String(node.nodeValue || '').includes('RP_CONTEXT_MANAGER');
    }
    if (!node.ownerDocument && node !== document) return false;
    const walker = renderedContextWalker(node);
    let child;
    while ((child = walker.nextNode())) {
      if (String(child.nodeValue || '').includes('RP_CONTEXT_MANAGER')) return true;
    }
    return false;
  }

  function startRenderedContextObserver() {
    if (document.hidden) return;
    const target = document.documentElement || document;
    if (!state.domObserver) {
      state.domObserver = new MutationObserver((mutations) => {
        if (state.domSanitizing || document.hidden) return;
        const roots = new Set();
        for (const m of mutations) {
          if (isManagerUiNode(m.target)) continue;
          if (m.type === 'characterData') {
            if (nodeContainsRenderedContextMarker(m.target)) roots.add(m.target.parentElement || m.target);
            continue;
          }
          // mutation.target의 textContent는 채팅 전체 문자열을 새로 만들 수 있으므로 읽지 않습니다.
          // 실제로 추가된 노드만 검사해 스트리밍 중 반복되는 전체 DOM 직렬화를 막습니다.
          for (const added of (m.addedNodes || [])) {
            if (!nodeContainsRenderedContextMarker(added)) continue;
            if (added.nodeType === Node.COMMENT_NODE) {
              added.remove();
            } else {
              roots.add(added.nodeType === Node.ELEMENT_NODE ? added : (added.parentElement || m.target));
            }
          }
        }
        if (!roots.size) return;
        state.domSanitizing = true;
        try {
          for (const root of roots) sanitizeRenderedContextBlocks(root);
        } finally {
          state.domSanitizing = false;
        }
      });
    }
    if (!state.domObserverActive) {
      state.domObserver.observe(target, { childList: true, subtree: true, characterData: true });
      state.domObserverActive = true;
    }
    sanitizeRenderedContextBlocks(document.body || document.documentElement || document);
  }

  function pauseRenderedContextObserver() {
    if (!state.domObserver || !state.domObserverActive) return;
    state.domObserver.disconnect();
    state.domObserverActive = false;
  }

  // ---------------------------------------------------------------------------
  // Mobile viewport / layout helpers
  // ---------------------------------------------------------------------------

  function isMobileManagerLayout() {
    try {
      const narrow = window.matchMedia('(max-width: 680px)').matches;
      const touchTablet = window.matchMedia('(pointer: coarse) and (max-width: 1024px)').matches;
      return narrow || touchTablet;
    } catch (_) { return window.innerWidth <= 680; }
  }

  function updateViewportMetrics() {
    const vv = window.visualViewport;
    const height = Math.max(1, Math.round(vv?.height || window.innerHeight || document.documentElement.clientHeight || 1));
    const top = Math.max(0, Math.round(vv?.offsetTop || 0));
    const root = document.documentElement;
    if (!root) return;
    const mobile = isMobileManagerLayout();
    root.classList.toggle('rpcm-mobile-layout', mobile);
    if (!mobile) state.mobileViewportMaxHeight = 0;
    else if (height > state.mobileViewportMaxHeight) state.mobileViewportMaxHeight = height;
    root.style.setProperty('--rpcm-vvh', `${height}px`);
    root.style.setProperty('--rpcm-vv-top', `${top}px`);
    const activeInput = document.activeElement;
    const typingFocus = !!activeInput?.matches?.('textarea,input:not([type="checkbox"]):not([type="radio"]):not([type="file"]):not([type="hidden"])') && !!activeInput.closest?.('#rpcm-overlay,#rpcm-detached-backdrop,#rpcm-lib-dialog-backdrop,#rpcm-library-manager-backdrop,#rpcm-log-dialog-backdrop,#rpcm-story-dialog-backdrop,#rpcm-story-view-backdrop,#rpcm-dup-dialog-backdrop,#rpcm-import-backdrop,#rpcm-ai-backdrop');
    const keyboardOpen = mobile && typingFocus && state.mobileViewportMaxHeight > 0 && height < state.mobileViewportMaxHeight * .82;
    root.classList.toggle('rpcm-mobile-keyboard-open', keyboardOpen);
  }

  function bindViewportMetrics() {
    updateViewportMetrics();
    if (state.viewportMetricsBound) return;
    state.viewportMetricsBound = true;
    const refresh = () => {
      updateViewportMetrics();
      // 세로/가로 전환으로 680px 경계를 넘나들 때 진입 버튼도 즉시 재배치합니다.
      ensureManagerButton();
    };
    window.addEventListener('resize', refresh, { passive: true });
    window.addEventListener('orientationchange', () => {
      state.mobileViewportMaxHeight = 0;
      setTimeout(refresh, 80);
      setTimeout(refresh, 320);
    }, { passive: true });
    if (window.visualViewport) {
      window.visualViewport.addEventListener('resize', updateViewportMetrics, { passive: true });
      window.visualViewport.addEventListener('scroll', updateViewportMetrics, { passive: true });
    }
  }

