  GM_addStyle('\n#rpcm-ltm-parts-dialog{position:fixed;inset:0;z-index:2147483647;background:rgba(36,26,36,.48);display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;font-family:inherit}\n#rpcm-ltm-parts-dialog .rpcm-ltm-parts-panel{box-sizing:border-box;width:min(560px,100%);max-height:min(85vh,740px);display:flex;flex-direction:column;overflow:hidden;border:1px solid var(--wish-line,#ead7e3);border-radius:18px;background:var(--wish-card,#fff);color:var(--wish-fg,#322b32);box-shadow:0 18px 55px rgba(38,22,35,.18)}\n#rpcm-ltm-parts-dialog .rpcm-ltm-parts-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;padding:22px 24px 16px;border-bottom:1px solid var(--wish-line,#ead7e3)}\n#rpcm-ltm-parts-dialog .rpcm-ltm-parts-head small{font-size:11px;color:var(--wish-accent-strong,#a24d7d)}\n#rpcm-ltm-parts-dialog h2{font-size:19px;font-weight:650;margin:4px 0 6px;line-height:1.4}\n#rpcm-ltm-parts-dialog p{font-size:13px;line-height:1.6;margin:0;color:var(--wish-fg-2,#827681)}\n#rpcm-ltm-parts-dialog button{font:inherit;cursor:pointer;border:1px solid var(--wish-line,#ead7e3);background:var(--wish-card,#fff);color:var(--wish-fg,#322b32);border-radius:10px;min-height:36px;padding:8px 13px;white-space:nowrap}\n#rpcm-ltm-parts-dialog [data-ltm-close]{border:0;background:transparent;min-width:30px;padding:0;font-size:24px;color:var(--wish-muted,#9b8794)}\n#rpcm-ltm-parts-dialog .rpcm-ltm-parts-content{padding:18px 24px;overflow:auto}\n#rpcm-ltm-parts-dialog .rpcm-ltm-parts-info{border-radius:11px;background:var(--wish-accent-soft,#fff1f7);padding:12px 14px;font-size:12px;line-height:1.7;color:var(--wish-fg-2,#796575);margin-bottom:12px}\n#rpcm-ltm-parts-dialog .rpcm-ltm-parts-list{display:grid;gap:8px}\n#rpcm-ltm-parts-dialog .rpcm-ltm-parts-row{display:flex;justify-content:space-between;align-items:center;gap:12px;border:1px solid var(--wish-line,#ead7e3);border-radius:11px;padding:12px 14px;background:var(--wish-card,#fff)}\n#rpcm-ltm-parts-dialog .rpcm-ltm-parts-meta{display:flex;flex-direction:column;gap:3px}\n#rpcm-ltm-parts-dialog .rpcm-ltm-parts-meta strong{font-size:14px}\n#rpcm-ltm-parts-dialog .rpcm-ltm-parts-meta small{font-size:12px;color:var(--wish-muted,#9b8794)}\n#rpcm-ltm-parts-dialog .rpcm-ltm-parts-row button{background:var(--wish-accent-soft,#fff1f7);color:var(--wish-accent-strong,#a24d7d);border-color:var(--wish-accent-line,#efbfd6);font-size:12px}\n#rpcm-ltm-parts-dialog .rpcm-ltm-parts-footer{display:flex;justify-content:flex-end;gap:8px;padding:14px 24px;border-top:1px solid var(--wish-line,#ead7e3)}\n#rpcm-ltm-parts-dialog .rpcm-ltm-parts-primary{background:var(--wish-accent,#bc6596)!important;color:white!important;border-color:transparent!important;font-weight:600}\n@media(max-width:600px){#rpcm-ltm-parts-dialog{padding:10px}#rpcm-ltm-parts-dialog .rpcm-ltm-parts-head{padding:18px 16px 14px}#rpcm-ltm-parts-dialog .rpcm-ltm-parts-content{padding:14px 16px}#rpcm-ltm-parts-dialog .rpcm-ltm-parts-footer{padding:12px 16px;flex-wrap:wrap}#rpcm-ltm-parts-dialog .rpcm-ltm-parts-primary{flex:1}}\n');
  function longTermZipParts(parts,kind){
    const encoder=new TextEncoder(),chunks=[],central=[];
    const u16=n=>[n&255,(n>>>8)&255],u32=n=>[n&255,(n>>>8)&255,(n>>>16)&255,(n>>>24)&255];
    const crc32=bytes=>{let c=0xffffffff;for(const byte of bytes){c^=byte;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0);}return(c^0xffffffff)>>>0;};
    let offset=0;
    parts.forEach((part,i)=>{
      const filename=`RP_장기기억_${kind==='first'?'1차':'2차'}_${i+1}of${parts.length}.txt`;
      const name=encoder.encode(filename),data=encoder.encode(part),crc=crc32(data),size=data.length;
      const local=new Uint8Array([...u32(0x04034b50),...u16(20),...u16(0x0800),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(size),...u32(size),...u16(name.length),...u16(0)]);
      chunks.push(local,name,data);
      const record=new Uint8Array([...u32(0x02014b50),...u16(20),...u16(20),...u16(0x0800),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(size),...u32(size),...u16(name.length),...u16(0),...u16(0),...u16(0),...u16(0),...u32(0),...u32(offset)]);
      central.push(record,name);offset+=local.length+name.length+data.length;
    });
    const centralSize=central.reduce((n,x)=>n+x.length,0);
    const end=new Uint8Array([...u32(0x06054b50),...u16(0),...u16(0),...u16(parts.length),...u16(parts.length),...u32(centralSize),...u32(offset),...u16(0)]);
    return new Blob([...chunks,...central,end],{type:'application/zip'});
  }
  function longTermDownloadAllParts(parts,kind){
    const blob=longTermZipParts(parts,kind),url=URL.createObjectURL(blob);
    const a=document.createElement('a');a.href=url;a.download=`RP_장기기억_${kind==='first'?'1차':'2차'}_${parts.length}개_전체.zip`;
    document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
  }
