      copy.onclick=async()=>{
        try{await navigator.clipboard.writeText(part);}
        catch(_){const t=document.createElement('textarea');t.value=part;t.style.position='fixed';t.style.opacity='0';document.body.appendChild(t);t.select();const ok=document.execCommand('copy');t.remove();if(!ok){notify('복사 실패 · 브라우저 클립보드 권한을 확인해 주세요.','error');return;}}
        copy.textContent='복사 완료 ✓';setTimeout(()=>{if(copy.isConnected)copy.textContent='TXT 복사';},1800);
      };
      line.append(meta,copy);host.appendChild(line);
