      if(!id||seen.has(id)||!item||!longTermNative(item,room))throw new Error(`보호되었거나 중복된 native ID: ${id}`);
      if(!['patch','delete'].includes(operation.op))throw new Error('허용되지 않은 native 작업입니다.');
